  '16;31;0;122\nT;0;18:98:1:قَالَ هَٰذَا رَحۡمَةࣱ مِّن رَّبِّيۖ فَإِذَا جَآءَ وَعۡدُ رَبِّي جَعَلَهُۥ دَكَّآءَۖ وَكَانَ وَعۡدُ رَبِّي\nT;0;18:98:2:حَقࣰّا¦18:99:1:۞ وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذࣲ يَمُوجُ فِي بَعۡضࣲۖ وَنُفِخَ فِي ٱلصُّورِ\nT;0;18:99:2:فَجَمَعۡنَٰهُمۡ جَمۡعࣰا¦18:100:3:وَعَرَضۡنَا جَهَنَّمَ يَوۡمَئِذࣲ لِّلۡكَٰفِرِينَ عَرۡضًا¦18:101:1:ٱلَّذِينَ\nT;0;18:101:2:كَانَتۡ أَعۡيُنُهُمۡ فِي غِطَآءٍ عَن ذِكۡرِي وَكَانُواْ لَا يَسۡتَطِيعُونَ سَمۡعًا\nT;0;18:102:1:أَفَحَسِبَ ٱلَّذِينَ كَفَرُوٓاْ أَن يَتَّخِذُواْ عِبَادِي مِن دُونِيٓ أَوۡلِيَآءَۚ إِنَّآ\nT;0;18:102:2:أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ نُزُلࣰا¦18:103:3:قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا\nT;0;18:104:1:ٱلَّذِينَ ضَلَّ سَعۡيُهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ\nT;0;18:104:2:صُنۡعًا¦18:105:1:أُوْلَٰٓئِكَ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ رَبِّهِمۡ وَلِقَآئِهِۦ فَحَبِطَتۡ\nT;0;18:105:2:أَعۡمَٰلُهُمۡ فَلَا نُقِيمُ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ وَزۡنࣰا¦18:106:1:ذَٰلِكَ جَزَآؤُهُمۡ جَهَنَّمُ\nT;0;18:106:2:بِمَا كَفَرُواْ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَرُسُلِي هُزُوًا¦18:107:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ\nT;0;18:107:2:ٱلصَّٰلِحَٰتِ كَانَتۡ لَهُمۡ جَنَّٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا¦18:108:1:خَٰلِدِينَ فِيهَا\nT;0;18:108:2:لَا يَبۡغُونَ عَنۡهَا حِوَلࣰا¦18:109:1:قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادࣰا لِّكَلِمَٰتِ رَبِّي لَنَفِدَ\nT;0;18:109:2:ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَٰتُ رَبِّي وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدࣰا¦18:110:1:قُلۡ إِنَّمَآ\nT;0;18:110:0:أَنَا۠ بَشَرࣱ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱۖ فَمَن كَانَ يَرۡجُواْ\nT;2;18:110:2:لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلࣰا صَٰلِحࣰا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا',
  '16;31;1;\nH;19\nB;19\nT;0;19:1:3:كٓهيعٓصٓ¦19:2:3:ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ¦19:3:1:إِذۡ\nT;0;19:3:2:نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيࣰّا¦19:4:1:قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي\nT;0;19:4:2:وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبࣰا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيࣰّا\nT;0;19:5:1:وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي\nT;0;19:5:2:عَاقِرࣰا فَهَبۡ لِي مِن لَّدُنكَ وَلِيࣰّا¦19:6:1:يَرِثُنِي وَيَرِثُ مِنۡ\nT;0;19:6:2:ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيࣰّا¦19:7:1:يَٰزَكَرِيَّآ إِنَّا\nT;0;19:7:2:نُبَشِّرُكَ بِغُلَٰمٍ ٱسۡمُهُۥ يَحۡيَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِيࣰّا\nT;0;19:8:1:قَالَ رَبِّ أَنَّىٰ يَكُونُ لِي غُلَٰمࣱ وَكَانَتِ ٱمۡرَأَتِي عَاقِرࣰا\nT;0;19:8:2:وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِيࣰّا¦19:9:1:قَالَ كَذَٰلِكَ قَالَ\nT;0;19:9:0:رَبُّكَ هُوَ عَلَيَّ هَيِّنࣱ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ\nT;0;19:9:2:شَيۡـࣰٔا¦19:10:1:قَالَ رَبِّ ٱجۡعَل لِّيٓ ءَايَةࣰۖ قَالَ ءَايَتُكَ أَلَّا\nT;0;19:10:2:تُكَلِّمَ ٱلنَّاسَ ثَلَٰثَ لَيَالࣲ سَوِيࣰّا¦19:11:1:فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ\nT;0;19:11:2:ٱلۡمِحۡرَابِ فَأَوۡحَىٰٓ إِلَيۡهِمۡ أَن سَبِّحُواْ بُكۡرَةࣰ وَعَشِيࣰّا',
  '16;31;1;123\nT;0;19:12:3:يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةࣲۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيࣰّا\nT;0;19:13:3:وَحَنَانࣰا مِّن لَّدُنَّا وَزَكَوٰةࣰۖ وَكَانَ تَقِيࣰّا¦19:14:1:وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ\nT;0;19:14:2:يَكُن جَبَّارًا عَصِيࣰّا¦19:15:1:وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ\nT;0;19:15:2:وَيَوۡمَ يُبۡعَثُ حَيࣰّا¦19:16:1:وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مَرۡيَمَ إِذِ ٱنتَبَذَتۡ\nT;0;19:16:2:مِنۡ أَهۡلِهَا مَكَانࣰا شَرۡقِيࣰّا¦19:17:1:فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابࣰا\nT;0;19:17:2:فَأَرۡسَلۡنَآ إِلَيۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرࣰا سَوِيࣰّا¦19:18:1:قَالَتۡ إِنِّيٓ\nT;0;19:18:2:أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيࣰّا¦19:19:1:قَالَ إِنَّمَآ أَنَا۠ رَسُولُ\nT;0;19:19:2:رَبِّكِ لِأَهَبَ لَكِ غُلَٰمࣰا زَكِيࣰّا¦19:20:1:قَالَتۡ أَنَّىٰ يَكُونُ لِي\nT;0;19:20:2:غُلَٰمࣱ وَلَمۡ يَمۡسَسۡنِي بَشَرࣱ وَلَمۡ أَكُ بَغِيࣰّا¦19:21:1:قَالَ كَذَٰلِكِ\nT;0;19:21:0:قَالَ رَبُّكِ هُوَ عَلَيَّ هَيِّنࣱۖ وَلِنَجۡعَلَهُۥٓ ءَايَةࣰ لِّلنَّاسِ وَرَحۡمَةࣰ\nT;0;19:21:2:مِّنَّاۚ وَكَانَ أَمۡرࣰا مَّقۡضِيࣰّا¦19:22:1:۞ فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ\nT;0;19:22:2:مَكَانࣰا قَصِيࣰّا¦19:23:1:فَأَجَآءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ\nT;0;19:23:2:قَالَتۡ يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيࣰا مَّنسِيࣰّا\nT;0;19:24:3:فَنَادَىٰهَا مِن تَحۡتِهَآ أَلَّا تَحۡزَنِي قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِيࣰّا\nT;0;19:25:3:وَهُزِّيٓ إِلَيۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَٰقِطۡ عَلَيۡكِ رُطَبࣰا جَنِيࣰّا',
  '16;31;2;\nT;0;19:26:1:فَكُلِي وَٱشۡرَبِي وَقَرِّي عَيۡنࣰاۖ فَإِمَّا تَرَيِنَّ مِنَ ٱلۡبَشَرِ أَحَدࣰا فَقُولِيٓ\nT;0;19:26:2:إِنِّي نَذَرۡتُ لِلرَّحۡمَٰنِ صَوۡمࣰا فَلَنۡ أُكَلِّمَ ٱلۡيَوۡمَ إِنسِيࣰّا¦19:27:1:فَأَتَتۡ\nT;0;19:27:2:بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُواْ يَٰمَرۡيَمُ لَقَدۡ جِئۡتِ شَيۡـࣰٔا فَرِيࣰّا\nT;0;19:28:1:يَٰٓأُخۡتَ هَٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءࣲ وَمَا كَانَتۡ\nT;0;19:28:2:أُمُّكِ بَغِيࣰّا¦19:29:1:فَأَشَارَتۡ إِلَيۡهِۖ قَالُواْ كَيۡفَ نُكَلِّمُ مَن كَانَ فِي\nT;0;19:29:2:ٱلۡمَهۡدِ صَبِيࣰّا¦19:30:1:قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي\nT;0;19:30:2:نَبِيࣰّا¦19:31:1:وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ\nT;0;19:31:2:وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيࣰّا¦19:32:1:وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي\nT;0;19:32:2:جَبَّارࣰا شَقِيࣰّا¦19:33:1:وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ\nT;0;19:33:2:وَيَوۡمَ أُبۡعَثُ حَيࣰّا¦19:34:1:ذَٰلِكَ عِيسَى ٱبۡنُ مَرۡيَمَۖ قَوۡلَ ٱلۡحَقِّ\nT;0;19:34:2:ٱلَّذِي فِيهِ يَمۡتَرُونَ¦19:35:1:مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدࣲۖ سُبۡحَٰنَهُۥٓۚ\nT;0;19:35:2:إِذَا قَضَىٰٓ أَمۡرࣰا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ¦19:36:1:وَإِنَّ ٱللَّهَ رَبِّي وَرَبُّكُمۡ\nT;0;19:36:2:فَٱعۡبُدُوهُۚ هَٰذَا صِرَٰطࣱ مُّسۡتَقِيمࣱ¦19:37:1:فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ\nT;0;19:37:2:بَيۡنِهِمۡۖ فَوَيۡلࣱ لِّلَّذِينَ كَفَرُواْ مِن مَّشۡهَدِ يَوۡمٍ عَظِيمٍ¦19:38:1:أَسۡمِعۡ بِهِمۡ\nT;0;19:38:2:وَأَبۡصِرۡ يَوۡمَ يَأۡتُونَنَا لَٰكِنِ ٱلظَّٰلِمُونَ ٱلۡيَوۡمَ فِي ضَلَٰلࣲ مُّبِينࣲ',
  '16;31;2;\nT;0;19:39:1:وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِيَ ٱلۡأَمۡرُ وَهُمۡ فِي غَفۡلَةࣲ وَهُمۡ\nT;0;19:39:2:لَا يُؤۡمِنُونَ¦19:40:3:إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَيۡهَا وَإِلَيۡنَا يُرۡجَعُونَ\nT;0;19:41:3:وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقࣰا نَّبِيًّا¦19:42:1:إِذۡ قَالَ لِأَبِيهِ\nT;0;19:42:2:يَٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـࣰٔا\nT;0;19:43:1:يَٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطࣰا\nT;0;19:43:2:سَوِيࣰّا¦19:44:1:يَٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ\nT;0;19:44:2:عَصِيࣰّا¦19:45:1:يَٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابࣱ مِّنَ ٱلرَّحۡمَٰنِ\nT;0;19:45:2:فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيࣰّا¦19:46:1:قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي\nT;0;19:46:2:يَٰٓإِبۡرَٰهِيمُۖ لَئِن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِي مَلِيࣰّا¦19:47:1:قَالَ\nT;0;19:47:2:سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ إِنَّهُۥ كَانَ بِي حَفِيࣰّا\nT;0;19:48:1:وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ\nT;0;19:48:2:أَكُونَ بِدُعَآءِ رَبِّي شَقِيࣰّا¦19:49:1:فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن\nT;0;19:49:2:دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلࣰّا جَعَلۡنَا نَبِيࣰّا\nT;0;19:50:3:وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِيࣰّا\nT;0;19:51:3:وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مُوسَىٰٓۚ إِنَّهُۥ كَانَ مُخۡلَصࣰا وَكَانَ رَسُولࣰا نَّبِيࣰّا',
  '16;31;2;124\nT;0;19:52:3:وَنَٰدَيۡنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَيۡمَنِ وَقَرَّبۡنَٰهُ نَجِيࣰّا¦19:53:1:وَوَهَبۡنَا لَهُۥ مِن\nT;0;19:53:2:رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيࣰّا¦19:54:1:وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ\nT;0;19:54:2:صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولࣰا نَّبِيࣰّا¦19:55:1:وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ\nT;0;19:55:2:وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيࣰّا¦19:56:1:وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ\nT;0;19:56:2:كَانَ صِدِّيقࣰا نَّبِيࣰّا¦19:57:3:وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا¦19:58:1:أُوْلَٰٓئِكَ ٱلَّذِينَ أَنۡعَمَ\nT;0;19:58:0:ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ مِن ذُرِّيَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحࣲ وَمِن\nT;0;19:58:0:ذُرِّيَّةِ إِبۡرَٰهِيمَ وَإِسۡرَٰٓءِيلَ وَمِمَّنۡ هَدَيۡنَا وَٱجۡتَبَيۡنَآۚ إِذَا تُتۡلَىٰ عَلَيۡهِمۡ\nT;0;19:58:2:ءَايَٰتُ ٱلرَّحۡمَٰنِ خَرُّواْۤ سُجَّدࣰاۤ وَبُكِيࣰّا۩¦19:59:1:۞ فَخَلَفَ مِنۢ بَعۡدِهِمۡ\nT;0;19:59:2:خَلۡفٌ أَضَاعُواْ ٱلصَّلَوٰةَ وَٱتَّبَعُواْ ٱلشَّهَوَٰتِۖ فَسَوۡفَ يَلۡقَوۡنَ غَيًّا\nT;0;19:60:1:إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحࣰا فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ\nT;0;19:60:2:وَلَا يُظۡلَمُونَ شَيۡـࣰٔا¦19:61:1:جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدَ ٱلرَّحۡمَٰنُ عِبَادَهُۥ\nT;0;19:61:2:بِٱلۡغَيۡبِۚ إِنَّهُۥ كَانَ وَعۡدُهُۥ مَأۡتِيࣰّا¦19:62:1:لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا إِلَّا\nT;0;19:62:2:سَلَٰمࣰاۖ وَلَهُمۡ رِزۡقُهُمۡ فِيهَا بُكۡرَةࣰ وَعَشِيࣰّا¦19:63:1:تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِي\nT;0;19:63:2:نُورِثُ مِنۡ عِبَادِنَا مَن كَانَ تَقِيࣰّا¦19:64:1:وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ\nT;0;19:64:2:مَا بَيۡنَ أَيۡدِينَا وَمَا خَلۡفَنَا وَمَا بَيۡنَ ذَٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِيࣰّا',
  '16;31;3;\nT;0;19:65:1:رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَٰدَتِهِۦۚ\nT;0;19:65:2:هَلۡ تَعۡلَمُ لَهُۥ سَمِيࣰّا¦19:66:1:وَيَقُولُ ٱلۡإِنسَٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ\nT;0;19:66:2:أُخۡرَجُ حَيًّا¦19:67:1:أَوَلَا يَذۡكُرُ ٱلۡإِنسَٰنُ أَنَّا خَلَقۡنَٰهُ مِن قَبۡلُ\nT;0;19:67:2:وَلَمۡ يَكُ شَيۡـࣰٔا¦19:68:1:فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّيَٰطِينَ ثُمَّ\nT;0;19:68:2:لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِيࣰّا¦19:69:1:ثُمَّ لَنَنزِعَنَّ مِن كُلِّ\nT;0;19:69:2:شِيعَةٍ أَيُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَٰنِ عِتِيࣰّا¦19:70:1:ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِينَ\nT;0;19:70:2:هُمۡ أَوۡلَىٰ بِهَا صِلِيࣰّا¦19:71:1:وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ\nT;0;19:71:2:حَتۡمࣰا مَّقۡضِيࣰّا¦19:72:1:ثُمَّ نُنَجِّي ٱلَّذِينَ ٱتَّقَواْ وَّنَذَرُ ٱلظَّٰلِمِينَ\nT;0;19:72:2:فِيهَا جِثِيࣰّا¦19:73:1:وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتࣲ قَالَ ٱلَّذِينَ كَفَرُواْ\nT;0;19:73:2:لِلَّذِينَ ءَامَنُوٓاْ أَيُّ ٱلۡفَرِيقَيۡنِ خَيۡرࣱ مَّقَامࣰا وَأَحۡسَنُ نَدِيࣰّا\nT;0;19:74:3:وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَٰثࣰا وَرِءۡيࣰا\nT;0;19:75:1:قُلۡ مَن كَانَ فِي ٱلضَّلَٰلَةِ فَلۡيَمۡدُدۡ لَهُ ٱلرَّحۡمَٰنُ مَدًّاۚ حَتَّىٰٓ إِذَا رَأَوۡاْ\nT;0;19:75:0:مَا يُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَيَعۡلَمُونَ مَنۡ هُوَ شَرࣱّ\nT;0;19:75:2:مَّكَانࣰا وَأَضۡعَفُ جُندࣰا¦19:76:1:وَيَزِيدُ ٱللَّهُ ٱلَّذِينَ ٱهۡتَدَوۡاْ هُدࣰىۗ\nT;0;19:76:2:وَٱلۡبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابࣰا وَخَيۡرࣱ مَّرَدًّا',
  '16;31;3;\nT;0;19:77:3:أَفَرَءَيۡتَ ٱلَّذِي كَفَرَ بِـَٔايَٰتِنَا وَقَالَ لَأُوتَيَنَّ مَالࣰا وَوَلَدًا\nT;0;19:78:3:أَطَّلَعَ ٱلۡغَيۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَٰنِ عَهۡدࣰا¦19:79:1:كَلَّاۚ\nT;0;19:79:2:سَنَكۡتُبُ مَا يَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدࣰّا¦19:80:1:وَنَرِثُهُۥ\nT;0;19:80:2:مَا يَقُولُ وَيَأۡتِينَا فَرۡدࣰا¦19:81:1:وَٱتَّخَذُواْ مِن دُونِ ٱللَّهِ ءَالِهَةࣰ\nT;0;19:81:2:لِّيَكُونُواْ لَهُمۡ عِزࣰّا¦19:82:1:كَلَّاۚ سَيَكۡفُرُونَ بِعِبَادَتِهِمۡ وَيَكُونُونَ\nT;0;19:82:2:عَلَيۡهِمۡ ضِدًّا¦19:83:1:أَلَمۡ تَرَ أَنَّآ أَرۡسَلۡنَا ٱلشَّيَٰطِينَ عَلَى ٱلۡكَٰفِرِينَ\nT;0;19:83:2:تَؤُزُّهُمۡ أَزࣰّا¦19:84:3:فَلَا تَعۡجَلۡ عَلَيۡهِمۡۖ إِنَّمَا نَعُدُّ لَهُمۡ عَدࣰّا\nT;0;19:85:3:يَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِينَ إِلَى ٱلرَّحۡمَٰنِ وَفۡدࣰا¦19:86:1:وَنَسُوقُ ٱلۡمُجۡرِمِينَ\nT;0;19:86:2:إِلَىٰ جَهَنَّمَ وِرۡدࣰا¦19:87:1:لَّا يَمۡلِكُونَ ٱلشَّفَٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ\nT;0;19:87:2:ٱلرَّحۡمَٰنِ عَهۡدࣰا¦19:88:3:وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدࣰا¦19:89:1:لَّقَدۡ\nT;0;19:89:2:جِئۡتُمۡ شَيۡـًٔا إِدࣰّا¦19:90:1:تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرۡنَ مِنۡهُ\nT;0;19:90:2:وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا¦19:91:3:أَن دَعَوۡاْ لِلرَّحۡمَٰنِ وَلَدࣰا\nT;0;19:92:3:وَمَا يَنۢبَغِي لِلرَّحۡمَٰنِ أَن يَتَّخِذَ وَلَدًا¦19:93:1:إِن كُلُّ مَن فِي\nT;0;19:93:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ إِلَّآ ءَاتِي ٱلرَّحۡمَٰنِ عَبۡدࣰا¦19:94:1:لَّقَدۡ أَحۡصَىٰهُمۡ\nT;0;19:94:2:وَعَدَّهُمۡ عَدࣰّا¦19:95:3:وَكُلُّهُمۡ ءَاتِيهِ يَوۡمَ ٱلۡقِيَٰمَةِ فَرۡدًا',
  '16;31;3;125\nT;0;19:96:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَيَجۡعَلُ لَهُمُ\nT;0;19:96:2:ٱلرَّحۡمَٰنُ وُدࣰّا¦19:97:1:فَإِنَّمَا يَسَّرۡنَٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ\nT;0;19:97:2:ٱلۡمُتَّقِينَ وَتُنذِرَ بِهِۦ قَوۡمࣰا لُّدࣰّا¦19:98:1:وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم\nT;2;19:98:2:مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا\nH;20\nB;20\nT;0;20:1:3:طه¦20:2:3:مَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰٓ¦20:3:1:إِلَّا تَذۡكِرَةࣰ\nT;0;20:3:2:لِّمَن يَخۡشَىٰ¦20:4:3:تَنزِيلࣰا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَٰوَٰتِ ٱلۡعُلَى\nT;0;20:5:3:ٱلرَّحۡمَٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ¦20:6:1:لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي\nT;0;20:6:2:ٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ¦20:7:1:وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ\nT;0;20:7:2:فَإِنَّهُۥ يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى¦20:8:1:ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ\nT;0;20:8:2:ٱلۡحُسۡنَىٰ¦20:9:3:وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ¦20:10:1:إِذۡ رَءَا نَارࣰا\nT;0;20:10:0:فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارࣰا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ\nT;0;20:10:2:أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدࣰى¦20:11:3:فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ¦20:12:1:إِنِّيٓ\nT;0;20:12:2:أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوࣰى',
  '16;32;0;\nT;0;20:13:3:وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ¦20:14:1:إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠\nT;0;20:14:2:فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ¦20:15:1:إِنَّ ٱلسَّاعَةَ ءَاتِيَةٌ\nT;0;20:15:2:أَكَادُ أُخۡفِيهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ¦20:16:1:فَلَا يَصُدَّنَّكَ\nT;0;20:16:2:عَنۡهَا مَن لَّا يُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ¦20:17:1:وَمَا تِلۡكَ\nT;0;20:17:2:بِيَمِينِكَ يَٰمُوسَىٰ¦20:18:1:قَالَ هِيَ عَصَايَ أَتَوَكَّؤُاْ عَلَيۡهَا\nT;0;20:18:2:وَأَهُشُّ بِهَا عَلَىٰ غَنَمِي وَلِيَ فِيهَا مَـَٔارِبُ أُخۡرَىٰ¦20:19:1:قَالَ أَلۡقِهَا\nT;0;20:19:2:يَٰمُوسَىٰ¦20:20:3:فَأَلۡقَىٰهَا فَإِذَا هِيَ حَيَّةࣱ تَسۡعَىٰ¦20:21:1:قَالَ خُذۡهَا\nT;0;20:21:2:وَلَا تَخَفۡۖ سَنُعِيدُهَا سِيرَتَهَا ٱلۡأُولَىٰ¦20:22:1:وَٱضۡمُمۡ يَدَكَ\nT;0;20:22:2:إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءٍ ءَايَةً أُخۡرَىٰ¦20:23:1:لِنُرِيَكَ\nT;0;20:23:2:مِنۡ ءَايَٰتِنَا ٱلۡكُبۡرَى¦20:24:3:ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ¦20:25:1:قَالَ\nT;0;20:25:2:رَبِّ ٱشۡرَحۡ لِي صَدۡرِي¦20:26:3:وَيَسِّرۡ لِيٓ أَمۡرِي¦20:27:1:وَٱحۡلُلۡ عُقۡدَةࣰ مِّن\nT;0;20:27:2:لِّسَانِي¦20:28:3:يَفۡقَهُواْ قَوۡلِي¦20:29:3:وَٱجۡعَل لِّي وَزِيرࣰا مِّنۡ أَهۡلِي¦20:30:1:هَٰرُونَ\nT;0;20:30:2:أَخِي¦20:31:3:ٱشۡدُدۡ بِهِۦٓ أَزۡرِي¦20:32:3:وَأَشۡرِكۡهُ فِيٓ أَمۡرِي¦20:33:1:كَيۡ نُسَبِّحَكَ\nT;0;20:33:2:كَثِيرࣰا¦20:34:3:وَنَذۡكُرَكَ كَثِيرًا¦20:35:3:إِنَّكَ كُنتَ بِنَا بَصِيرࣰا¦20:36:1:قَالَ قَدۡ\nT;0;20:36:2:أُوتِيتَ سُؤۡلَكَ يَٰمُوسَىٰ¦20:37:3:وَلَقَدۡ مَنَنَّا عَلَيۡكَ مَرَّةً أُخۡرَىٰٓ',
  '16;32;0;\nT;0;20:38:3:إِذۡ أَوۡحَيۡنَآ إِلَىٰٓ أُمِّكَ مَا يُوحَىٰٓ¦20:39:1:أَنِ ٱقۡذِفِيهِ فِي ٱلتَّابُوتِ فَٱقۡذِفِيهِ\nT;0;20:39:0:فِي ٱلۡيَمِّ فَلۡيُلۡقِهِ ٱلۡيَمُّ بِٱلسَّاحِلِ يَأۡخُذۡهُ عَدُوࣱّ لِّي وَعَدُوࣱّ لَّهُۥۚ وَأَلۡقَيۡتُ\nT;0;20:39:2:عَلَيۡكَ مَحَبَّةࣰ مِّنِّي وَلِتُصۡنَعَ عَلَىٰ عَيۡنِيٓ¦20:40:1:إِذۡ تَمۡشِيٓ أُخۡتُكَ فَتَقُولُ\nT;0;20:40:0:هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن يَكۡفُلُهُۥۖ فَرَجَعۡنَٰكَ إِلَىٰٓ أُمِّكَ كَيۡ تَقَرَّ عَيۡنُهَا\nT;0;20:40:0:وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسࣰا فَنَجَّيۡنَٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّٰكَ فُتُونࣰاۚ\nT;0;20:40:2:فَلَبِثۡتَ سِنِينَ فِيٓ أَهۡلِ مَدۡيَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرࣲ يَٰمُوسَىٰ\nT;0;20:41:3:وَٱصۡطَنَعۡتُكَ لِنَفۡسِي¦20:42:1:ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔايَٰتِي وَلَا\nT;0;20:42:2:تَنِيَا فِي ذِكۡرِي¦20:43:3:ٱذۡهَبَآ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ¦20:44:1:فَقُولَا لَهُۥ قَوۡلࣰا\nT;0;20:44:2:لَّيِّنࣰا لَّعَلَّهُۥ يَتَذَكَّرُ أَوۡ يَخۡشَىٰ¦20:45:1:قَالَا رَبَّنَآ إِنَّنَا نَخَافُ أَن يَفۡرُطَ\nT;0;20:45:2:عَلَيۡنَآ أَوۡ أَن يَطۡغَىٰ¦20:46:3:قَالَ لَا تَخَافَآۖ إِنَّنِي مَعَكُمَآ أَسۡمَعُ وَأَرَىٰ\nT;0;20:47:1:فَأۡتِيَاهُ فَقُولَآ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِيٓ إِسۡرَٰٓءِيلَ\nT;0;20:47:0:وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَٰكَ بِـَٔايَةࣲ مِّن رَّبِّكَۖ وَٱلسَّلَٰمُ عَلَىٰ مَنِ ٱتَّبَعَ\nT;0;20:47:2:ٱلۡهُدَىٰٓ¦20:48:1:إِنَّا قَدۡ أُوحِيَ إِلَيۡنَآ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ\nT;0;20:48:2:وَتَوَلَّىٰ¦20:49:3:قَالَ فَمَن رَّبُّكُمَا يَٰمُوسَىٰ¦20:50:1:قَالَ رَبُّنَا ٱلَّذِيٓ أَعۡطَىٰ\nT;0;20:50:2:كُلَّ شَيۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ¦20:51:3:قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ',
  '16;32;0;126\nT;0;20:52:3:قَالَ عِلۡمُهَا عِندَ رَبِّي فِي كِتَٰبࣲۖ لَّا يَضِلُّ رَبِّي وَلَا يَنسَى¦20:53:1:ٱلَّذِي\nT;0;20:53:0:جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدࣰا وَسَلَكَ لَكُمۡ فِيهَا سُبُلࣰا وَأَنزَلَ مِنَ\nT;0;20:53:2:ٱلسَّمَآءِ مَآءࣰ فَأَخۡرَجۡنَا بِهِۦٓ أَزۡوَٰجࣰا مِّن نَّبَاتࣲ شَتَّىٰ¦20:54:1:كُلُواْ\nT;0;20:54:2:وَٱرۡعَوۡاْ أَنۡعَٰمَكُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّأُوْلِي ٱلنُّهَىٰ¦20:55:1:۞ مِنۡهَا\nT;0;20:55:2:خَلَقۡنَٰكُمۡ وَفِيهَا نُعِيدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ¦20:56:1:وَلَقَدۡ\nT;0;20:56:2:أَرَيۡنَٰهُ ءَايَٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ¦20:57:1:قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا\nT;0;20:57:2:مِنۡ أَرۡضِنَا بِسِحۡرِكَ يَٰمُوسَىٰ¦20:58:1:فَلَنَأۡتِيَنَّكَ بِسِحۡرࣲ مِّثۡلِهِۦ\nT;0;20:58:0:فَٱجۡعَلۡ بَيۡنَنَا وَبَيۡنَكَ مَوۡعِدࣰا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَآ أَنتَ مَكَانࣰا\nT;0;20:58:2:سُوࣰى¦20:59:3:قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحࣰى\nT;0;20:60:3:فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَيۡدَهُۥ ثُمَّ أَتَىٰ¦20:61:1:قَالَ لَهُم\nT;0;20:61:0:مُّوسَىٰ وَيۡلَكُمۡ لَا تَفۡتَرُواْ عَلَى ٱللَّهِ كَذِبࣰا فَيُسۡحِتَكُم بِعَذَابࣲۖ\nT;0;20:61:2:وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ¦20:62:1:فَتَنَٰزَعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ وَأَسَرُّواْ\nT;0;20:62:2:ٱلنَّجۡوَىٰ¦20:63:1:قَالُوٓاْ إِنۡ هَٰذَٰنِ لَسَٰحِرَٰنِ يُرِيدَانِ أَن يُخۡرِجَاكُم\nT;0;20:63:2:مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَيَذۡهَبَا بِطَرِيقَتِكُمُ ٱلۡمُثۡلَىٰ\nT;0;20:64:3:فَأَجۡمِعُواْ كَيۡدَكُمۡ ثُمَّ ٱئۡتُواْ صَفࣰّاۚ وَقَدۡ أَفۡلَحَ ٱلۡيَوۡمَ مَنِ ٱسۡتَعۡلَىٰ',
  '16;32;1;\nT;0;20:65:3:قَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ¦20:66:1:قَالَ بَلۡ\nT;0;20:66:0:أَلۡقُواْۖ فَإِذَا حِبَالُهُمۡ وَعِصِيُّهُمۡ يُخَيَّلُ إِلَيۡهِ مِن سِحۡرِهِمۡ أَنَّهَا\nT;0;20:66:2:تَسۡعَىٰ¦20:67:3:فَأَوۡجَسَ فِي نَفۡسِهِۦ خِيفَةࣰ مُّوسَىٰ¦20:68:1:قُلۡنَا لَا تَخَفۡ إِنَّكَ\nT;0;20:68:2:أَنتَ ٱلۡأَعۡلَىٰ¦20:69:1:وَأَلۡقِ مَا فِي يَمِينِكَ تَلۡقَفۡ مَا صَنَعُوٓاْۖ إِنَّمَا صَنَعُواْ\nT;0;20:69:2:كَيۡدُ سَٰحِرࣲۖ وَلَا يُفۡلِحُ ٱلسَّاحِرُ حَيۡثُ أَتَىٰ¦20:70:1:فَأُلۡقِيَ ٱلسَّحَرَةُ سُجَّدࣰا\nT;0;20:70:2:قَالُوٓاْ ءَامَنَّا بِرَبِّ هَٰرُونَ وَمُوسَىٰ¦20:71:1:قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ\nT;0;20:71:0:لَكُمۡۖ إِنَّهُۥ لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَيۡدِيَكُمۡ\nT;0;20:71:0:وَأَرۡجُلَكُم مِّنۡ خِلَٰفࣲ وَلَأُصَلِّبَنَّكُمۡ فِي جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ\nT;0;20:71:2:أَيُّنَآ أَشَدُّ عَذَابࣰا وَأَبۡقَىٰ¦20:72:1:قَالُواْ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَآءَنَا مِنَ\nT;0;20:72:0:ٱلۡبَيِّنَٰتِ وَٱلَّذِي فَطَرَنَاۖ فَٱقۡضِ مَآ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِي هَٰذِهِ\nT;0;20:72:2:ٱلۡحَيَوٰةَ ٱلدُّنۡيَآ¦20:73:1:إِنَّآ ءَامَنَّا بِرَبِّنَا لِيَغۡفِرَ لَنَا خَطَٰيَٰنَا وَمَآ أَكۡرَهۡتَنَا\nT;0;20:73:2:عَلَيۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَيۡرࣱ وَأَبۡقَىٰٓ¦20:74:1:إِنَّهُۥ مَن يَأۡتِ رَبَّهُۥ مُجۡرِمࣰا\nT;0;20:74:2:فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ¦20:75:1:وَمَن يَأۡتِهِۦ مُؤۡمِنࣰا قَدۡ\nT;0;20:75:2:عَمِلَ ٱلصَّٰلِحَٰتِ فَأُوْلَٰٓئِكَ لَهُمُ ٱلدَّرَجَٰتُ ٱلۡعُلَىٰ¦20:76:1:جَنَّٰتُ عَدۡنࣲ\nT;0;20:76:2:تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ جَزَآءُ مَن تَزَكَّىٰ',
  '16;32;1;127\nT;0;20:77:1:وَلَقَدۡ أَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِي فَٱضۡرِبۡ لَهُمۡ طَرِيقࣰا\nT;0;20:77:2:فِي ٱلۡبَحۡرِ يَبَسࣰا لَّا تَخَٰفُ دَرَكࣰا وَلَا تَخۡشَىٰ¦20:78:1:فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ\nT;0;20:78:2:بِجُنُودِهِۦ فَغَشِيَهُم مِّنَ ٱلۡيَمِّ مَا غَشِيَهُمۡ¦20:79:1:وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ\nT;0;20:79:2:وَمَا هَدَىٰ¦20:80:1:يَٰبَنِيٓ إِسۡرَٰٓءِيلَ قَدۡ أَنجَيۡنَٰكُم مِّنۡ عَدُوِّكُمۡ وَوَٰعَدۡنَٰكُمۡ\nT;0;20:80:2:جَانِبَ ٱلطُّورِ ٱلۡأَيۡمَنَ وَنَزَّلۡنَا عَلَيۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ¦20:81:1:كُلُواْ مِن\nT;0;20:81:0:طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ وَلَا تَطۡغَوۡاْ فِيهِ فَيَحِلَّ عَلَيۡكُمۡ غَضَبِيۖ\nT;0;20:81:2:وَمَن يَحۡلِلۡ عَلَيۡهِ غَضَبِي فَقَدۡ هَوَىٰ¦20:82:1:وَإِنِّي لَغَفَّارࣱ لِّمَن تَابَ\nT;0;20:82:2:وَءَامَنَ وَعَمِلَ صَٰلِحࣰا ثُمَّ ٱهۡتَدَىٰ¦20:83:1:۞ وَمَآ أَعۡجَلَكَ عَن\nT;0;20:83:2:قَوۡمِكَ يَٰمُوسَىٰ¦20:84:1:قَالَ هُمۡ أُوْلَآءِ عَلَىٰٓ أَثَرِي وَعَجِلۡتُ إِلَيۡكَ\nT;0;20:84:2:رَبِّ لِتَرۡضَىٰ¦20:85:1:قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ\nT;0;20:85:2:ٱلسَّامِرِيُّ¦20:86:1:فَرَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفࣰاۚ قَالَ\nT;0;20:86:0:يَٰقَوۡمِ أَلَمۡ يَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَيۡكُمُ ٱلۡعَهۡدُ\nT;0;20:86:0:أَمۡ أَرَدتُّمۡ أَن يَحِلَّ عَلَيۡكُمۡ غَضَبࣱ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم\nT;0;20:86:2:مَّوۡعِدِي¦20:87:1:قَالُواْ مَآ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَٰكِنَّا حُمِّلۡنَآ\nT;0;20:87:2:أَوۡزَارࣰا مِّن زِينَةِ ٱلۡقَوۡمِ فَقَذَفۡنَٰهَا فَكَذَٰلِكَ أَلۡقَى ٱلسَّامِرِيُّ',
  '16;32;2;\nT;0;20:88:1:فَأَخۡرَجَ لَهُمۡ عِجۡلࣰا جَسَدࣰا لَّهُۥ خُوَارࣱ فَقَالُواْ هَٰذَآ إِلَٰهُكُمۡ\nT;0;20:88:2:وَإِلَٰهُ مُوسَىٰ فَنَسِيَ¦20:89:1:أَفَلَا يَرَوۡنَ أَلَّا يَرۡجِعُ إِلَيۡهِمۡ قَوۡلࣰا\nT;0;20:89:2:وَلَا يَمۡلِكُ لَهُمۡ ضَرࣰّا وَلَا نَفۡعࣰا¦20:90:1:وَلَقَدۡ قَالَ لَهُمۡ هَٰرُونُ\nT;0;20:90:0:مِن قَبۡلُ يَٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَٰنُ فَٱتَّبِعُونِي\nT;0;20:90:2:وَأَطِيعُوٓاْ أَمۡرِي¦20:91:1:قَالُواْ لَن نَّبۡرَحَ عَلَيۡهِ عَٰكِفِينَ حَتَّىٰ يَرۡجِعَ\nT;0;20:91:2:إِلَيۡنَا مُوسَىٰ¦20:92:3:قَالَ يَٰهَٰرُونُ مَا مَنَعَكَ إِذۡ رَأَيۡتَهُمۡ ضَلُّوٓاْ\nT;0;20:93:3:أَلَّا تَتَّبِعَنِۖ أَفَعَصَيۡتَ أَمۡرِي¦20:94:1:قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي\nT;0;20:94:0:وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَٰٓءِيلَ\nT;0;20:94:2:وَلَمۡ تَرۡقُبۡ قَوۡلِي¦20:95:3:قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ¦20:96:1:قَالَ\nT;0;20:96:0:بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةࣰ مِّنۡ أَثَرِ\nT;0;20:96:2:ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي¦20:97:1:قَالَ\nT;0;20:97:0:فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ\nT;0;20:97:0:مَوۡعِدࣰا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ\nT;0;20:97:2:عَاكِفࣰاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا¦20:98:1:إِنَّمَآ\nT;0;20:98:2:إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمࣰا',
  '16;32;2;128\nT;0;20:99:1:كَذَٰلِكَ نَقُصُّ عَلَيۡكَ مِنۡ أَنۢبَآءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَيۡنَٰكَ مِن لَّدُنَّا\nT;0;20:99:2:ذِكۡرࣰا¦20:100:3:مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ يَحۡمِلُ يَوۡمَ ٱلۡقِيَٰمَةِ وِزۡرًا\nT;0;20:101:3:خَٰلِدِينَ فِيهِۖ وَسَآءَ لَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ حِمۡلࣰا¦20:102:1:يَوۡمَ يُنفَخُ\nT;0;20:102:2:فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذࣲ زُرۡقࣰا¦20:103:1:يَتَخَٰفَتُونَ\nT;0;20:103:2:بَيۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرࣰا¦20:104:1:نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَ إِذۡ يَقُولُ\nT;0;20:104:2:أَمۡثَلُهُمۡ طَرِيقَةً إِن لَّبِثۡتُمۡ إِلَّا يَوۡمࣰا¦20:105:1:وَيَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ\nT;0;20:105:2:فَقُلۡ يَنسِفُهَا رَبِّي نَسۡفࣰا¦20:106:3:فَيَذَرُهَا قَاعࣰا صَفۡصَفࣰا\nT;0;20:107:3:لَّا تَرَىٰ فِيهَا عِوَجࣰا وَلَآ أَمۡتࣰا¦20:108:1:يَوۡمَئِذࣲ يَتَّبِعُونَ ٱلدَّاعِيَ لَا عِوَجَ\nT;0;20:108:2:لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسࣰا\nT;0;20:109:1:يَوۡمَئِذࣲ لَّا تَنفَعُ ٱلشَّفَٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَرَضِيَ لَهُۥ\nT;0;20:109:2:قَوۡلࣰا¦20:110:1:يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَلَا يُحِيطُونَ بِهِۦ\nT;0;20:110:2:عِلۡمࣰا¦20:111:1:۞ وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَيِّ ٱلۡقَيُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ\nT;0;20:111:2:ظُلۡمࣰا¦20:112:1:وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا يَخَافُ\nT;0;20:112:2:ظُلۡمࣰا وَلَا هَضۡمࣰا¦20:113:1:وَكَذَٰلِكَ أَنزَلۡنَٰهُ قُرۡءَانًا عَرَبِيࣰّا وَصَرَّفۡنَا\nT;0;20:113:2:فِيهِ مِنَ ٱلۡوَعِيدِ لَعَلَّهُمۡ يَتَّقُونَ أَوۡ يُحۡدِثُ لَهُمۡ ذِكۡرࣰا',
  '16;32;3;\nT;0;20:114:1:فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن\nT;0;20:114:2:يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمࣰا¦20:115:1:وَلَقَدۡ عَهِدۡنَآ\nT;0;20:115:2:إِلَىٰٓ ءَادَمَ مِن قَبۡلُ فَنَسِيَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمࣰا¦20:116:1:وَإِذۡ قُلۡنَا\nT;0;20:116:2:لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ\nT;0;20:117:1:فَقُلۡنَا يَٰٓـَٔادَمُ إِنَّ هَٰذَا عَدُوࣱّ لَّكَ وَلِزَوۡجِكَ فَلَا يُخۡرِجَنَّكُمَا\nT;0;20:117:2:مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰٓ¦20:118:3:إِنَّ لَكَ أَلَّا تَجُوعَ فِيهَا وَلَا تَعۡرَىٰ\nT;0;20:119:3:وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ¦20:120:1:فَوَسۡوَسَ إِلَيۡهِ\nT;0;20:120:0:ٱلشَّيۡطَٰنُ قَالَ يَٰٓـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكࣲ\nT;0;20:120:2:لَّا يَبۡلَىٰ¦20:121:1:فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا\nT;0;20:121:2:يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ\nT;0;20:122:3:ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ¦20:123:1:قَالَ ٱهۡبِطَا مِنۡهَا\nT;0;20:123:0:جَمِيعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ فَإِمَّا يَأۡتِيَنَّكُم مِّنِّي هُدࣰى\nT;0;20:123:2:فَمَنِ ٱتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشۡقَىٰ¦20:124:1:وَمَنۡ أَعۡرَضَ\nT;0;20:124:0:عَن ذِكۡرِي فَإِنَّ لَهُۥ مَعِيشَةࣰ ضَنكࣰا وَنَحۡشُرُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ\nT;0;20:124:2:أَعۡمَىٰ¦20:125:3:قَالَ رَبِّ لِمَ حَشَرۡتَنِيٓ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِيرࣰا',
  '16;32;3;\nT;0;20:126:3:قَالَ كَذَٰلِكَ أَتَتۡكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ وَكَذَٰلِكَ ٱلۡيَوۡمَ تُنسَىٰ\nT;0;20:127:1:وَكَذَٰلِكَ نَجۡزِي مَنۡ أَسۡرَفَ وَلَمۡ يُؤۡمِنۢ بِـَٔايَٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡأٓخِرَةِ\nT;0;20:127:2:أَشَدُّ وَأَبۡقَىٰٓ¦20:128:1:أَفَلَمۡ يَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ\nT;0;20:128:2:يَمۡشُونَ فِي مَسَٰكِنِهِمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّأُوْلِي ٱلنُّهَىٰ\nT;0;20:129:3:وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامࣰا وَأَجَلࣱ مُّسَمࣰّى\nT;0;20:130:1:فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ\nT;0;20:130:0:وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَآيِٕ ٱلَّيۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ\nT;0;20:130:2:تَرۡضَىٰ¦20:131:1:وَلَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجࣰا مِّنۡهُمۡ زَهۡرَةَ\nT;0;20:131:2:ٱلۡحَيَوٰةِ ٱلدُّنۡيَا لِنَفۡتِنَهُمۡ فِيهِۚ وَرِزۡقُ رَبِّكَ خَيۡرࣱ وَأَبۡقَىٰ¦20:132:1:وَأۡمُرۡ أَهۡلَكَ\nT;0;20:132:0:بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقࣰاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ\nT;0;20:132:2:لِلتَّقۡوَىٰ¦20:133:1:وَقَالُواْ لَوۡلَا يَأۡتِينَا بِـَٔايَةࣲ مِّن رَّبِّهِۦٓۚ أَوَلَمۡ تَأۡتِهِم\nT;0;20:133:2:بَيِّنَةُ مَا فِي ٱلصُّحُفِ ٱلۡأُولَىٰ¦20:134:1:وَلَوۡ أَنَّآ أَهۡلَكۡنَٰهُم بِعَذَابࣲ\nT;0;20:134:0:مِّن قَبۡلِهِۦ لَقَالُواْ رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولࣰا فَنَتَّبِعَ\nT;0;20:134:2:ءَايَٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ¦20:135:1:قُلۡ كُلࣱّ مُّتَرَبِّصࣱ فَتَرَبَّصُواْۖ\nT;2;20:135:2:فَسَتَعۡلَمُونَ مَنۡ أَصۡحَٰبُ ٱلصِّرَٰطِ ٱلسَّوِيِّ وَمَنِ ٱهۡتَدَىٰ',
  '17;33;0;129\nH;21\nB;21\nT;0;21:1:3:ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِي غَفۡلَةࣲ مُّعۡرِضُونَ\nT;0;21:2:1:مَا يَأۡتِيهِم مِّن ذِكۡرࣲ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ\nT;0;21:2:2:يَلۡعَبُونَ¦21:3:1:لَاهِيَةࣰ قُلُوبُهُمۡۗ وَأَسَرُّواْ ٱلنَّجۡوَى ٱلَّذِينَ\nT;0;21:3:0:ظَلَمُواْ هَلۡ هَٰذَآ إِلَّا بَشَرࣱ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ\nT;0;21:3:2:تُبۡصِرُونَ¦21:4:1:قَالَ رَبِّي يَعۡلَمُ ٱلۡقَوۡلَ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۖ\nT;0;21:4:2:وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ¦21:5:1:بَلۡ قَالُوٓاْ أَضۡغَٰثُ أَحۡلَٰمِۭ بَلِ\nT;0;21:5:2:ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرࣱ فَلۡيَأۡتِنَا بِـَٔايَةࣲ كَمَآ أُرۡسِلَ ٱلۡأَوَّلُونَ\nT;0;21:6:3:مَآ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَآۖ أَفَهُمۡ يُؤۡمِنُونَ\nT;0;21:7:1:وَمَآ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالࣰا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ\nT;0;21:7:2:ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ¦21:8:1:وَمَا جَعَلۡنَٰهُمۡ جَسَدࣰا\nT;0;21:8:2:لَّا يَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُواْ خَٰلِدِينَ¦21:9:1:ثُمَّ صَدَقۡنَٰهُمُ\nT;0;21:9:2:ٱلۡوَعۡدَ فَأَنجَيۡنَٰهُمۡ وَمَن نَّشَآءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِينَ\nT;0;21:10:3:لَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ كِتَٰبࣰا فِيهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ',
  '17;33;0;\nT;0;21:11:1:وَكَمۡ قَصَمۡنَا مِن قَرۡيَةࣲ كَانَتۡ ظَالِمَةࣰ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا\nT;0;21:11:2:ءَاخَرِينَ¦21:12:3:فَلَمَّآ أَحَسُّواْ بَأۡسَنَآ إِذَا هُم مِّنۡهَا يَرۡكُضُونَ\nT;0;21:13:1:لَا تَرۡكُضُواْ وَٱرۡجِعُوٓاْ إِلَىٰ مَآ أُتۡرِفۡتُمۡ فِيهِ وَمَسَٰكِنِكُمۡ لَعَلَّكُمۡ\nT;0;21:13:2:تُسۡـَٔلُونَ¦21:14:3:قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ¦21:15:1:فَمَا زَالَت تِّلۡكَ\nT;0;21:15:2:دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَٰهُمۡ حَصِيدًا خَٰمِدِينَ¦21:16:1:وَمَا خَلَقۡنَا\nT;0;21:16:2:ٱلسَّمَآءَ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا لَٰعِبِينَ¦21:17:1:لَوۡ أَرَدۡنَآ أَن نَّتَّخِذَ\nT;0;21:17:2:لَهۡوࣰا لَّٱتَّخَذۡنَٰهُ مِن لَّدُنَّآ إِن كُنَّا فَٰعِلِينَ¦21:18:1:بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى\nT;0;21:18:2:ٱلۡبَٰطِلِ فَيَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقࣱۚ وَلَكُمُ ٱلۡوَيۡلُ مِمَّا تَصِفُونَ\nT;0;21:19:1:وَلَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا يَسۡتَكۡبِرُونَ\nT;0;21:19:2:عَنۡ عِبَادَتِهِۦ وَلَا يَسۡتَحۡسِرُونَ¦21:20:1:يُسَبِّحُونَ ٱلَّيۡلَ وَٱلنَّهَارَ\nT;0;21:20:2:لَا يَفۡتُرُونَ¦21:21:3:أَمِ ٱتَّخَذُوٓاْ ءَالِهَةࣰ مِّنَ ٱلۡأَرۡضِ هُمۡ يُنشِرُونَ\nT;0;21:22:1:لَوۡ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ\nT;0;21:22:2:عَمَّا يَصِفُونَ¦21:23:3:لَا يُسۡـَٔلُ عَمَّا يَفۡعَلُ وَهُمۡ يُسۡـَٔلُونَ¦21:24:1:أَمِ ٱتَّخَذُواْ\nT;0;21:24:0:مِن دُونِهِۦٓ ءَالِهَةࣰۖ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡۖ هَٰذَا ذِكۡرُ مَن مَّعِيَ وَذِكۡرُ\nT;0;21:24:2:مَن قَبۡلِيۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ',
  '17;33;0;130\nT;0;21:25:1:وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِيٓ إِلَيۡهِ أَنَّهُۥ لَآ إِلَٰهَ\nT;0;21:25:2:إِلَّآ أَنَا۠ فَٱعۡبُدُونِ¦21:26:1:وَقَالُواْ ٱتَّخَذَ ٱلرَّحۡمَٰنُ وَلَدࣰاۗ سُبۡحَٰنَهُۥۚ\nT;0;21:26:2:بَلۡ عِبَادࣱ مُّكۡرَمُونَ¦21:27:1:لَا يَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم\nT;0;21:27:2:بِأَمۡرِهِۦ يَعۡمَلُونَ¦21:28:1:يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ\nT;0;21:28:2:وَلَا يَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡيَتِهِۦ مُشۡفِقُونَ\nT;0;21:29:1:۞ وَمَن يَقُلۡ مِنۡهُمۡ إِنِّيٓ إِلَٰهࣱ مِّن دُونِهِۦ فَذَٰلِكَ نَجۡزِيهِ\nT;0;21:29:2:جَهَنَّمَۚ كَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ¦21:30:1:أَوَلَمۡ يَرَ ٱلَّذِينَ كَفَرُوٓاْ\nT;0;21:30:0:أَنَّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقࣰا فَفَتَقۡنَٰهُمَاۖ وَجَعَلۡنَا\nT;0;21:30:2:مِنَ ٱلۡمَآءِ كُلَّ شَيۡءٍ حَيٍّۚ أَفَلَا يُؤۡمِنُونَ¦21:31:1:وَجَعَلۡنَا فِي ٱلۡأَرۡضِ\nT;0;21:31:0:رَوَٰسِيَ أَن تَمِيدَ بِهِمۡ وَجَعَلۡنَا فِيهَا فِجَاجࣰا سُبُلࣰا لَّعَلَّهُمۡ\nT;0;21:31:2:يَهۡتَدُونَ¦21:32:1:وَجَعَلۡنَا ٱلسَّمَآءَ سَقۡفࣰا مَّحۡفُوظࣰاۖ وَهُمۡ عَنۡ\nT;0;21:32:2:ءَايَٰتِهَا مُعۡرِضُونَ¦21:33:1:وَهُوَ ٱلَّذِي خَلَقَ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ\nT;0;21:33:2:وَٱلۡقَمَرَۖ كُلࣱّ فِي فَلَكࣲ يَسۡبَحُونَ¦21:34:1:وَمَا جَعَلۡنَا لِبَشَرࣲ مِّن قَبۡلِكَ\nT;0;21:34:2:ٱلۡخُلۡدَۖ أَفَإِيْن مِّتَّ فَهُمُ ٱلۡخَٰلِدُونَ¦21:35:1:كُلُّ نَفۡسࣲ ذَآئِقَةُ\nT;0;21:35:2:ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَيۡرِ فِتۡنَةࣰۖ وَإِلَيۡنَا تُرۡجَعُونَ',
  '17;33;1;\nT;0;21:36:1:وَإِذَا رَءَاكَ ٱلَّذِينَ كَفَرُوٓاْ إِن يَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَٰذَا\nT;0;21:36:0:ٱلَّذِي يَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَٰنِ هُمۡ\nT;0;21:36:2:كَٰفِرُونَ¦21:37:1:خُلِقَ ٱلۡإِنسَٰنُ مِنۡ عَجَلࣲۚ سَأُوْرِيكُمۡ\nT;0;21:37:2:ءَايَٰتِي فَلَا تَسۡتَعۡجِلُونِ¦21:38:1:وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ\nT;0;21:38:2:إِن كُنتُمۡ صَٰدِقِينَ¦21:39:1:لَوۡ يَعۡلَمُ ٱلَّذِينَ كَفَرُواْ حِينَ\nT;0;21:39:0:لَا يَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا\nT;0;21:39:2:هُمۡ يُنصَرُونَ¦21:40:1:بَلۡ تَأۡتِيهِم بَغۡتَةࣰ فَتَبۡهَتُهُمۡ فَلَا\nT;0;21:40:2:يَسۡتَطِيعُونَ رَدَّهَا وَلَا هُمۡ يُنظَرُونَ¦21:41:1:وَلَقَدِ ٱسۡتُهۡزِئَ\nT;0;21:41:0:بِرُسُلࣲ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِينَ سَخِرُواْ مِنۡهُم مَّا كَانُواْ\nT;0;21:41:2:بِهِۦ يَسۡتَهۡزِءُونَ¦21:42:1:قُلۡ مَن يَكۡلَؤُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ\nT;0;21:42:2:مِنَ ٱلرَّحۡمَٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ\nT;0;21:43:1:أَمۡ لَهُمۡ ءَالِهَةࣱ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا يَسۡتَطِيعُونَ نَصۡرَ\nT;0;21:43:2:أَنفُسِهِمۡ وَلَا هُم مِّنَّا يُصۡحَبُونَ¦21:44:1:بَلۡ مَتَّعۡنَا هَٰٓؤُلَآءِ\nT;0;21:44:0:وَءَابَآءَهُمۡ حَتَّىٰ طَالَ عَلَيۡهِمُ ٱلۡعُمُرُۗ أَفَلَا يَرَوۡنَ أَنَّا نَأۡتِي\nT;0;21:44:2:ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَآۚ أَفَهُمُ ٱلۡغَٰلِبُونَ',
  '17;33;1;131\nT;0;21:45:1:قُلۡ إِنَّمَآ أُنذِرُكُم بِٱلۡوَحۡيِۚ وَلَا يَسۡمَعُ ٱلصُّمُّ ٱلدُّعَآءَ إِذَا\nT;0;21:45:2:مَا يُنذَرُونَ¦21:46:1:وَلَئِن مَّسَّتۡهُمۡ نَفۡحَةࣱ مِّنۡ عَذَابِ رَبِّكَ\nT;0;21:46:2:لَيَقُولُنَّ يَٰوَيۡلَنَآ إِنَّا كُنَّا ظَٰلِمِينَ¦21:47:1:وَنَضَعُ ٱلۡمَوَٰزِينَ\nT;0;21:47:0:ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسࣱ شَيۡـࣰٔاۖ وَإِن كَانَ\nT;0;21:47:2:مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ\nT;0;21:48:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ وَهَٰرُونَ ٱلۡفُرۡقَانَ وَضِيَآءࣰ وَذِكۡرࣰا\nT;0;21:48:2:لِّلۡمُتَّقِينَ¦21:49:1:ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ وَهُم مِّنَ ٱلسَّاعَةِ\nT;0;21:49:2:مُشۡفِقُونَ¦21:50:1:وَهَٰذَا ذِكۡرࣱ مُّبَارَكٌ أَنزَلۡنَٰهُۚ أَفَأَنتُمۡ لَهُۥ\nT;0;21:50:2:مُنكِرُونَ¦21:51:1:۞ وَلَقَدۡ ءَاتَيۡنَآ إِبۡرَٰهِيمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا\nT;0;21:51:2:بِهِۦ عَٰلِمِينَ¦21:52:1:إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا هَٰذِهِ ٱلتَّمَاثِيلُ ٱلَّتِيٓ\nT;0;21:52:2:أَنتُمۡ لَهَا عَٰكِفُونَ¦21:53:3:قَالُواْ وَجَدۡنَآ ءَابَآءَنَا لَهَا عَٰبِدِينَ¦21:54:1:قَالَ\nT;0;21:54:2:لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَآؤُكُمۡ فِي ضَلَٰلࣲ مُّبِينࣲ¦21:55:1:قَالُوٓاْ أَجِئۡتَنَا\nT;0;21:55:2:بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّٰعِبِينَ¦21:56:1:قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَٰوَٰتِ\nT;0;21:56:2:وَٱلۡأَرۡضِ ٱلَّذِي فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَٰلِكُم مِّنَ ٱلشَّٰهِدِينَ\nT;0;21:57:3:وَتَٱللَّهِ لَأَكِيدَنَّ أَصۡنَٰمَكُم بَعۡدَ أَن تُوَلُّواْ مُدۡبِرِينَ',
  '17;33;2;\nT;0;21:58:3:فَجَعَلَهُمۡ جُذَٰذًا إِلَّا كَبِيرࣰا لَّهُمۡ لَعَلَّهُمۡ إِلَيۡهِ يَرۡجِعُونَ\nT;0;21:59:3:قَالُواْ مَن فَعَلَ هَٰذَا بِـَٔالِهَتِنَآ إِنَّهُۥ لَمِنَ ٱلظَّٰلِمِينَ\nT;0;21:60:3:قَالُواْ سَمِعۡنَا فَتࣰى يَذۡكُرُهُمۡ يُقَالُ لَهُۥٓ إِبۡرَٰهِيمُ¦21:61:1:قَالُواْ فَأۡتُواْ\nT;0;21:61:2:بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ¦21:62:1:قَالُوٓاْ ءَأَنتَ\nT;0;21:62:2:فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ¦21:63:1:قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ\nT;0;21:63:2:هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ¦21:64:1:فَرَجَعُوٓاْ إِلَىٰٓ\nT;0;21:64:2:أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّٰلِمُونَ¦21:65:1:ثُمَّ نُكِسُواْ\nT;0;21:65:2:عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ¦21:66:1:قَالَ\nT;0;21:66:0:أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـࣰٔا وَلَا\nT;0;21:66:2:يَضُرُّكُمۡ¦21:67:1:أُفࣲّ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ\nT;0;21:67:2:أَفَلَا تَعۡقِلُونَ¦21:68:1:قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ\nT;0;21:68:2:فَٰعِلِينَ¦21:69:3:قُلۡنَا يَٰنَارُ كُونِي بَرۡدࣰا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ\nT;0;21:70:3:وَأَرَادُواْ بِهِۦ كَيۡدࣰا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ¦21:71:1:وَنَجَّيۡنَٰهُ\nT;0;21:71:2:وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ¦21:72:1:وَوَهَبۡنَا\nT;0;21:72:2:لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةࣰۖ وَكُلࣰّا جَعَلۡنَا صَٰلِحِينَ',
  '17;33;2;\nT;0;21:73:1:وَجَعَلۡنَٰهُمۡ أَئِمَّةࣰ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ\nT;0;21:73:0:ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا\nT;0;21:73:2:عَٰبِدِينَ¦21:74:1:وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمࣰا وَعِلۡمࣰا وَنَجَّيۡنَٰهُ مِنَ\nT;0;21:74:0:ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءࣲ\nT;0;21:74:2:فَٰسِقِينَ¦21:75:3:وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ\nT;0;21:76:1:وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ\nT;0;21:76:2:وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ¦21:77:1:وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ\nT;0;21:77:0:ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءࣲ فَأَغۡرَقۡنَٰهُمۡ\nT;0;21:77:2:أَجۡمَعِينَ¦21:78:1:وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ\nT;0;21:78:2:إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ\nT;0;21:79:1:فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمࣰا وَعِلۡمࣰاۚ وَسَخَّرۡنَا\nT;0;21:79:2:مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ\nT;0;21:80:1:وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسࣲ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ\nT;0;21:80:2:فَهَلۡ أَنتُمۡ شَٰكِرُونَ¦21:81:1:وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةࣰ تَجۡرِي بِأَمۡرِهِۦٓ\nT;0;21:81:2:إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ',
  '17;33;2;132\nT;0;21:82:1:وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلࣰا دُونَ\nT;0;21:82:2:ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ¦21:83:1:۞ وَأَيُّوبَ إِذۡ نَادَىٰ\nT;0;21:83:2:رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ\nT;0;21:84:1:فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرࣲّۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ\nT;0;21:84:2:وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ\nT;0;21:85:3:وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلࣱّ مِّنَ ٱلصَّٰبِرِينَ\nT;0;21:86:3:وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ\nT;0;21:87:1:وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبࣰا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ\nT;0;21:87:0:فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي\nT;0;21:87:2:كُنتُ مِنَ ٱلظَّٰلِمِينَ¦21:88:1:فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ\nT;0;21:88:2:مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ¦21:89:1:وَزَكَرِيَّآ\nT;0;21:89:2:إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدࣰا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ\nT;0;21:90:1:فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا\nT;0;21:90:0:لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ\nT;0;21:90:2:وَيَدۡعُونَنَا رَغَبࣰا وَرَهَبࣰاۖ وَكَانُواْ لَنَا خَٰشِعِينَ',
  '17;33;3;\nT;0;21:91:1:وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا\nT;0;21:91:2:وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةࣰ لِّلۡعَٰلَمِينَ¦21:92:1:إِنَّ هَٰذِهِۦٓ\nT;0;21:92:2:أُمَّتُكُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ\nT;0;21:93:3:وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ\nT;0;21:94:1:فَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا كُفۡرَانَ\nT;0;21:94:2:لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ¦21:95:1:وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ\nT;0;21:95:2:أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ¦21:96:1:حَتَّىٰٓ إِذَا فُتِحَتۡ\nT;0;21:96:2:يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبࣲ يَنسِلُونَ\nT;0;21:97:1:وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ\nT;0;21:97:0:كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةࣲ مِّنۡ هَٰذَا بَلۡ كُنَّا\nT;0;21:97:2:ظَٰلِمِينَ¦21:98:1:إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ\nT;0;21:98:2:حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ¦21:99:1:لَوۡ كَانَ\nT;0;21:99:2:هَٰٓؤُلَآءِ ءَالِهَةࣰ مَّا وَرَدُوهَاۖ وَكُلࣱّ فِيهَا خَٰلِدُونَ\nT;0;21:100:3:لَهُمۡ فِيهَا زَفِيرࣱ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ¦21:101:1:إِنَّ ٱلَّذِينَ\nT;0;21:101:2:سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَٰٓئِكَ عَنۡهَا مُبۡعَدُونَ',
  '17;33;3;\nT;0;21:102:1:لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ\nT;0;21:102:2:خَٰلِدُونَ¦21:103:1:لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ\nT;0;21:103:2:ٱلۡمَلَٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ\nT;0;21:104:1:يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا\nT;0;21:104:0:بَدَأۡنَآ أَوَّلَ خَلۡقࣲ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا\nT;0;21:104:2:فَٰعِلِينَ¦21:105:1:وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ\nT;0;21:105:2:ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ\nT;0;21:106:3:إِنَّ فِي هَٰذَا لَبَلَٰغࣰا لِّقَوۡمٍ عَٰبِدِينَ¦21:107:1:وَمَآ أَرۡسَلۡنَٰكَ\nT;0;21:107:2:إِلَّا رَحۡمَةࣰ لِّلۡعَٰلَمِينَ¦21:108:1:قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ\nT;0;21:108:2:إِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ\nT;0;21:109:1:فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءࣲۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ\nT;0;21:109:2:أَم بَعِيدࣱ مَّا تُوعَدُونَ¦21:110:1:إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ\nT;0;21:110:2:ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ¦21:111:1:وَإِنۡ أَدۡرِي لَعَلَّهُۥ\nT;0;21:111:2:فِتۡنَةࣱ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينࣲ¦21:112:1:قَٰلَ رَبِّ ٱحۡكُم\nT;2;21:112:2:بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ',
  '17;34;0;133\nH;22\nB;22\nT;0;22:1:3:يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمࣱ\nT;0;22:2:1:يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ\nT;0;22:2:0:ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ\nT;0;22:2:2:وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدࣱ¦22:3:1:وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ\nT;0;22:3:2:بِغَيۡرِ عِلۡمࣲ وَيَتَّبِعُ كُلَّ شَيۡطَٰنࣲ مَّرِيدࣲ¦22:4:1:كُتِبَ عَلَيۡهِ أَنَّهُۥ\nT;0;22:4:2:مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ\nT;0;22:5:1:يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبࣲ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم\nT;0;22:5:0:مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ مِنۡ عَلَقَةࣲ ثُمَّ مِن مُّضۡغَةࣲ\nT;0;22:5:0:مُّخَلَّقَةࣲ وَغَيۡرِ مُخَلَّقَةࣲ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ\nT;0;22:5:0:إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى ثُمَّ نُخۡرِجُكُمۡ طِفۡلࣰا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ\nT;0;22:5:0:وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا\nT;0;22:5:0:يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمࣲ شَيۡـࣰٔاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةࣰ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا\nT;0;22:5:2:ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجࣲ',
  '17;34;0;\nT;0;22:6:1:ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءࣲ\nT;0;22:6:2:قَدِيرࣱ¦22:7:1:وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةࣱ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي\nT;0;22:7:2:ٱلۡقُبُورِ¦22:8:1:وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمࣲ وَلَا هُدࣰى\nT;0;22:8:2:وَلَا كِتَٰبࣲ مُّنِيرࣲ¦22:9:1:ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي\nT;0;22:9:2:ٱلدُّنۡيَا خِزۡيࣱۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ¦22:10:1:ذَٰلِكَ\nT;0;22:10:2:بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّٰمࣲ لِّلۡعَبِيدِ¦22:11:1:وَمِنَ ٱلنَّاسِ\nT;0;22:11:0:مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفࣲۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ\nT;0;22:11:0:أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ\nT;0;22:11:2:هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ¦22:12:1:يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ\nT;0;22:12:2:وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ¦22:13:1:يَدۡعُواْ لَمَن\nT;0;22:13:2:ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ\nT;0;22:14:1:إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتࣲ\nT;0;22:14:2:تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ¦22:15:1:مَن كَانَ\nT;0;22:15:0:يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى\nT;0;22:15:2:ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ',
  '17;34;0;134\nT;0;22:16:3:وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتࣲ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ\nT;0;22:17:1:إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ\nT;0;22:17:0:وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ\nT;0;22:17:2:ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ¦22:18:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ\nT;0;22:18:0:يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ\nT;0;22:18:0:وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرࣱ مِّنَ\nT;0;22:18:0:ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن\nT;0;22:18:2:مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩¦22:19:1:۞ هَٰذَانِ خَصۡمَانِ\nT;0;22:19:0:ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابࣱ\nT;0;22:19:2:مِّن نَّارࣲ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ¦22:20:1:يُصۡهَرُ بِهِۦ\nT;0;22:20:2:مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ¦22:21:3:وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدࣲ¦22:22:1:كُلَّمَآ\nT;0;22:22:0:أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ\nT;0;22:22:2:ٱلۡحَرِيقِ¦22:23:1:إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ\nT;0;22:23:0:جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ\nT;0;22:23:2:أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرࣱ',
  '17;34;1;\nT;0;22:24:3:وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ\nT;0;22:25:1:إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ\nT;0;22:25:0:ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ\nT;0;22:25:2:وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمࣲ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمࣲ\nT;0;22:26:1:وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ\nT;0;22:26:0:بِي شَيۡـࣰٔا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ\nT;0;22:26:2:ٱلسُّجُودِ¦22:27:1:وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالࣰا وَعَلَىٰ\nT;0;22:27:2:كُلِّ ضَامِرࣲ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقࣲ¦22:28:1:لِّيَشۡهَدُواْ\nT;0;22:28:0:مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامࣲ مَّعۡلُومَٰتٍ\nT;0;22:28:0:عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا\nT;0;22:28:2:وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ¦22:29:1:ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ\nT;0;22:29:2:وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ\nT;0;22:30:1:ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرࣱ لَّهُۥ عِندَ\nT;0;22:30:0:رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ\nT;0;22:30:2:فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ',
  '17;34;1;135\nT;0;22:31:1:حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ\nT;0;22:31:2:ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانࣲ سَحِيقࣲ\nT;0;22:32:3:ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ\nT;0;22:33:1:لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ\nT;0;22:33:2:ٱلۡعَتِيقِ¦22:34:1:وَلِكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكࣰا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ\nT;0;22:34:0:مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱ فَلَهُۥٓ\nT;0;22:34:2:أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ¦22:35:1:ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ\nT;0;22:35:0:قُلُوبُهُمۡ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ\nT;0;22:35:2:وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ¦22:36:1:وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَٰٓئِرِ\nT;0;22:36:0:ٱللَّهِ لَكُمۡ فِيهَا خَيۡرࣱۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ\nT;0;22:36:0:جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا\nT;0;22:36:2:لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ¦22:37:1:لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا\nT;0;22:37:0:وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ\nT;0;22:37:2:ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ¦22:38:1:۞ إِنَّ ٱللَّهَ يُدَٰفِعُ\nT;0;22:38:2:عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانࣲ كَفُورٍ',
  '17;34;2;\nT;0;22:39:1:أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ\nT;0;22:39:2:لَقَدِيرٌ¦22:40:1:ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ\nT;0;22:40:0:رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ\nT;0;22:40:0:صَوَٰمِعُ وَبِيَعࣱ وَصَلَوَٰتࣱ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ\nT;0;22:40:0:كَثِيرࣰاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ\nT;0;22:40:2:عَزِيزٌ¦22:41:1:ٱلَّذِينَ إِن مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ\nT;0;22:41:0:وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ\nT;0;22:41:2:وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ¦22:42:1:وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ\nT;0;22:42:2:قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَثَمُودُ¦22:43:1:وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ\nT;0;22:43:2:لُوطࣲ¦22:44:1:وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ\nT;0;22:44:2:ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ¦22:45:1:فَكَأَيِّن مِّن قَرۡيَةٍ\nT;0;22:45:0:أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةࣱ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرࣲ\nT;0;22:45:2:مُّعَطَّلَةࣲ وَقَصۡرࣲ مَّشِيدٍ¦22:46:1:أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ\nT;0;22:46:0:لَهُمۡ قُلُوبࣱ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانࣱ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا\nT;0;22:46:2:لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ',
  '17;34;2;\nT;0;22:47:1:وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا\nT;0;22:47:2:عِندَ رَبِّكَ كَأَلۡفِ سَنَةࣲ مِّمَّا تَعُدُّونَ¦22:48:1:وَكَأَيِّن مِّن قَرۡيَةٍ\nT;0;22:48:2:أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةࣱ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ\nT;0;22:49:3:قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرࣱ مُّبِينࣱ¦22:50:1:فَٱلَّذِينَ\nT;0;22:50:2:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِيمࣱ\nT;0;22:51:1:وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ أَصۡحَٰبُ\nT;0;22:51:2:ٱلۡجَحِيمِ¦22:52:1:وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولࣲ وَلَا نَبِيٍّ إِلَّآ\nT;0;22:52:0:إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي\nT;0;22:52:2:ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ¦22:53:1:لِّيَجۡعَلَ\nT;0;22:53:0:مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةࣰ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ وَٱلۡقَاسِيَةِ\nT;0;22:53:2:قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدࣲ¦22:54:1:وَلِيَعۡلَمَ\nT;0;22:54:0:ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ\nT;0;22:54:0:فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطࣲ\nT;0;22:54:2:مُّسۡتَقِيمࣲ¦22:55:1:وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةࣲ مِّنۡهُ حَتَّىٰ\nT;0;22:55:2:تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ',
  '17;34;2;136\nT;0;22:56:1:ٱلۡمُلۡكُ يَوۡمَئِذࣲ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ\nT;0;22:56:2:وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي جَنَّٰتِ ٱلنَّعِيمِ¦22:57:1:وَٱلَّذِينَ\nT;0;22:57:0:كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمۡ عَذَابࣱ\nT;0;22:57:2:مُّهِينࣱ¦22:58:1:وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ\nT;0;22:58:0:أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنࣰاۚ وَإِنَّ ٱللَّهَ لَهُوَ\nT;0;22:58:2:خَيۡرُ ٱلرَّٰزِقِينَ¦22:59:1:لَيُدۡخِلَنَّهُم مُّدۡخَلࣰا يَرۡضَوۡنَهُۥۚ\nT;0;22:59:2:وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمࣱ¦22:60:1:۞ ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ\nT;0;22:60:0:مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ\nT;0;22:60:2:لَعَفُوٌّ غَفُورࣱ¦22:61:1:ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي\nT;0;22:61:0:ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ\nT;0;22:61:2:بَصِيرࣱ¦22:62:1:ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ\nT;0;22:62:2:مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ\nT;0;22:63:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَتُصۡبِحُ ٱلۡأَرۡضُ\nT;0;22:63:2:مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرࣱ¦22:64:1:لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ\nT;0;22:64:2:وَمَا فِي ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ',
  '17;34;3;\nT;0;22:65:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي\nT;0;22:65:0:فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا\nT;0;22:65:2:بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِيمࣱ¦22:66:1:وَهُوَ ٱلَّذِيٓ\nT;0;22:66:2:أَحۡيَاكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورࣱ\nT;0;22:67:1:لِّكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ\nT;0;22:67:2:فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدࣰى مُّسۡتَقِيمࣲ\nT;0;22:68:3:وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ¦22:69:1:ٱللَّهُ يَحۡكُمُ\nT;0;22:69:2:بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ\nT;0;22:70:1:أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ\nT;0;22:70:2:ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣱ¦22:71:1:وَيَعۡبُدُونَ\nT;0;22:71:0:مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنࣰا وَمَا لَيۡسَ لَهُم بِهِۦ\nT;0;22:71:2:عِلۡمࣱۗ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرࣲ¦22:72:1:وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا\nT;0;22:72:0:بَيِّنَٰتࣲ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ\nT;0;22:72:0:يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرࣲّ مِّن\nT;0;22:72:2:ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ',
  '17;34;3;\nT;0;22:73:1:يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلࣱ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ\nT;0;22:73:0:تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابࣰا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ\nT;0;22:73:0:وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـࣰٔا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ\nT;0;22:73:2:ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ¦22:74:1:مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ\nT;0;22:74:2:إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ¦22:75:1:ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ\nT;0;22:75:2:رُسُلࣰا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرࣱ¦22:76:1:يَعۡلَمُ\nT;0;22:76:2:مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ\nT;0;22:77:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ\nT;0;22:77:2:رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩\nT;0;22:78:1:وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ\nT;0;22:78:0:وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجࣲۚ مِّلَّةَ أَبِيكُمۡ\nT;0;22:78:0:إِبۡرَٰهِيمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِينَ مِن قَبۡلُ وَفِي\nT;0;22:78:0:هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيۡكُمۡ وَتَكُونُواْ\nT;0;22:78:0:شُهَدَآءَ عَلَى ٱلنَّاسِۚ فَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ\nT;2;22:78:2:وَٱعۡتَصِمُواْ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ',
  '18;35;0;137\nH;23\nB;23\nT;0;23:1:3:قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ¦23:2:3:ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ\nT;0;23:3:3:وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ¦23:4:1:وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ\nT;0;23:4:2:فَٰعِلُونَ¦23:5:3:وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ¦23:6:1:إِلَّا عَلَىٰٓ\nT;0;23:6:2:أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ¦23:7:1:فَمَنِ ٱبۡتَغَىٰ\nT;0;23:7:2:وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ¦23:8:1:وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ\nT;0;23:8:2:وَعَهۡدِهِمۡ رَٰعُونَ¦23:9:3:وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ¦23:10:1:أُوْلَٰٓئِكَ\nT;0;23:10:2:هُمُ ٱلۡوَٰرِثُونَ¦23:11:3:ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ\nT;0;23:12:3:وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةࣲ مِّن طِينࣲ¦23:13:1:ثُمَّ جَعَلۡنَٰهُ نُطۡفَةࣰ\nT;0;23:13:2:فِي قَرَارࣲ مَّكِينࣲ¦23:14:1:ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةࣰ فَخَلَقۡنَا ٱلۡعَلَقَةَ\nT;0;23:14:0:مُضۡغَةࣰ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمࣰا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمࣰا ثُمَّ\nT;0;23:14:2:أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ¦23:15:1:ثُمَّ\nT;0;23:15:2:إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ¦23:16:3:ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ\nT;0;23:17:3:وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ',
  '18;35;0;\nT;0;23:18:1:وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرࣲ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ\nT;0;23:18:2:ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ¦23:19:1:فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتࣲ مِّن نَّخِيلࣲ\nT;0;23:19:2:وَأَعۡنَٰبࣲ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةࣱ وَمِنۡهَا تَأۡكُلُونَ¦23:20:1:وَشَجَرَةࣰ\nT;0;23:20:2:تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغࣲ لِّلۡأٓكِلِينَ\nT;0;23:21:1:وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةࣰۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا\nT;0;23:21:2:مَنَٰفِعُ كَثِيرَةࣱ وَمِنۡهَا تَأۡكُلُونَ¦23:22:3:وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ\nT;0;23:23:1:وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ\nT;0;23:23:2:مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ¦23:24:1:فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ\nT;0;23:24:0:كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ\nT;0;23:24:0:وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةࣰ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا\nT;0;23:24:2:ٱلۡأَوَّلِينَ¦23:25:3:إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةࣱ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينࣲ\nT;0;23:26:3:قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ¦23:27:1:فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ\nT;0;23:27:0:ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ\nT;0;23:27:0:فِيهَا مِن كُلࣲّ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ\nT;0;23:27:2:ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ',
  '18;35;0;138\nT;0;23:28:1:فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي\nT;0;23:28:2:نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ¦23:29:1:وَقُل رَّبِّ أَنزِلۡنِي مُنزَلࣰا مُّبَارَكࣰا وَأَنتَ\nT;0;23:29:2:خَيۡرُ ٱلۡمُنزِلِينَ¦23:30:3:إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ وَإِن كُنَّا لَمُبۡتَلِينَ¦23:31:1:ثُمَّ أَنشَأۡنَا\nT;0;23:31:2:مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ¦23:32:1:فَأَرۡسَلۡنَا فِيهِمۡ رَسُولࣰا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ\nT;0;23:32:2:ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ¦23:33:1:وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ\nT;0;23:33:0:ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا\nT;0;23:33:0:مَا هَٰذَآ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ\nT;0;23:33:2:مِمَّا تَشۡرَبُونَ¦23:34:3:وَلَئِنۡ أَطَعۡتُم بَشَرࣰا مِّثۡلَكُمۡ إِنَّكُمۡ إِذࣰا لَّخَٰسِرُونَ\nT;0;23:35:3:أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابࣰا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ\nT;0;23:36:3:۞ هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ¦23:37:1:إِنۡ هِيَ إِلَّا حَيَاتُنَا\nT;0;23:37:2:ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ¦23:38:1:إِنۡ هُوَ إِلَّا\nT;0;23:38:2:رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ¦23:39:1:قَالَ رَبِّ\nT;0;23:39:2:ٱنصُرۡنِي بِمَا كَذَّبُونِ¦23:40:3:قَالَ عَمَّا قَلِيلࣲ لَّيُصۡبِحُنَّ نَٰدِمِينَ\nT;0;23:41:1:فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءࣰۚ فَبُعۡدࣰا لِّلۡقَوۡمِ\nT;0;23:41:2:ٱلظَّٰلِمِينَ¦23:42:3:ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ',
  '18;35;1;\nT;0;23:43:3:مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ¦23:44:1:ثُمَّ أَرۡسَلۡنَا رُسُلَنَا\nT;0;23:44:0:تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةࣰ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضࣰا\nT;0;23:44:2:وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدࣰا لِّقَوۡمࣲ لَّا يُؤۡمِنُونَ¦23:45:1:ثُمَّ أَرۡسَلۡنَا مُوسَىٰ\nT;0;23:45:2:وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنࣲ مُّبِينٍ¦23:46:1:إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ\nT;0;23:46:2:فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ¦23:47:1:فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا\nT;0;23:47:2:وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ¦23:48:3:فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ\nT;0;23:49:3:وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ¦23:50:1:وَجَعَلۡنَا ٱبۡنَ\nT;0;23:50:2:مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةࣰ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةࣲ ذَاتِ قَرَارࣲ وَمَعِينࣲ\nT;0;23:51:1:يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا\nT;0;23:51:2:تَعۡمَلُونَ عَلِيمࣱ¦23:52:1:وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَأَنَا۠ رَبُّكُمۡ\nT;0;23:52:2:فَٱتَّقُونِ¦23:53:1:فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرࣰاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ\nT;0;23:53:2:فَرِحُونَ¦23:54:3:فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ¦23:55:1:أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم\nT;0;23:55:2:بِهِۦ مِن مَّالࣲ وَبَنِينَ¦23:56:3:نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ\nT;0;23:57:3:إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ¦23:58:1:وَٱلَّذِينَ هُم\nT;0;23:58:2:بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ¦23:59:3:وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ',
  '18;35;1;\nT;0;23:60:3:وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ\nT;0;23:61:3:أُوْلَٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ¦23:62:1:وَلَا نُكَلِّفُ\nT;0;23:62:2:نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبࣱ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ\nT;0;23:63:1:بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةࣲ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلࣱ مِّن دُونِ ذَٰلِكَ\nT;0;23:63:2:هُمۡ لَهَا عَٰمِلُونَ¦23:64:1:حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ\nT;0;23:64:2:يَجۡـَٔرُونَ¦23:65:3:لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ¦23:66:1:قَدۡ كَانَتۡ\nT;0;23:66:2:ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ\nT;0;23:67:3:مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرࣰا تَهۡجُرُونَ¦23:68:1:أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ\nT;0;23:68:2:جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ¦23:69:1:أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ\nT;0;23:69:2:فَهُمۡ لَهُۥ مُنكِرُونَ¦23:70:1:أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ\nT;0;23:70:2:وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ¦23:71:1:وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ\nT;0;23:71:0:ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ\nT;0;23:71:2:عَن ذِكۡرِهِم مُّعۡرِضُونَ¦23:72:1:أَمۡ تَسۡـَٔلُهُمۡ خَرۡجࣰا فَخَرَاجُ رَبِّكَ خَيۡرࣱۖ\nT;0;23:72:2:وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ¦23:73:3:وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ\nT;0;23:74:3:وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ',
  '18;35;2;139\nT;0;23:75:1:۞ وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرࣲّ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ\nT;0;23:75:2:يَعۡمَهُونَ¦23:76:1:وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ\nT;0;23:76:2:وَمَا يَتَضَرَّعُونَ¦23:77:1:حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابࣰا ذَا عَذَابࣲ شَدِيدٍ\nT;0;23:77:2:إِذَا هُمۡ فِيهِ مُبۡلِسُونَ¦23:78:1:وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ\nT;0;23:78:2:وَٱلۡأَفۡـِٔدَةَۚ قَلِيلࣰا مَّا تَشۡكُرُونَ¦23:79:1:وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ\nT;0;23:79:2:وَإِلَيۡهِ تُحۡشَرُونَ¦23:80:1:وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ\nT;0;23:80:2:ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ¦23:81:1:بَلۡ قَالُواْ مِثۡلَ مَا قَالَ\nT;0;23:81:2:ٱلۡأَوَّلُونَ¦23:82:1:قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَٰمًا أَءِنَّا\nT;0;23:82:2:لَمَبۡعُوثُونَ¦23:83:1:لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ\nT;0;23:83:2:إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ¦23:84:1:قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن\nT;0;23:84:2:فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ¦23:85:1:سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا\nT;0;23:85:2:تَذَكَّرُونَ¦23:86:1:قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ\nT;0;23:86:2:ٱلۡعَظِيمِ¦23:87:3:سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ¦23:88:1:قُلۡ مَنۢ\nT;0;23:88:0:بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءࣲ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن\nT;0;23:88:2:كُنتُمۡ تَعۡلَمُونَ¦23:89:3:سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ',
  '18;35;2;\nT;0;23:90:3:بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ¦23:91:1:مَا ٱتَّخَذَ ٱللَّهُ مِن\nT;0;23:91:0:وَلَدࣲ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذࣰا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ\nT;0;23:91:2:وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ\nT;0;23:92:3:عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ¦23:93:1:قُل رَّبِّ\nT;0;23:93:2:إِمَّا تُرِيَنِّي مَا يُوعَدُونَ¦23:94:3:رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ\nT;0;23:95:3:وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ¦23:96:1:ٱدۡفَعۡ بِٱلَّتِي\nT;0;23:96:2:هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ¦23:97:1:وَقُل رَّبِّ\nT;0;23:97:2:أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ¦23:98:1:وَأَعُوذُ بِكَ رَبِّ أَن\nT;0;23:98:2:يَحۡضُرُونِ¦23:99:1:حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ\nT;0;23:99:2:ٱرۡجِعُونِ¦23:100:1:لَعَلِّيٓ أَعۡمَلُ صَٰلِحࣰا فِيمَا تَرَكۡتُۚ كَلَّآۚ إِنَّهَا\nT;0;23:100:2:كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ\nT;0;23:101:3:فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذࣲ وَلَا يَتَسَآءَلُونَ\nT;0;23:102:3:فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ¦23:103:1:وَمَنۡ\nT;0;23:103:0:خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ\nT;0;23:103:2:خَٰلِدُونَ¦23:104:3:تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ',
  '18;35;2;\nT;0;23:105:3:أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ\nT;0;23:106:3:قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمࣰا ضَآلِّينَ\nT;0;23:107:3:رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ\nT;0;23:108:3:قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ¦23:109:1:إِنَّهُۥ كَانَ فَرِيقࣱ مِّنۡ\nT;0;23:109:0:عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ\nT;0;23:109:2:خَيۡرُ ٱلرَّٰحِمِينَ¦23:110:1:فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي\nT;0;23:110:2:وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ¦23:111:1:إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ\nT;0;23:111:2:أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ¦23:112:1:قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ\nT;0;23:112:2:سِنِينَ¦23:113:3:قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمࣲ فَسۡـَٔلِ ٱلۡعَآدِّينَ\nT;0;23:114:3:قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلࣰاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ\nT;0;23:115:3:أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثࣰا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ\nT;0;23:116:3:فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ\nT;0;23:117:1:وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ\nT;0;23:117:2:فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ\nT;2;23:118:3:وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ',
  '18;35;3;140\nH;24\nB;24\nT;0;24:1:3:سُورَةٌ أَنزَلۡنَٰهَا وَفَرَضۡنَٰهَا وَأَنزَلۡنَا فِيهَآ ءَايَٰتِۭ بَيِّنَٰتࣲ لَّعَلَّكُمۡ تَذَكَّرُونَ\nT;0;24:2:1:ٱلزَّانِيَةُ وَٱلزَّانِي فَٱجۡلِدُواْ كُلَّ وَٰحِدࣲ مِّنۡهُمَا مِاْئَةَ جَلۡدَةࣲۖ وَلَا تَأۡخُذۡكُم بِهِمَا\nT;0;24:2:0:رَأۡفَةࣱ فِي دِينِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ وَلۡيَشۡهَدۡ عَذَابَهُمَا\nT;0;24:2:2:طَآئِفَةࣱ مِّنَ ٱلۡمُؤۡمِنِينَ¦24:3:1:ٱلزَّانِي لَا يَنكِحُ إِلَّا زَانِيَةً أَوۡ مُشۡرِكَةࣰ وَٱلزَّانِيَةُ\nT;0;24:3:2:لَا يَنكِحُهَآ إِلَّا زَانٍ أَوۡ مُشۡرِكࣱۚ وَحُرِّمَ ذَٰلِكَ عَلَى ٱلۡمُؤۡمِنِينَ¦24:4:1:وَٱلَّذِينَ\nT;0;24:4:0:يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ ثُمَّ لَمۡ يَأۡتُواْ بِأَرۡبَعَةِ شُهَدَآءَ فَٱجۡلِدُوهُمۡ ثَمَٰنِينَ\nT;0;24:4:2:جَلۡدَةࣰ وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدࣰاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ¦24:5:1:إِلَّا\nT;0;24:5:2:ٱلَّذِينَ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُواْ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ¦24:6:1:وَٱلَّذِينَ\nT;0;24:6:0:يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ\nT;0;24:6:2:شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ¦24:7:1:وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ\nT;0;24:7:2:إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ¦24:8:1:وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ\nT;0;24:8:2:بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ¦24:9:1:وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ\nT;0;24:9:2:ٱلصَّٰدِقِينَ¦24:10:3:وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِيمٌ',
  '18;35;3;\nT;0;24:11:1:إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةࣱ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرࣰّا لَّكُمۖ بَلۡ\nT;0;24:11:0:هُوَ خَيۡرࣱ لَّكُمۡۚ لِكُلِّ ٱمۡرِيࣲٕ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ\nT;0;24:11:2:كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمࣱ¦24:12:1:لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ\nT;0;24:12:2:وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرࣰا وَقَالُواْ هَٰذَآ إِفۡكࣱ مُّبِينࣱ¦24:13:1:لَّوۡلَا\nT;0;24:13:0:جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَٰٓئِكَ\nT;0;24:13:2:عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ¦24:14:1:وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ\nT;0;24:14:2:فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ\nT;0;24:15:1:إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمࣱ\nT;0;24:15:2:وَتَحۡسَبُونَهُۥ هَيِّنࣰا وَهُوَ عِندَ ٱللَّهِ عَظِيمࣱ¦24:16:1:وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ\nT;0;24:16:0:قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ\nT;0;24:16:2:عَظِيمࣱ¦24:17:1:يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم\nT;0;24:17:2:مُّؤۡمِنِينَ¦24:18:3:وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ¦24:19:1:إِنَّ\nT;0;24:19:0:ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ\nT;0;24:19:2:أَلِيمࣱ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ¦24:20:1:وَلَوۡلَا\nT;0;24:20:2:فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفࣱ رَّحِيمࣱ',
  '18;36;0;141\nT;0;24:21:1:۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ\nT;0;24:21:0:خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا\nT;0;24:21:0:فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدࣰا وَلَٰكِنَّ\nT;0;24:21:2:ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ¦24:22:1:وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ\nT;0;24:22:0:مِنكُمۡ وَٱلسَّعَةِ أَن يُؤۡتُوٓاْ أُوْلِي ٱلۡقُرۡبَىٰ وَٱلۡمَسَٰكِينَ وَٱلۡمُهَٰجِرِينَ\nT;0;24:22:0:فِي سَبِيلِ ٱللَّهِۖ وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ أَلَا تُحِبُّونَ أَن يَغۡفِرَ ٱللَّهُ\nT;0;24:22:2:لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِيمٌ¦24:23:1:إِنَّ ٱلَّذِينَ يَرۡمُونَ ٱلۡمُحۡصَنَٰتِ\nT;0;24:23:0:ٱلۡغَٰفِلَٰتِ ٱلۡمُؤۡمِنَٰتِ لُعِنُواْ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَلَهُمۡ عَذَابٌ\nT;0;24:23:2:عَظِيمࣱ¦24:24:1:يَوۡمَ تَشۡهَدُ عَلَيۡهِمۡ أَلۡسِنَتُهُمۡ وَأَيۡدِيهِمۡ وَأَرۡجُلُهُم بِمَا\nT;0;24:24:2:كَانُواْ يَعۡمَلُونَ¦24:25:1:يَوۡمَئِذࣲ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ\nT;0;24:25:2:ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ¦24:26:1:ٱلۡخَبِيثَٰتُ لِلۡخَبِيثِينَ وَٱلۡخَبِيثُونَ\nT;0;24:26:0:لِلۡخَبِيثَٰتِۖ وَٱلطَّيِّبَٰتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَٰتِۚ\nT;0;24:26:2:أُوْلَٰٓئِكَ مُبَرَّءُونَ مِمَّا يَقُولُونَۖ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِيمࣱ¦24:27:1:يَٰٓأَيُّهَا\nT;0;24:27:0:ٱلَّذِينَ ءَامَنُواْ لَا تَدۡخُلُواْ بُيُوتًا غَيۡرَ بُيُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُواْ\nT;0;24:27:2:وَتُسَلِّمُواْ عَلَىٰٓ أَهۡلِهَاۚ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ',
  '18;36;0;\nT;0;24:28:1:فَإِن لَّمۡ تَجِدُواْ فِيهَآ أَحَدࣰا فَلَا تَدۡخُلُوهَا حَتَّىٰ يُؤۡذَنَ لَكُمۡۖ\nT;0;24:28:0:وَإِن قِيلَ لَكُمُ ٱرۡجِعُواْ فَٱرۡجِعُواْۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا\nT;0;24:28:2:تَعۡمَلُونَ عَلِيمࣱ¦24:29:1:لَّيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَدۡخُلُواْ بُيُوتًا\nT;0;24:29:0:غَيۡرَ مَسۡكُونَةࣲ فِيهَا مَتَٰعࣱ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ مَا تُبۡدُونَ وَمَا\nT;0;24:29:2:تَكۡتُمُونَ¦24:30:1:قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ\nT;0;24:30:2:فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ\nT;0;24:31:1:وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ\nT;0;24:31:0:فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ\nT;0;24:31:0:بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ\nT;0;24:31:0:أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ\nT;0;24:31:0:أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ\nT;0;24:31:0:أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ\nT;0;24:31:0:ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ\nT;0;24:31:0:وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ\nT;0;24:31:2:إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ',
  '18;36;0;142\nT;0;24:32:1:وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن\nT;0;24:32:2:يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمࣱ\nT;0;24:33:1:وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ\nT;0;24:33:0:وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ\nT;0;24:33:0:عَلِمۡتُمۡ فِيهِمۡ خَيۡرࣰاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ\nT;0;24:33:0:فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنࣰا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ\nT;0;24:33:2:ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورࣱ رَّحِيمࣱ\nT;0;24:34:1:وَلَقَدۡ أَنزَلۡنَآ إِلَيۡكُمۡ ءَايَٰتࣲ مُّبَيِّنَٰتࣲ وَمَثَلࣰا مِّنَ ٱلَّذِينَ خَلَوۡاْ\nT;0;24:34:2:مِن قَبۡلِكُمۡ وَمَوۡعِظَةࣰ لِّلۡمُتَّقِينَ¦24:35:1:۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ\nT;0;24:35:0:مَثَلُ نُورِهِۦ كَمِشۡكَوٰةࣲ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ\nT;0;24:35:0:ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبࣱ دُرِّيࣱّ يُوقَدُ مِن شَجَرَةࣲ مُّبَٰرَكَةࣲ زَيۡتُونَةࣲ\nT;0;24:35:0:لَّا شَرۡقِيَّةࣲ وَلَا غَرۡبِيَّةࣲ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارࣱۚ\nT;0;24:35:0:نُّورٌ عَلَىٰ نُورࣲۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ\nT;0;24:35:2:لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣱ¦24:36:1:فِي بُيُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ\nT;0;24:36:2:وَيُذۡكَرَ فِيهَا ٱسۡمُهُۥ يُسَبِّحُ لَهُۥ فِيهَا بِٱلۡغُدُوِّ وَٱلۡأٓصَالِ',
  '18;36;1;\nT;0;24:37:1:رِجَالࣱ لَّا تُلۡهِيهِمۡ تِجَٰرَةࣱ وَلَا بَيۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ\nT;0;24:37:2:وَإِيتَآءِ ٱلزَّكَوٰةِ يَخَافُونَ يَوۡمࣰا تَتَقَلَّبُ فِيهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَٰرُ\nT;0;24:38:1:لِيَجۡزِيَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُواْ وَيَزِيدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ\nT;0;24:38:2:يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابࣲ¦24:39:1:وَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۭ\nT;0;24:39:0:بِقِيعَةࣲ يَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَآءً حَتَّىٰٓ إِذَا جَآءَهُۥ لَمۡ يَجِدۡهُ شَيۡـࣰٔا\nT;0;24:39:2:وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥۗ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ\nT;0;24:40:1:أَوۡ كَظُلُمَٰتࣲ فِي بَحۡرࣲ لُّجِّيࣲّ يَغۡشَىٰهُ مَوۡجࣱ مِّن فَوۡقِهِۦ مَوۡجࣱ مِّن فَوۡقِهِۦ\nT;0;24:40:0:سَحَابࣱۚ ظُلُمَٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَآ أَخۡرَجَ يَدَهُۥ لَمۡ يَكَدۡ\nT;0;24:40:2:يَرَىٰهَاۗ وَمَن لَّمۡ يَجۡعَلِ ٱللَّهُ لَهُۥ نُورࣰا فَمَا لَهُۥ مِن نُّورٍ¦24:41:1:أَلَمۡ تَرَ أَنَّ\nT;0;24:41:0:ٱللَّهَ يُسَبِّحُ لَهُۥ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱلطَّيۡرُ صَٰٓفَّٰتࣲۖ كُلࣱّ\nT;0;24:41:2:قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِيحَهُۥۗ وَٱللَّهُ عَلِيمُۢ بِمَا يَفۡعَلُونَ¦24:42:1:وَلِلَّهِ مُلۡكُ\nT;0;24:42:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِلَى ٱللَّهِ ٱلۡمَصِيرُ¦24:43:1:أَلَمۡ تَرَ أَنَّ ٱللَّهَ يُزۡجِي\nT;0;24:43:0:سَحَابࣰا ثُمَّ يُؤَلِّفُ بَيۡنَهُۥ ثُمَّ يَجۡعَلُهُۥ رُكَامࣰا فَتَرَى ٱلۡوَدۡقَ يَخۡرُجُ مِنۡ\nT;0;24:43:0:خِلَٰلِهِۦ وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مِن جِبَالࣲ فِيهَا مِنۢ بَرَدࣲ فَيُصِيبُ بِهِۦ مَن يَشَآءُ\nT;0;24:43:2:وَيَصۡرِفُهُۥ عَن مَّن يَشَآءُۖ يَكَادُ سَنَا بَرۡقِهِۦ يَذۡهَبُ بِٱلۡأَبۡصَٰرِ',
  '18;36;1;143\nT;0;24:44:3:يُقَلِّبُ ٱللَّهُ ٱلَّيۡلَ وَٱلنَّهَارَۚ إِنَّ فِي ذَٰلِكَ لَعِبۡرَةࣰ لِّأُوْلِي ٱلۡأَبۡصَٰرِ\nT;0;24:45:1:وَٱللَّهُ خَلَقَ كُلَّ دَآبَّةࣲ مِّن مَّآءࣲۖ فَمِنۡهُم مَّن يَمۡشِي عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن\nT;0;24:45:0:يَمۡشِي عَلَىٰ رِجۡلَيۡنِ وَمِنۡهُم مَّن يَمۡشِي عَلَىٰٓ أَرۡبَعࣲۚ يَخۡلُقُ ٱللَّهُ مَا يَشَآءُۚ\nT;0;24:45:2:إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ¦24:46:1:لَّقَدۡ أَنزَلۡنَآ ءَايَٰتࣲ مُّبَيِّنَٰتࣲۚ\nT;0;24:46:2:وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ¦24:47:1:وَيَقُولُونَ\nT;0;24:47:0:ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ يَتَوَلَّىٰ فَرِيقࣱ مِّنۡهُم مِّنۢ بَعۡدِ\nT;0;24:47:2:ذَٰلِكَۚ وَمَآ أُوْلَٰٓئِكَ بِٱلۡمُؤۡمِنِينَ¦24:48:1:وَإِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ\nT;0;24:48:2:لِيَحۡكُمَ بَيۡنَهُمۡ إِذَا فَرِيقࣱ مِّنۡهُم مُّعۡرِضُونَ¦24:49:1:وَإِن يَكُن لَّهُمُ ٱلۡحَقُّ\nT;0;24:49:2:يَأۡتُوٓاْ إِلَيۡهِ مُذۡعِنِينَ¦24:50:1:أَفِي قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوٓاْ أَمۡ يَخَافُونَ\nT;0;24:50:2:أَن يَحِيفَ ٱللَّهُ عَلَيۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُوْلَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ¦24:51:1:إِنَّمَا\nT;0;24:51:0:كَانَ قَوۡلَ ٱلۡمُؤۡمِنِينَ إِذَا دُعُوٓاْ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحۡكُمَ بَيۡنَهُمۡ أَن\nT;0;24:51:2:يَقُولُواْ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ¦24:52:1:وَمَن\nT;0;24:52:2:يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخۡشَ ٱللَّهَ وَيَتَّقۡهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ\nT;0;24:53:1:۞ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَئِنۡ أَمَرۡتَهُمۡ لَيَخۡرُجُنَّۖ قُل\nT;0;24:53:2:لَّا تُقۡسِمُواْۖ طَاعَةࣱ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ',
  '18;36;2;\nT;0;24:54:1:قُلۡ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡهِ مَا حُمِّلَ\nT;0;24:54:0:وَعَلَيۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِيعُوهُ تَهۡتَدُواْۚ وَمَا عَلَى ٱلرَّسُولِ\nT;0;24:54:2:إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ¦24:55:1:وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَعَمِلُواْ\nT;0;24:55:0:ٱلصَّٰلِحَٰتِ لَيَسۡتَخۡلِفَنَّهُمۡ فِي ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ\nT;0;24:55:0:ٱلَّذِينَ مِن قَبۡلِهِمۡ وَلَيُمَكِّنَنَّ لَهُمۡ دِينَهُمُ ٱلَّذِي ٱرۡتَضَىٰ\nT;0;24:55:0:لَهُمۡ وَلَيُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنࣰاۚ يَعۡبُدُونَنِي لَا يُشۡرِكُونَ\nT;0;24:55:2:بِي شَيۡـࣰٔاۚ وَمَن كَفَرَ بَعۡدَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡفَٰسِقُونَ\nT;0;24:56:1:وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَطِيعُواْ ٱلرَّسُولَ لَعَلَّكُمۡ\nT;0;24:56:2:تُرۡحَمُونَ¦24:57:1:لَا تَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ مُعۡجِزِينَ فِي ٱلۡأَرۡضِۚ\nT;0;24:57:2:وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِيرُ¦24:58:1:يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ\nT;0;24:58:0:لِيَسۡتَـٔۡذِنكُمُ ٱلَّذِينَ مَلَكَتۡ أَيۡمَٰنُكُمۡ وَٱلَّذِينَ لَمۡ يَبۡلُغُواْ ٱلۡحُلُمَ مِنكُمۡ\nT;0;24:58:0:ثَلَٰثَ مَرَّٰتࣲۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِينَ تَضَعُونَ ثِيَابَكُم مِّنَ\nT;0;24:58:0:ٱلظَّهِيرَةِ وَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَآءِۚ ثَلَٰثُ عَوۡرَٰتࣲ لَّكُمۡۚ لَيۡسَ عَلَيۡكُمۡ\nT;0;24:58:0:وَلَا عَلَيۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّٰفُونَ عَلَيۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضࣲۚ\nT;0;24:58:2:كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۗ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ',
  '18;36;2;\nT;0;24:59:1:وَإِذَا بَلَغَ ٱلۡأَطۡفَٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡيَسۡتَـٔۡذِنُواْ كَمَا\nT;0;24:59:0:ٱسۡتَـٔۡذَنَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ\nT;0;24:59:2:ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ¦24:60:1:وَٱلۡقَوَٰعِدُ مِنَ ٱلنِّسَآءِ\nT;0;24:60:0:ٱلَّٰتِي لَا يَرۡجُونَ نِكَاحࣰا فَلَيۡسَ عَلَيۡهِنَّ جُنَاحٌ أَن يَضَعۡنَ\nT;0;24:60:0:ثِيَابَهُنَّ غَيۡرَ مُتَبَرِّجَٰتِۭ بِزِينَةࣲۖ وَأَن يَسۡتَعۡفِفۡنَ خَيۡرࣱ\nT;0;24:60:2:لَّهُنَّۗ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ¦24:61:1:لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجࣱ وَلَا\nT;0;24:61:0:عَلَى ٱلۡأَعۡرَجِ حَرَجࣱ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجࣱ وَلَا عَلَىٰٓ أَنفُسِكُمۡ\nT;0;24:61:0:أَن تَأۡكُلُواْ مِنۢ بُيُوتِكُمۡ أَوۡ بُيُوتِ ءَابَآئِكُمۡ أَوۡ بُيُوتِ\nT;0;24:61:0:أُمَّهَٰتِكُمۡ أَوۡ بُيُوتِ إِخۡوَٰنِكُمۡ أَوۡ بُيُوتِ أَخَوَٰتِكُمۡ\nT;0;24:61:0:أَوۡ بُيُوتِ أَعۡمَٰمِكُمۡ أَوۡ بُيُوتِ عَمَّٰتِكُمۡ أَوۡ بُيُوتِ\nT;0;24:61:0:أَخۡوَٰلِكُمۡ أَوۡ بُيُوتِ خَٰلَٰتِكُمۡ أَوۡ مَا مَلَكۡتُم\nT;0;24:61:0:مَّفَاتِحَهُۥٓ أَوۡ صَدِيقِكُمۡۚ لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن\nT;0;24:61:0:تَأۡكُلُواْ جَمِيعًا أَوۡ أَشۡتَاتࣰاۚ فَإِذَا دَخَلۡتُم بُيُوتࣰا فَسَلِّمُواْ\nT;0;24:61:0:عَلَىٰٓ أَنفُسِكُمۡ تَحِيَّةࣰ مِّنۡ عِندِ ٱللَّهِ مُبَٰرَكَةࣰ طَيِّبَةࣰۚ كَذَٰلِكَ\nT;0;24:61:2:يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ',
  '18;36;2;144\nT;0;24:62:1:إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُواْ مَعَهُۥ\nT;0;24:62:0:عَلَىٰٓ أَمۡرࣲ جَامِعࣲ لَّمۡ يَذۡهَبُواْ حَتَّىٰ يَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِينَ يَسۡتَـٔۡذِنُونَكَ\nT;0;24:62:0:أُوْلَٰٓئِكَ ٱلَّذِينَ يُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ\nT;0;24:62:0:لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ\nT;0;24:62:2:ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ¦24:63:1:لَّا تَجۡعَلُواْ دُعَآءَ ٱلرَّسُولِ\nT;0;24:63:0:بَيۡنَكُمۡ كَدُعَآءِ بَعۡضِكُم بَعۡضࣰاۚ قَدۡ يَعۡلَمُ ٱللَّهُ ٱلَّذِينَ\nT;0;24:63:0:يَتَسَلَّلُونَ مِنكُمۡ لِوَاذࣰاۚ فَلۡيَحۡذَرِ ٱلَّذِينَ يُخَالِفُونَ عَنۡ\nT;0;24:63:2:أَمۡرِهِۦٓ أَن تُصِيبَهُمۡ فِتۡنَةٌ أَوۡ يُصِيبَهُمۡ عَذَابٌ أَلِيمٌ¦24:64:1:أَلَآ إِنَّ\nT;0;24:64:0:لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ قَدۡ يَعۡلَمُ مَآ أَنتُمۡ عَلَيۡهِ وَيَوۡمَ\nT;2;24:64:2:يُرۡجَعُونَ إِلَيۡهِ فَيُنَبِّئُهُم بِمَا عَمِلُواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ\nH;25\nB;25\nT;0;25:1:3:تَبَارَكَ ٱلَّذِي نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِيَكُونَ لِلۡعَٰلَمِينَ نَذِيرًا\nT;0;25:2:1:ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَمۡ يَتَّخِذۡ وَلَدࣰا وَلَمۡ يَكُن\nT;0;25:2:2:لَّهُۥ شَرِيكࣱ فِي ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَيۡءࣲ فَقَدَّرَهُۥ تَقۡدِيرࣰا',
  '18;36;3;\nT;0;25:3:1:وَٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةࣰ لَّا يَخۡلُقُونَ شَيۡـࣰٔا وَهُمۡ يُخۡلَقُونَ\nT;0;25:3:0:وَلَا يَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرࣰّا وَلَا نَفۡعࣰا وَلَا يَمۡلِكُونَ مَوۡتࣰا\nT;0;25:3:2:وَلَا حَيَوٰةࣰ وَلَا نُشُورࣰا¦25:4:1:وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّآ\nT;0;25:4:0:إِفۡكٌ ٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَيۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَآءُو ظُلۡمࣰا\nT;0;25:4:2:وَزُورࣰا¦25:5:1:وَقَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ٱكۡتَتَبَهَا فَهِيَ تُمۡلَىٰ\nT;0;25:5:2:عَلَيۡهِ بُكۡرَةࣰ وَأَصِيلࣰا¦25:6:1:قُلۡ أَنزَلَهُ ٱلَّذِي يَعۡلَمُ ٱلسِّرَّ\nT;0;25:6:2:فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورࣰا رَّحِيمࣰا\nT;0;25:7:1:وَقَالُواْ مَالِ هَٰذَا ٱلرَّسُولِ يَأۡكُلُ ٱلطَّعَامَ وَيَمۡشِي فِي\nT;0;25:7:2:ٱلۡأَسۡوَاقِ لَوۡلَآ أُنزِلَ إِلَيۡهِ مَلَكࣱ فَيَكُونَ مَعَهُۥ نَذِيرًا\nT;0;25:8:1:أَوۡ يُلۡقَىٰٓ إِلَيۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةࣱ يَأۡكُلُ مِنۡهَاۚ وَقَالَ\nT;0;25:8:2:ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلࣰا مَّسۡحُورًا¦25:9:1:ٱنظُرۡ\nT;0;25:9:0:كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَٰلَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ\nT;0;25:9:2:سَبِيلࣰا¦25:10:1:تَبَارَكَ ٱلَّذِيٓ إِن شَآءَ جَعَلَ لَكَ خَيۡرࣰا مِّن ذَٰلِكَ\nT;0;25:10:2:جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ وَيَجۡعَل لَّكَ قُصُورَۢا¦25:11:1:بَلۡ\nT;0;25:11:2:كَذَّبُواْ بِٱلسَّاعَةِۖ وَأَعۡتَدۡنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِيرًا',
  '18;36;3;\nT;0;25:12:3:إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِيدࣲ سَمِعُواْ لَهَا تَغَيُّظࣰا وَزَفِيرࣰا\nT;0;25:13:3:وَإِذَآ أُلۡقُواْ مِنۡهَا مَكَانࣰا ضَيِّقࣰا مُّقَرَّنِينَ دَعَوۡاْ هُنَالِكَ ثُبُورࣰا\nT;0;25:14:3:لَّا تَدۡعُواْ ٱلۡيَوۡمَ ثُبُورࣰا وَٰحِدࣰا وَٱدۡعُواْ ثُبُورࣰا كَثِيرࣰا\nT;0;25:15:1:قُلۡ أَذَٰلِكَ خَيۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ\nT;0;25:15:2:لَهُمۡ جَزَآءࣰ وَمَصِيرࣰا¦25:16:1:لَّهُمۡ فِيهَا مَا يَشَآءُونَ خَٰلِدِينَۚ\nT;0;25:16:2:كَانَ عَلَىٰ رَبِّكَ وَعۡدࣰا مَّسۡـُٔولࣰا¦25:17:1:وَيَوۡمَ يَحۡشُرُهُمۡ وَمَا\nT;0;25:17:0:يَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَيَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِي\nT;0;25:17:2:هَٰٓؤُلَآءِ أَمۡ هُمۡ ضَلُّواْ ٱلسَّبِيلَ¦25:18:1:قَالُواْ سُبۡحَٰنَكَ مَا كَانَ\nT;0;25:18:0:يَنۢبَغِي لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِيَآءَ وَلَٰكِن مَّتَّعۡتَهُمۡ\nT;0;25:18:2:وَءَابَآءَهُمۡ حَتَّىٰ نَسُواْ ٱلذِّكۡرَ وَكَانُواْ قَوۡمَۢا بُورࣰا\nT;0;25:19:1:فَقَدۡ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِيعُونَ صَرۡفࣰا\nT;0;25:19:2:وَلَا نَصۡرࣰاۚ وَمَن يَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابࣰا كَبِيرࣰا\nT;0;25:20:1:وَمَآ أَرۡسَلۡنَا قَبۡلَكَ مِنَ ٱلۡمُرۡسَلِينَ إِلَّآ إِنَّهُمۡ لَيَأۡكُلُونَ\nT;0;25:20:0:ٱلطَّعَامَ وَيَمۡشُونَ فِي ٱلۡأَسۡوَاقِۗ وَجَعَلۡنَا بَعۡضَكُمۡ\nT;0;25:20:2:لِبَعۡضࣲ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِيرࣰا',
  '19;37;0;145\nT;0;25:21:1:۞ وَقَالَ ٱلَّذِينَ لَا يَرۡجُونَ لِقَآءَنَا لَوۡلَآ أُنزِلَ عَلَيۡنَا ٱلۡمَلَٰٓئِكَةُ\nT;0;25:21:2:أَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُواْ فِيٓ أَنفُسِهِمۡ وَعَتَوۡ عُتُوࣰّا كَبِيرࣰا\nT;0;25:22:1:يَوۡمَ يَرَوۡنَ ٱلۡمَلَٰٓئِكَةَ لَا بُشۡرَىٰ يَوۡمَئِذࣲ لِّلۡمُجۡرِمِينَ وَيَقُولُونَ\nT;0;25:22:2:حِجۡرࣰا مَّحۡجُورࣰا¦25:23:1:وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلࣲ فَجَعَلۡنَٰهُ\nT;0;25:23:2:هَبَآءࣰ مَّنثُورًا¦25:24:1:أَصۡحَٰبُ ٱلۡجَنَّةِ يَوۡمَئِذٍ خَيۡرࣱ مُّسۡتَقَرࣰّا\nT;0;25:24:2:وَأَحۡسَنُ مَقِيلࣰا¦25:25:1:وَيَوۡمَ تَشَقَّقُ ٱلسَّمَآءُ بِٱلۡغَمَٰمِ وَنُزِّلَ ٱلۡمَلَٰٓئِكَةُ\nT;0;25:25:2:تَنزِيلًا¦25:26:1:ٱلۡمُلۡكُ يَوۡمَئِذٍ ٱلۡحَقُّ لِلرَّحۡمَٰنِۚ وَكَانَ يَوۡمًا عَلَى\nT;0;25:26:2:ٱلۡكَٰفِرِينَ عَسِيرࣰا¦25:27:1:وَيَوۡمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيۡهِ يَقُولُ\nT;0;25:27:2:يَٰلَيۡتَنِي ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِيلࣰا¦25:28:1:يَٰوَيۡلَتَىٰ لَيۡتَنِي لَمۡ\nT;0;25:28:2:أَتَّخِذۡ فُلَانًا خَلِيلࣰا¦25:29:1:لَّقَدۡ أَضَلَّنِي عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَآءَنِيۗ\nT;0;25:29:2:وَكَانَ ٱلشَّيۡطَٰنُ لِلۡإِنسَٰنِ خَذُولࣰا¦25:30:1:وَقَالَ ٱلرَّسُولُ يَٰرَبِّ\nT;0;25:30:2:إِنَّ قَوۡمِي ٱتَّخَذُواْ هَٰذَا ٱلۡقُرۡءَانَ مَهۡجُورࣰا¦25:31:1:وَكَذَٰلِكَ\nT;0;25:31:0:جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوࣰّا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيࣰا\nT;0;25:31:2:وَنَصِيرࣰا¦25:32:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةࣰ\nT;0;25:32:2:وَٰحِدَةࣰۚ كَذَٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَٰهُ تَرۡتِيلࣰا',
  '19;37;0;\nT;0;25:33:3:وَلَا يَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِيرًا\nT;0;25:34:1:ٱلَّذِينَ يُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُوْلَٰٓئِكَ\nT;0;25:34:2:شَرࣱّ مَّكَانࣰا وَأَضَلُّ سَبِيلࣰا¦25:35:1:وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ\nT;0;25:35:2:وَجَعَلۡنَا مَعَهُۥٓ أَخَاهُ هَٰرُونَ وَزِيرࣰا¦25:36:1:فَقُلۡنَا ٱذۡهَبَآ\nT;0;25:36:2:إِلَى ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا فَدَمَّرۡنَٰهُمۡ تَدۡمِيرࣰا\nT;0;25:37:1:وَقَوۡمَ نُوحࣲ لَّمَّا كَذَّبُواْ ٱلرُّسُلَ أَغۡرَقۡنَٰهُمۡ وَجَعَلۡنَٰهُمۡ لِلنَّاسِ\nT;0;25:37:2:ءَايَةࣰۖ وَأَعۡتَدۡنَا لِلظَّٰلِمِينَ عَذَابًا أَلِيمࣰا¦25:38:1:وَعَادࣰا وَثَمُودَاْ\nT;0;25:38:2:وَأَصۡحَٰبَ ٱلرَّسِّ وَقُرُونَۢا بَيۡنَ ذَٰلِكَ كَثِيرࣰا¦25:39:1:وَكُلࣰّا\nT;0;25:39:2:ضَرَبۡنَا لَهُ ٱلۡأَمۡثَٰلَۖ وَكُلࣰّا تَبَّرۡنَا تَتۡبِيرࣰا¦25:40:1:وَلَقَدۡ أَتَوۡاْ عَلَى\nT;0;25:40:0:ٱلۡقَرۡيَةِ ٱلَّتِيٓ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ يَكُونُواْ يَرَوۡنَهَاۚ\nT;0;25:40:2:بَلۡ كَانُواْ لَا يَرۡجُونَ نُشُورࣰا¦25:41:1:وَإِذَا رَأَوۡكَ إِن يَتَّخِذُونَكَ\nT;0;25:41:2:إِلَّا هُزُوًا أَهَٰذَا ٱلَّذِي بَعَثَ ٱللَّهُ رَسُولًا¦25:42:1:إِن كَادَ\nT;0;25:42:0:لَيُضِلُّنَا عَنۡ ءَالِهَتِنَا لَوۡلَآ أَن صَبَرۡنَا عَلَيۡهَاۚ وَسَوۡفَ\nT;0;25:42:2:يَعۡلَمُونَ حِينَ يَرَوۡنَ ٱلۡعَذَابَ مَنۡ أَضَلُّ سَبِيلًا¦25:43:1:أَرَءَيۡتَ\nT;0;25:43:2:مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَيۡهِ وَكِيلًا',
  '19;37;0;146\nT;0;25:44:1:أَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ يَسۡمَعُونَ أَوۡ يَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا\nT;0;25:44:2:كَٱلۡأَنۡعَٰمِ بَلۡ هُمۡ أَضَلُّ سَبِيلًا¦25:45:1:أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَيۡفَ مَدَّ ٱلظِّلَّ\nT;0;25:45:2:وَلَوۡ شَآءَ لَجَعَلَهُۥ سَاكِنࣰا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَيۡهِ دَلِيلࣰا\nT;0;25:46:3:ثُمَّ قَبَضۡنَٰهُ إِلَيۡنَا قَبۡضࣰا يَسِيرࣰا¦25:47:1:وَهُوَ ٱلَّذِي جَعَلَ لَكُمُ\nT;0;25:47:2:ٱلَّيۡلَ لِبَاسࣰا وَٱلنَّوۡمَ سُبَاتࣰا وَجَعَلَ ٱلنَّهَارَ نُشُورࣰا¦25:48:1:وَهُوَ\nT;0;25:48:0:ٱلَّذِيٓ أَرۡسَلَ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ\nT;0;25:48:2:ٱلسَّمَآءِ مَآءࣰ طَهُورࣰا¦25:49:1:لِّنُحۡـِۧيَ بِهِۦ بَلۡدَةࣰ مَّيۡتࣰا وَنُسۡقِيَهُۥ\nT;0;25:49:2:مِمَّا خَلَقۡنَآ أَنۡعَٰمࣰا وَأَنَاسِيَّ كَثِيرࣰا¦25:50:1:وَلَقَدۡ صَرَّفۡنَٰهُ بَيۡنَهُمۡ\nT;0;25:50:2:لِيَذَّكَّرُواْ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورࣰا¦25:51:1:وَلَوۡ شِئۡنَا\nT;0;25:51:2:لَبَعَثۡنَا فِي كُلِّ قَرۡيَةࣲ نَّذِيرࣰا¦25:52:1:فَلَا تُطِعِ ٱلۡكَٰفِرِينَ وَجَٰهِدۡهُم\nT;0;25:52:2:بِهِۦ جِهَادࣰا كَبِيرࣰا¦25:53:1:۞ وَهُوَ ٱلَّذِي مَرَجَ ٱلۡبَحۡرَيۡنِ هَٰذَا\nT;0;25:53:0:عَذۡبࣱ فُرَاتࣱ وَهَٰذَا مِلۡحٌ أُجَاجࣱ وَجَعَلَ بَيۡنَهُمَا بَرۡزَخࣰا\nT;0;25:53:2:وَحِجۡرࣰا مَّحۡجُورࣰا¦25:54:1:وَهُوَ ٱلَّذِي خَلَقَ مِنَ ٱلۡمَآءِ بَشَرࣰا فَجَعَلَهُۥ\nT;0;25:54:2:نَسَبࣰا وَصِهۡرࣰاۗ وَكَانَ رَبُّكَ قَدِيرࣰا¦25:55:1:وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ\nT;0;25:55:2:مَا لَا يَنفَعُهُمۡ وَلَا يَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِيرࣰا',
  '19;37;1;\nT;0;25:56:3:وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرࣰا وَنَذِيرࣰا¦25:57:1:قُلۡ مَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ\nT;0;25:57:2:مِنۡ أَجۡرٍ إِلَّا مَن شَآءَ أَن يَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِيلࣰا¦25:58:1:وَتَوَكَّلۡ\nT;0;25:58:0:عَلَى ٱلۡحَيِّ ٱلَّذِي لَا يَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ\nT;0;25:58:2:بِذُنُوبِ عِبَادِهِۦ خَبِيرًا¦25:59:1:ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ\nT;0;25:59:0:وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَٰنُ\nT;0;25:59:2:فَسۡـَٔلۡ بِهِۦ خَبِيرࣰا¦25:60:1:وَإِذَا قِيلَ لَهُمُ ٱسۡجُدُواْۤ لِلرَّحۡمَٰنِ قَالُواْ\nT;0;25:60:2:وَمَا ٱلرَّحۡمَٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورࣰا۩¦25:61:1:تَبَارَكَ\nT;0;25:61:0:ٱلَّذِي جَعَلَ فِي ٱلسَّمَآءِ بُرُوجࣰا وَجَعَلَ فِيهَا سِرَٰجࣰا وَقَمَرࣰا\nT;0;25:61:2:مُّنِيرࣰا¦25:62:1:وَهُوَ ٱلَّذِي جَعَلَ ٱلَّيۡلَ وَٱلنَّهَارَ خِلۡفَةࣰ لِّمَنۡ أَرَادَ\nT;0;25:62:2:أَن يَذَّكَّرَ أَوۡ أَرَادَ شُكُورࣰا¦25:63:1:وَعِبَادُ ٱلرَّحۡمَٰنِ ٱلَّذِينَ يَمۡشُونَ\nT;0;25:63:2:عَلَى ٱلۡأَرۡضِ هَوۡنࣰا وَإِذَا خَاطَبَهُمُ ٱلۡجَٰهِلُونَ قَالُواْ سَلَٰمࣰا\nT;0;25:64:3:وَٱلَّذِينَ يَبِيتُونَ لِرَبِّهِمۡ سُجَّدࣰا وَقِيَٰمࣰا¦25:65:1:وَٱلَّذِينَ\nT;0;25:65:0:يَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ\nT;0;25:65:2:غَرَامًا¦25:66:3:إِنَّهَا سَآءَتۡ مُسۡتَقَرࣰّا وَمُقَامࣰا¦25:67:1:وَٱلَّذِينَ إِذَآ\nT;0;25:67:2:أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامࣰا',
  '19;37;1;\nT;0;25:68:1:وَٱلَّذِينَ لَا يَدۡعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ وَلَا يَقۡتُلُونَ\nT;0;25:68:0:ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا يَزۡنُونَۚ وَمَن\nT;0;25:68:2:يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامࣰا¦25:69:1:يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ\nT;0;25:69:2:يَوۡمَ ٱلۡقِيَٰمَةِ وَيَخۡلُدۡ فِيهِۦ مُهَانًا¦25:70:1:إِلَّا مَن تَابَ\nT;0;25:70:0:وَءَامَنَ وَعَمِلَ عَمَلࣰا صَٰلِحࣰا فَأُوْلَٰٓئِكَ يُبَدِّلُ ٱللَّهُ\nT;0;25:70:2:سَيِّـَٔاتِهِمۡ حَسَنَٰتࣲۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِيمࣰا\nT;0;25:71:3:وَمَن تَابَ وَعَمِلَ صَٰلِحࣰا فَإِنَّهُۥ يَتُوبُ إِلَى ٱللَّهِ مَتَابࣰا\nT;0;25:72:3:وَٱلَّذِينَ لَا يَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّواْ بِٱللَّغۡوِ مَرُّواْ كِرَامࣰا\nT;0;25:73:1:وَٱلَّذِينَ إِذَا ذُكِّرُواْ بِـَٔايَٰتِ رَبِّهِمۡ لَمۡ يَخِرُّواْ عَلَيۡهَا\nT;0;25:73:2:صُمࣰّا وَعُمۡيَانࣰا¦25:74:1:وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا\nT;0;25:74:0:مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنࣲ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ\nT;0;25:74:2:إِمَامًا¦25:75:1:أُوْلَٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ\nT;0;25:75:2:وَيُلَقَّوۡنَ فِيهَا تَحِيَّةࣰ وَسَلَٰمًا¦25:76:1:خَٰلِدِينَ فِيهَاۚ\nT;0;25:76:2:حَسُنَتۡ مُسۡتَقَرࣰّا وَمُقَامࣰا¦25:77:1:قُلۡ مَا يَعۡبَؤُاْ بِكُمۡ رَبِّي\nT;2;25:77:2:لَوۡلَا دُعَآؤُكُمۡۖ فَقَدۡ كَذَّبۡتُمۡ فَسَوۡفَ يَكُونُ لِزَامَۢا',
  '19;37;2;147\nH;26\nB;26\nT;0;26:1:3:طسٓمٓ¦26:2:3:تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ¦26:3:1:لَعَلَّكَ بَٰخِعࣱ نَّفۡسَكَ أَلَّا\nT;0;26:3:2:يَكُونُواْ مُؤۡمِنِينَ¦26:4:1:إِن نَّشَأۡ نُنَزِّلۡ عَلَيۡهِم مِّنَ ٱلسَّمَآءِ ءَايَةࣰ فَظَلَّتۡ\nT;0;26:4:2:أَعۡنَٰقُهُمۡ لَهَا خَٰضِعِينَ¦26:5:1:وَمَا يَأۡتِيهِم مِّن ذِكۡرࣲ مِّنَ ٱلرَّحۡمَٰنِ مُحۡدَثٍ\nT;0;26:5:2:إِلَّا كَانُواْ عَنۡهُ مُعۡرِضِينَ¦26:6:1:فَقَدۡ كَذَّبُواْ فَسَيَأۡتِيهِمۡ أَنۢبَٰٓؤُاْ مَا كَانُواْ بِهِۦ\nT;0;26:6:2:يَسۡتَهۡزِءُونَ¦26:7:3:أَوَلَمۡ يَرَوۡاْ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجࣲ كَرِيمٍ\nT;0;26:8:3:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ¦26:9:1:وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ\nT;0;26:9:2:ٱلرَّحِيمُ¦26:10:3:وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰٓ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ¦26:11:1:قَوۡمَ فِرۡعَوۡنَۚ\nT;0;26:11:2:أَلَا يَتَّقُونَ¦26:12:3:قَالَ رَبِّ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ¦26:13:1:وَيَضِيقُ صَدۡرِي\nT;0;26:13:2:وَلَا يَنطَلِقُ لِسَانِي فَأَرۡسِلۡ إِلَىٰ هَٰرُونَ¦26:14:1:وَلَهُمۡ عَلَيَّ ذَنۢبࣱ فَأَخَافُ\nT;0;26:14:2:أَن يَقۡتُلُونِ¦26:15:3:قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔايَٰتِنَآۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ\nT;0;26:16:3:فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ¦26:17:1:أَنۡ أَرۡسِلۡ مَعَنَا\nT;0;26:17:2:بَنِيٓ إِسۡرَٰٓءِيلَ¦26:18:1:قَالَ أَلَمۡ نُرَبِّكَ فِينَا وَلِيدࣰا وَلَبِثۡتَ فِينَا مِنۡ عُمُرِكَ\nT;0;26:18:2:سِنِينَ¦26:19:3:وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِي فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَٰفِرِينَ',
  '19;37;2;\nT;0;26:20:3:قَالَ فَعَلۡتُهَآ إِذࣰا وَأَنَا۠ مِنَ ٱلضَّآلِّينَ¦26:21:1:فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ\nT;0;26:21:2:فَوَهَبَ لِي رَبِّي حُكۡمࣰا وَجَعَلَنِي مِنَ ٱلۡمُرۡسَلِينَ¦26:22:1:وَتِلۡكَ نِعۡمَةࣱ تَمُنُّهَا\nT;0;26:22:2:عَلَيَّ أَنۡ عَبَّدتَّ بَنِيٓ إِسۡرَٰٓءِيلَ¦26:23:3:قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَٰلَمِينَ\nT;0;26:24:3:قَالَ رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُم مُّوقِنِينَ\nT;0;26:25:3:قَالَ لِمَنۡ حَوۡلَهُۥٓ أَلَا تَسۡتَمِعُونَ¦26:26:1:قَالَ رَبُّكُمۡ وَرَبُّ ءَابَآئِكُمُ\nT;0;26:26:2:ٱلۡأَوَّلِينَ¦26:27:3:قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِيٓ أُرۡسِلَ إِلَيۡكُمۡ لَمَجۡنُونࣱ\nT;0;26:28:3:قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَيۡنَهُمَآۖ إِن كُنتُمۡ تَعۡقِلُونَ\nT;0;26:29:3:قَالَ لَئِنِ ٱتَّخَذۡتَ إِلَٰهًا غَيۡرِي لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِينَ\nT;0;26:30:3:قَالَ أَوَلَوۡ جِئۡتُكَ بِشَيۡءࣲ مُّبِينࣲ¦26:31:1:قَالَ فَأۡتِ بِهِۦٓ إِن كُنتَ\nT;0;26:31:2:مِنَ ٱلصَّٰدِقِينَ¦26:32:3:فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانࣱ مُّبِينࣱ\nT;0;26:33:3:وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ¦26:34:1:قَالَ لِلۡمَلَإِ حَوۡلَهُۥٓ\nT;0;26:34:2:إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمࣱ¦26:35:1:يُرِيدُ أَن يُخۡرِجَكُم مِّنۡ أَرۡضِكُم\nT;0;26:35:2:بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ¦26:36:1:قَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِي ٱلۡمَدَآئِنِ\nT;0;26:36:2:حَٰشِرِينَ¦26:37:3:يَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِيمࣲ¦26:38:1:فَجُمِعَ ٱلسَّحَرَةُ\nT;0;26:38:2:لِمِيقَٰتِ يَوۡمࣲ مَّعۡلُومࣲ¦26:39:3:وَقِيلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ',
  '19;37;2;148\nT;0;26:40:3:لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُواْ هُمُ ٱلۡغَٰلِبِينَ¦26:41:1:فَلَمَّا جَآءَ ٱلسَّحَرَةُ\nT;0;26:41:2:قَالُواْ لِفِرۡعَوۡنَ أَئِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ¦26:42:1:قَالَ نَعَمۡ\nT;0;26:42:2:وَإِنَّكُمۡ إِذࣰا لَّمِنَ ٱلۡمُقَرَّبِينَ¦26:43:3:قَالَ لَهُم مُّوسَىٰٓ أَلۡقُواْ مَآ أَنتُم مُّلۡقُونَ\nT;0;26:44:1:فَأَلۡقَوۡاْ حِبَالَهُمۡ وَعِصِيَّهُمۡ وَقَالُواْ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ\nT;0;26:44:2:ٱلۡغَٰلِبُونَ¦26:45:3:فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِيَ تَلۡقَفُ مَا يَأۡفِكُونَ\nT;0;26:46:3:فَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ¦26:47:3:قَالُوٓاْ ءَامَنَّا بِرَبِّ ٱلۡعَٰلَمِينَ\nT;0;26:48:3:رَبِّ مُوسَىٰ وَهَٰرُونَ¦26:49:1:قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ\nT;0;26:49:0:لَكَبِيرُكُمُ ٱلَّذِي عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَيۡدِيَكُمۡ\nT;0;26:49:2:وَأَرۡجُلَكُم مِّنۡ خِلَٰفࣲ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِينَ¦26:50:1:قَالُواْ لَا ضَيۡرَۖ إِنَّآ\nT;0;26:50:2:إِلَىٰ رَبِّنَا مُنقَلِبُونَ¦26:51:1:إِنَّا نَطۡمَعُ أَن يَغۡفِرَ لَنَا رَبُّنَا خَطَٰيَٰنَآ أَن كُنَّآ\nT;0;26:51:2:أَوَّلَ ٱلۡمُؤۡمِنِينَ¦26:52:1:۞ وَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنۡ أَسۡرِ بِعِبَادِيٓ إِنَّكُم\nT;0;26:52:2:مُّتَّبَعُونَ¦26:53:3:فَأَرۡسَلَ فِرۡعَوۡنُ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ¦26:54:1:إِنَّ هَٰٓؤُلَآءِ\nT;0;26:54:2:لَشِرۡذِمَةࣱ قَلِيلُونَ¦26:55:3:وَإِنَّهُمۡ لَنَا لَغَآئِظُونَ¦26:56:3:وَإِنَّا لَجَمِيعٌ حَٰذِرُونَ\nT;0;26:57:3:فَأَخۡرَجۡنَٰهُم مِّن جَنَّٰتࣲ وَعُيُونࣲ¦26:58:3:وَكُنُوزࣲ وَمَقَامࣲ كَرِيمࣲ\nT;0;26:59:3:كَذَٰلِكَۖ وَأَوۡرَثۡنَٰهَا بَنِيٓ إِسۡرَٰٓءِيلَ¦26:60:3:فَأَتۡبَعُوهُم مُّشۡرِقِينَ',
  '19;37;3;\nT;0;26:61:3:فَلَمَّا تَرَٰٓءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَٰبُ مُوسَىٰٓ إِنَّا لَمُدۡرَكُونَ\nT;0;26:62:3:قَالَ كَلَّآۖ إِنَّ مَعِيَ رَبِّي سَيَهۡدِينِ¦26:63:1:فَأَوۡحَيۡنَآ إِلَىٰ مُوسَىٰٓ أَنِ\nT;0;26:63:2:ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقࣲ كَٱلطَّوۡدِ ٱلۡعَظِيمِ\nT;0;26:64:3:وَأَزۡلَفۡنَا ثَمَّ ٱلۡأٓخَرِينَ¦26:65:3:وَأَنجَيۡنَا مُوسَىٰ وَمَن مَّعَهُۥٓ أَجۡمَعِينَ\nT;0;26:66:3:ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ¦26:67:1:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ\nT;0;26:67:2:أَكۡثَرُهُم مُّؤۡمِنِينَ¦26:68:3:وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ\nT;0;26:69:3:وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ إِبۡرَٰهِيمَ¦26:70:3:إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ\nT;0;26:71:3:قَالُواْ نَعۡبُدُ أَصۡنَامࣰا فَنَظَلُّ لَهَا عَٰكِفِينَ¦26:72:1:قَالَ هَلۡ\nT;0;26:72:2:يَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ¦26:73:3:أَوۡ يَنفَعُونَكُمۡ أَوۡ يَضُرُّونَ¦26:74:1:قَالُواْ\nT;0;26:74:2:بَلۡ وَجَدۡنَآ ءَابَآءَنَا كَذَٰلِكَ يَفۡعَلُونَ¦26:75:1:قَالَ أَفَرَءَيۡتُم مَّا كُنتُمۡ\nT;0;26:75:2:تَعۡبُدُونَ¦26:76:3:أَنتُمۡ وَءَابَآؤُكُمُ ٱلۡأَقۡدَمُونَ¦26:77:1:فَإِنَّهُمۡ عَدُوࣱّ لِّيٓ\nT;0;26:77:2:إِلَّا رَبَّ ٱلۡعَٰلَمِينَ¦26:78:3:ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ¦26:79:1:وَٱلَّذِي هُوَ\nT;0;26:79:2:يُطۡعِمُنِي وَيَسۡقِينِ¦26:80:3:وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ¦26:81:1:وَٱلَّذِي\nT;0;26:81:2:يُمِيتُنِي ثُمَّ يُحۡيِينِ¦26:82:1:وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي\nT;0;26:82:2:يَوۡمَ ٱلدِّينِ¦26:83:3:رَبِّ هَبۡ لِي حُكۡمࣰا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ',
  '19;37;3;149\nT;0;26:84:3:وَٱجۡعَل لِّي لِسَانَ صِدۡقࣲ فِي ٱلۡأٓخِرِينَ¦26:85:1:وَٱجۡعَلۡنِي مِن وَرَثَةِ جَنَّةِ\nT;0;26:85:2:ٱلنَّعِيمِ¦26:86:3:وَٱغۡفِرۡ لِأَبِيٓ إِنَّهُۥ كَانَ مِنَ ٱلضَّآلِّينَ¦26:87:1:وَلَا تُخۡزِنِي يَوۡمَ\nT;0;26:87:2:يُبۡعَثُونَ¦26:88:3:يَوۡمَ لَا يَنفَعُ مَالࣱ وَلَا بَنُونَ¦26:89:1:إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبࣲ\nT;0;26:89:2:سَلِيمࣲ¦26:90:3:وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ¦26:91:1:وَبُرِّزَتِ ٱلۡجَحِيمُ\nT;0;26:91:2:لِلۡغَاوِينَ¦26:92:3:وَقِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تَعۡبُدُونَ¦26:93:1:مِن دُونِ ٱللَّهِ هَلۡ\nT;0;26:93:2:يَنصُرُونَكُمۡ أَوۡ يَنتَصِرُونَ¦26:94:3:فَكُبۡكِبُواْ فِيهَا هُمۡ وَٱلۡغَاوُۥنَ¦26:95:1:وَجُنُودُ\nT;0;26:95:2:إِبۡلِيسَ أَجۡمَعُونَ¦26:96:3:قَالُواْ وَهُمۡ فِيهَا يَخۡتَصِمُونَ¦26:97:1:تَٱللَّهِ إِن كُنَّا لَفِي\nT;0;26:97:2:ضَلَٰلࣲ مُّبِينٍ¦26:98:3:إِذۡ نُسَوِّيكُم بِرَبِّ ٱلۡعَٰلَمِينَ¦26:99:1:وَمَآ أَضَلَّنَآ إِلَّا\nT;0;26:99:2:ٱلۡمُجۡرِمُونَ¦26:100:3:فَمَا لَنَا مِن شَٰفِعِينَ¦26:101:3:وَلَا صَدِيقٍ حَمِيمࣲ¦26:102:1:فَلَوۡ\nT;0;26:102:2:أَنَّ لَنَا كَرَّةࣰ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ¦26:103:1:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ\nT;0;26:103:2:أَكۡثَرُهُم مُّؤۡمِنِينَ¦26:104:3:وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ¦26:105:1:كَذَّبَتۡ\nT;0;26:105:2:قَوۡمُ نُوحٍ ٱلۡمُرۡسَلِينَ¦26:106:3:إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّقُونَ\nT;0;26:107:3:إِنِّي لَكُمۡ رَسُولٌ أَمِينࣱ¦26:108:3:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ¦26:109:1:وَمَآ أَسۡـَٔلُكُمۡ\nT;0;26:109:2:عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ¦26:110:1:فَٱتَّقُواْ ٱللَّهَ\nT;0;26:110:2:وَأَطِيعُونِ¦26:111:3:۞ قَالُوٓاْ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ',
  '19;38;0;\nT;0;26:112:3:قَالَ وَمَا عِلۡمِي بِمَا كَانُواْ يَعۡمَلُونَ¦26:113:1:إِنۡ حِسَابُهُمۡ إِلَّا عَلَىٰ رَبِّيۖ\nT;0;26:113:2:لَوۡ تَشۡعُرُونَ¦26:114:3:وَمَآ أَنَا۠ بِطَارِدِ ٱلۡمُؤۡمِنِينَ¦26:115:1:إِنۡ أَنَا۠ إِلَّا نَذِيرࣱ\nT;0;26:115:2:مُّبِينࣱ¦26:116:3:قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰنُوحُ لَتَكُونَنَّ مِنَ ٱلۡمَرۡجُومِينَ¦26:117:1:قَالَ رَبِّ\nT;0;26:117:2:إِنَّ قَوۡمِي كَذَّبُونِ¦26:118:1:فَٱفۡتَحۡ بَيۡنِي وَبَيۡنَهُمۡ فَتۡحࣰا وَنَجِّنِي وَمَن مَّعِيَ\nT;0;26:118:2:مِنَ ٱلۡمُؤۡمِنِينَ¦26:119:3:فَأَنجَيۡنَٰهُ وَمَن مَّعَهُۥ فِي ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ\nT;0;26:120:3:ثُمَّ أَغۡرَقۡنَا بَعۡدُ ٱلۡبَاقِينَ¦26:121:1:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ\nT;0;26:121:2:أَكۡثَرُهُم مُّؤۡمِنِينَ¦26:122:3:وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ¦26:123:1:كَذَّبَتۡ\nT;0;26:123:2:عَادٌ ٱلۡمُرۡسَلِينَ¦26:124:3:إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ هُودٌ أَلَا تَتَّقُونَ¦26:125:1:إِنِّي لَكُمۡ\nT;0;26:125:2:رَسُولٌ أَمِينࣱ¦26:126:3:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ¦26:127:1:وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ\nT;0;26:127:2:مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ¦26:128:1:أَتَبۡنُونَ بِكُلِّ رِيعٍ\nT;0;26:128:2:ءَايَةࣰ تَعۡبَثُونَ¦26:129:3:وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ\nT;0;26:130:3:وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِينَ¦26:131:3:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ\nT;0;26:132:3:وَٱتَّقُواْ ٱلَّذِيٓ أَمَدَّكُم بِمَا تَعۡلَمُونَ¦26:133:3:أَمَدَّكُم بِأَنۡعَٰمࣲ وَبَنِينَ\nT;0;26:134:3:وَجَنَّٰتࣲ وَعُيُونٍ¦26:135:3:إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمࣲ\nT;0;26:136:3:قَالُواْ سَوَآءٌ عَلَيۡنَآ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَٰعِظِينَ',
  '19;38;0;\nT;0;26:137:3:إِنۡ هَٰذَآ إِلَّا خُلُقُ ٱلۡأَوَّلِينَ¦26:138:3:وَمَا نَحۡنُ بِمُعَذَّبِينَ¦26:139:1:فَكَذَّبُوهُ\nT;0;26:139:2:فَأَهۡلَكۡنَٰهُمۡۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ\nT;0;26:140:3:وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ¦26:141:3:كَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِينَ¦26:142:1:إِذۡ\nT;0;26:142:2:قَالَ لَهُمۡ أَخُوهُمۡ صَٰلِحٌ أَلَا تَتَّقُونَ¦26:143:3:إِنِّي لَكُمۡ رَسُولٌ أَمِينࣱ\nT;0;26:144:3:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ¦26:145:1:وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ\nT;0;26:145:2:إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ¦26:146:3:أَتُتۡرَكُونَ فِي مَا هَٰهُنَآ ءَامِنِينَ\nT;0;26:147:3:فِي جَنَّٰتࣲ وَعُيُونࣲ¦26:148:3:وَزُرُوعࣲ وَنَخۡلࣲ طَلۡعُهَا هَضِيمࣱ\nT;0;26:149:3:وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتࣰا فَٰرِهِينَ¦26:150:3:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ\nT;0;26:151:3:وَلَا تُطِيعُوٓاْ أَمۡرَ ٱلۡمُسۡرِفِينَ¦26:152:1:ٱلَّذِينَ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ\nT;0;26:152:2:وَلَا يُصۡلِحُونَ¦26:153:3:قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ ٱلۡمُسَحَّرِينَ¦26:154:1:مَآ أَنتَ\nT;0;26:154:2:إِلَّا بَشَرࣱ مِّثۡلُنَا فَأۡتِ بِـَٔايَةٍ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ¦26:155:1:قَالَ\nT;0;26:155:2:هَٰذِهِۦ نَاقَةࣱ لَّهَا شِرۡبࣱ وَلَكُمۡ شِرۡبُ يَوۡمࣲ مَّعۡلُومࣲ¦26:156:1:وَلَا تَمَسُّوهَا\nT;0;26:156:2:بِسُوٓءࣲ فَيَأۡخُذَكُمۡ عَذَابُ يَوۡمٍ عَظِيمࣲ¦26:157:1:فَعَقَرُوهَا فَأَصۡبَحُواْ\nT;0;26:157:2:نَٰدِمِينَ¦26:158:1:فَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ\nT;0;26:158:2:أَكۡثَرُهُم مُّؤۡمِنِينَ¦26:159:3:وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ',
  '19;38;0;150\nT;0;26:160:3:كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِينَ¦26:161:1:إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا\nT;0;26:161:2:تَتَّقُونَ¦26:162:3:إِنِّي لَكُمۡ رَسُولٌ أَمِينࣱ¦26:163:3:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ¦26:164:1:وَمَآ\nT;0;26:164:2:أَسۡـَٔلُكُمۡ عَلَيۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ\nT;0;26:165:3:أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ¦26:166:1:وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم\nT;0;26:166:2:مِّنۡ أَزۡوَٰجِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ¦26:167:1:قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ\nT;0;26:167:2:لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ¦26:168:3:قَالَ إِنِّي لِعَمَلِكُم مِّنَ ٱلۡقَالِينَ\nT;0;26:169:3:رَبِّ نَجِّنِي وَأَهۡلِي مِمَّا يَعۡمَلُونَ¦26:170:3:فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ\nT;0;26:171:3:إِلَّا عَجُوزࣰا فِي ٱلۡغَٰبِرِينَ¦26:172:3:ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ¦26:173:1:وَأَمۡطَرۡنَا عَلَيۡهِم\nT;0;26:173:2:مَّطَرࣰاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ¦26:174:1:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم\nT;0;26:174:2:مُّؤۡمِنِينَ¦26:175:3:وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ¦26:176:1:كَذَّبَ أَصۡحَٰبُ\nT;0;26:176:2:لۡـَٔيۡكَةِ ٱلۡمُرۡسَلِينَ¦26:177:3:إِذۡ قَالَ لَهُمۡ شُعَيۡبٌ أَلَا تَتَّقُونَ¦26:178:1:إِنِّي لَكُمۡ\nT;0;26:178:2:رَسُولٌ أَمِينࣱ¦26:179:3:فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ¦26:180:1:وَمَآ أَسۡـَٔلُكُمۡ عَلَيۡهِ\nT;0;26:180:2:مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِيَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَٰلَمِينَ¦26:181:1:۞ أَوۡفُواْ ٱلۡكَيۡلَ وَلَا\nT;0;26:181:2:تَكُونُواْ مِنَ ٱلۡمُخۡسِرِينَ¦26:182:3:وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِ\nT;0;26:183:3:وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ',
  '19;38;1;\nT;0;26:184:3:وَٱتَّقُواْ ٱلَّذِي خَلَقَكُمۡ وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِينَ¦26:185:1:قَالُوٓاْ إِنَّمَآ أَنتَ مِنَ\nT;0;26:185:2:ٱلۡمُسَحَّرِينَ¦26:186:1:وَمَآ أَنتَ إِلَّا بَشَرࣱ مِّثۡلُنَا وَإِن نَّظُنُّكَ لَمِنَ\nT;0;26:186:2:ٱلۡكَٰذِبِينَ¦26:187:1:فَأَسۡقِطۡ عَلَيۡنَا كِسَفࣰا مِّنَ ٱلسَّمَآءِ إِن كُنتَ\nT;0;26:187:2:مِنَ ٱلصَّٰدِقِينَ¦26:188:3:قَالَ رَبِّيٓ أَعۡلَمُ بِمَا تَعۡمَلُونَ¦26:189:1:فَكَذَّبُوهُ\nT;0;26:189:2:فَأَخَذَهُمۡ عَذَابُ يَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ يَوۡمٍ عَظِيمٍ\nT;0;26:190:3:إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِينَ¦26:191:1:وَإِنَّ رَبَّكَ\nT;0;26:191:2:لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ¦26:192:3:وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ¦26:193:1:نَزَلَ بِهِ\nT;0;26:193:2:ٱلرُّوحُ ٱلۡأَمِينُ¦26:194:3:عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ¦26:195:1:بِلِسَانٍ\nT;0;26:195:2:عَرَبِيࣲّ مُّبِينࣲ¦26:196:3:وَإِنَّهُۥ لَفِي زُبُرِ ٱلۡأَوَّلِينَ¦26:197:1:أَوَلَمۡ يَكُن لَّهُمۡ ءَايَةً\nT;0;26:197:2:أَن يَعۡلَمَهُۥ عُلَمَٰٓؤُاْ بَنِيٓ إِسۡرَٰٓءِيلَ¦26:198:1:وَلَوۡ نَزَّلۡنَٰهُ عَلَىٰ بَعۡضِ\nT;0;26:198:2:ٱلۡأَعۡجَمِينَ¦26:199:3:فَقَرَأَهُۥ عَلَيۡهِم مَّا كَانُواْ بِهِۦ مُؤۡمِنِينَ¦26:200:1:كَذَٰلِكَ سَلَكۡنَٰهُ\nT;0;26:200:2:فِي قُلُوبِ ٱلۡمُجۡرِمِينَ¦26:201:1:لَا يُؤۡمِنُونَ بِهِۦ حَتَّىٰ يَرَوُاْ ٱلۡعَذَابَ\nT;0;26:201:2:ٱلۡأَلِيمَ¦26:202:3:فَيَأۡتِيَهُم بَغۡتَةࣰ وَهُمۡ لَا يَشۡعُرُونَ¦26:203:1:فَيَقُولُواْ\nT;0;26:203:2:هَلۡ نَحۡنُ مُنظَرُونَ¦26:204:3:أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ¦26:205:1:أَفَرَءَيۡتَ\nT;0;26:205:2:إِن مَّتَّعۡنَٰهُمۡ سِنِينَ¦26:206:3:ثُمَّ جَآءَهُم مَّا كَانُواْ يُوعَدُونَ',
  '19;38;1;\nT;0;26:207:3:مَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يُمَتَّعُونَ¦26:208:1:وَمَآ أَهۡلَكۡنَا\nT;0;26:208:2:مِن قَرۡيَةٍ إِلَّا لَهَا مُنذِرُونَ¦26:209:1:ذِكۡرَىٰ وَمَا كُنَّا\nT;0;26:209:2:ظَٰلِمِينَ¦26:210:3:وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّيَٰطِينُ¦26:211:1:وَمَا يَنۢبَغِي لَهُمۡ\nT;0;26:211:2:وَمَا يَسۡتَطِيعُونَ¦26:212:3:إِنَّهُمۡ عَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ\nT;0;26:213:3:فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِينَ\nT;0;26:214:3:وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ¦26:215:1:وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ\nT;0;26:215:2:مِنَ ٱلۡمُؤۡمِنِينَ¦26:216:3:فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّي بَرِيٓءࣱ مِّمَّا تَعۡمَلُونَ\nT;0;26:217:3:وَتَوَكَّلۡ عَلَى ٱلۡعَزِيزِ ٱلرَّحِيمِ¦26:218:3:ٱلَّذِي يَرَىٰكَ حِينَ تَقُومُ\nT;0;26:219:3:وَتَقَلُّبَكَ فِي ٱلسَّٰجِدِينَ¦26:220:3:إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ\nT;0;26:221:3:هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّيَٰطِينُ¦26:222:1:تَنَزَّلُ عَلَىٰ كُلِّ\nT;0;26:222:2:أَفَّاكٍ أَثِيمࣲ¦26:223:3:يُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَٰذِبُونَ\nT;0;26:224:3:وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلۡغَاوُۥنَ¦26:225:1:أَلَمۡ تَرَ أَنَّهُمۡ فِي كُلِّ وَادࣲ\nT;0;26:225:2:يَهِيمُونَ¦26:226:3:وَأَنَّهُمۡ يَقُولُونَ مَا لَا يَفۡعَلُونَ¦26:227:1:إِلَّا ٱلَّذِينَ\nT;0;26:227:0:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَذَكَرُواْ ٱللَّهَ كَثِيرࣰا وَٱنتَصَرُواْ مِنۢ\nT;2;26:227:2:بَعۡدِ مَا ظُلِمُواْۗ وَسَيَعۡلَمُ ٱلَّذِينَ ظَلَمُوٓاْ أَيَّ مُنقَلَبࣲ يَنقَلِبُونَ',
  '19;38;2;151\nH;27\nB;27\nT;0;27:1:3:طسٓۚ تِلۡكَ ءَايَٰتُ ٱلۡقُرۡءَانِ وَكِتَابࣲ مُّبِينٍ¦27:2:1:هُدࣰى وَبُشۡرَىٰ\nT;0;27:2:2:لِلۡمُؤۡمِنِينَ¦27:3:1:ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ\nT;0;27:3:2:هُمۡ يُوقِنُونَ¦27:4:1:إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ\nT;0;27:4:2:يَعۡمَهُونَ¦27:5:1:أُوْلَٰٓئِكَ ٱلَّذِينَ لَهُمۡ سُوٓءُ ٱلۡعَذَابِ وَهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ\nT;0;27:5:2:ٱلۡأَخۡسَرُونَ¦27:6:3:وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن لَّدُنۡ حَكِيمٍ عَلِيمٍ¦27:7:1:إِذۡ قَالَ\nT;0;27:7:0:مُوسَىٰ لِأَهۡلِهِۦٓ إِنِّيٓ ءَانَسۡتُ نَارࣰا سَـَٔاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِيكُم بِشِهَابࣲ قَبَسࣲ\nT;0;27:7:2:لَّعَلَّكُمۡ تَصۡطَلُونَ¦27:8:1:فَلَمَّا جَآءَهَا نُودِيَ أَنۢ بُورِكَ مَن فِي ٱلنَّارِ وَمَنۡ حَوۡلَهَا\nT;0;27:8:2:وَسُبۡحَٰنَ ٱللَّهِ رَبِّ ٱلۡعَٰلَمِينَ¦27:9:3:يَٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\nT;0;27:10:1:وَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَآنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ يُعَقِّبۡۚ\nT;0;27:10:2:يَٰمُوسَىٰ لَا تَخَفۡ إِنِّي لَا يَخَافُ لَدَيَّ ٱلۡمُرۡسَلُونَ¦27:11:1:إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ\nT;0;27:11:2:حُسۡنَۢا بَعۡدَ سُوٓءࣲ فَإِنِّي غَفُورࣱ رَّحِيمࣱ¦27:12:1:وَأَدۡخِلۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ\nT;0;27:12:0:بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءࣲۖ فِي تِسۡعِ ءَايَٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦٓۚ إِنَّهُمۡ كَانُواْ قَوۡمࣰا\nT;0;27:12:2:فَٰسِقِينَ¦27:13:3:فَلَمَّا جَآءَتۡهُمۡ ءَايَٰتُنَا مُبۡصِرَةࣰ قَالُواْ هَٰذَا سِحۡرࣱ مُّبِينࣱ',
  '19;38;2;\nT;0;27:14:1:وَجَحَدُواْ بِهَا وَٱسۡتَيۡقَنَتۡهَآ أَنفُسُهُمۡ ظُلۡمࣰا وَعُلُوࣰّاۚ فَٱنظُرۡ كَيۡفَ\nT;0;27:14:2:كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ¦27:15:1:وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ وَسُلَيۡمَٰنَ عِلۡمࣰاۖ\nT;0;27:15:2:وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرࣲ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ\nT;0;27:16:1:وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ\nT;0;27:16:2:ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ\nT;0;27:17:1:وَحُشِرَ لِسُلَيۡمَٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّيۡرِ فَهُمۡ\nT;0;27:17:2:يُوزَعُونَ¦27:18:1:حَتَّىٰٓ إِذَآ أَتَوۡاْ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةࣱ يَٰٓأَيُّهَا\nT;0;27:18:0:ٱلنَّمۡلُ ٱدۡخُلُواْ مَسَٰكِنَكُمۡ لَا يَحۡطِمَنَّكُمۡ سُلَيۡمَٰنُ وَجُنُودُهُۥ وَهُمۡ\nT;0;27:18:2:لَا يَشۡعُرُونَ¦27:19:1:فَتَبَسَّمَ ضَاحِكࣰا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِيٓ\nT;0;27:19:0:أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ\nT;0;27:19:2:صَٰلِحࣰا تَرۡضَىٰهُ وَأَدۡخِلۡنِي بِرَحۡمَتِكَ فِي عِبَادِكَ ٱلصَّٰلِحِينَ\nT;0;27:20:1:وَتَفَقَّدَ ٱلطَّيۡرَ فَقَالَ مَا لِيَ لَآ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ\nT;0;27:20:2:مِنَ ٱلۡغَآئِبِينَ¦27:21:1:لَأُعَذِّبَنَّهُۥ عَذَابࣰا شَدِيدًا أَوۡ لَأَاْذۡبَحَنَّهُۥٓ\nT;0;27:21:2:أَوۡ لَيَأۡتِيَنِّي بِسُلۡطَٰنࣲ مُّبِينࣲ¦27:22:1:فَمَكَثَ غَيۡرَ بَعِيدࣲ فَقَالَ\nT;0;27:22:2:أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإࣲ يَقِينٍ',
  '19;38;2;152\nT;0;27:23:1:إِنِّي وَجَدتُّ ٱمۡرَأَةࣰ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءࣲ وَلَهَا\nT;0;27:23:2:عَرۡشٌ عَظِيمࣱ¦27:24:1:وَجَدتُّهَا وَقَوۡمَهَا يَسۡجُدُونَ لِلشَّمۡسِ\nT;0;27:24:0:مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ\nT;0;27:24:2:فَهُمۡ لَا يَهۡتَدُونَ¦27:25:1:أَلَّاۤ يَسۡجُدُواْۤ لِلَّهِ ٱلَّذِي يُخۡرِجُ ٱلۡخَبۡءَ فِي\nT;0;27:25:2:ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَيَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ¦27:26:1:ٱللَّهُ\nT;0;27:26:2:لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩¦27:27:1:۞ قَالَ سَنَنظُرُ\nT;0;27:27:2:أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَٰذِبِينَ¦27:28:1:ٱذۡهَب بِّكِتَٰبِي هَٰذَا\nT;0;27:28:2:فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ¦27:29:1:قَالَتۡ يَٰٓأَيُّهَا\nT;0;27:29:2:ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبࣱ كَرِيمٌ¦27:30:1:إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ\nT;0;27:30:2:بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ¦27:31:3:أَلَّا تَعۡلُواْ عَلَيَّ وَأۡتُونِي مُسۡلِمِينَ\nT;0;27:32:1:قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَفۡتُونِي فِيٓ أَمۡرِي مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ\nT;0;27:32:2:تَشۡهَدُونِ¦27:33:1:قَالُواْ نَحۡنُ أُوْلُواْ قُوَّةࣲ وَأُوْلُواْ بَأۡسࣲ شَدِيدࣲ وَٱلۡأَمۡرُ\nT;0;27:33:2:إِلَيۡكِ فَٱنظُرِي مَاذَا تَأۡمُرِينَ¦27:34:1:قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُواْ قَرۡيَةً\nT;0;27:34:2:أَفۡسَدُوهَا وَجَعَلُوٓاْ أَعِزَّةَ أَهۡلِهَآ أَذِلَّةࣰۚ وَكَذَٰلِكَ يَفۡعَلُونَ\nT;0;27:35:3:وَإِنِّي مُرۡسِلَةٌ إِلَيۡهِم بِهَدِيَّةࣲ فَنَاظِرَةُۢ بِمَ يَرۡجِعُ ٱلۡمُرۡسَلُونَ',
  '19;38;3;\nT;0;27:36:1:فَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالࣲ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرࣱ مِّمَّآ\nT;0;27:36:2:ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ¦27:37:1:ٱرۡجِعۡ إِلَيۡهِمۡ فَلَنَأۡتِيَنَّهُم\nT;0;27:37:2:بِجُنُودࣲ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَآ أَذِلَّةࣰ وَهُمۡ صَٰغِرُونَ\nT;0;27:38:3:قَالَ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ أَيُّكُمۡ يَأۡتِينِي بِعَرۡشِهَا قَبۡلَ أَن يَأۡتُونِي مُسۡلِمِينَ\nT;0;27:39:1:قَالَ عِفۡرِيتࣱ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ\nT;0;27:39:2:وَإِنِّي عَلَيۡهِ لَقَوِيٌّ أَمِينࣱ¦27:40:1:قَالَ ٱلَّذِي عِندَهُۥ عِلۡمࣱ مِّنَ ٱلۡكِتَٰبِ أَنَا۠\nT;0;27:40:0:ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ\nT;0;27:40:0:قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا\nT;0;27:40:2:يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيࣱّ كَرِيمࣱ¦27:41:1:قَالَ نَكِّرُواْ لَهَا\nT;0;27:41:2:عَرۡشَهَا نَنظُرۡ أَتَهۡتَدِيٓ أَمۡ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهۡتَدُونَ¦27:42:1:فَلَمَّا\nT;0;27:42:0:جَآءَتۡ قِيلَ أَهَٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِينَا ٱلۡعِلۡمَ مِن قَبۡلِهَا\nT;0;27:42:2:وَكُنَّا مُسۡلِمِينَ¦27:43:1:وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن\nT;0;27:43:2:قَوۡمࣲ كَٰفِرِينَ¦27:44:1:قِيلَ لَهَا ٱدۡخُلِي ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةࣰ\nT;0;27:44:0:وَكَشَفَتۡ عَن سَاقَيۡهَاۚ قَالَ إِنَّهُۥ صَرۡحࣱ مُّمَرَّدࣱ مِّن قَوَارِيرَۗ قَالَتۡ رَبِّ\nT;0;27:44:2:إِنِّي ظَلَمۡتُ نَفۡسِي وَأَسۡلَمۡتُ مَعَ سُلَيۡمَٰنَ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ',
  '19;38;3;\nT;0;27:45:1:وَلَقَدۡ أَرۡسَلۡنَآ إِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحًا أَنِ ٱعۡبُدُواْ ٱللَّهَ\nT;0;27:45:2:فَإِذَا هُمۡ فَرِيقَانِ يَخۡتَصِمُونَ¦27:46:1:قَالَ يَٰقَوۡمِ لِمَ تَسۡتَعۡجِلُونَ\nT;0;27:46:0:بِٱلسَّيِّئَةِ قَبۡلَ ٱلۡحَسَنَةِۖ لَوۡلَا تَسۡتَغۡفِرُونَ ٱللَّهَ لَعَلَّكُمۡ\nT;0;27:46:2:تُرۡحَمُونَ¦27:47:1:قَالُواْ ٱطَّيَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَٰٓئِرُكُمۡ\nT;0;27:47:2:عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمࣱ تُفۡتَنُونَ¦27:48:1:وَكَانَ فِي ٱلۡمَدِينَةِ\nT;0;27:48:2:تِسۡعَةُ رَهۡطࣲ يُفۡسِدُونَ فِي ٱلۡأَرۡضِ وَلَا يُصۡلِحُونَ\nT;0;27:49:1:قَالُواْ تَقَاسَمُواْ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهۡلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ\nT;0;27:49:2:مَا شَهِدۡنَا مَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَٰدِقُونَ¦27:50:1:وَمَكَرُواْ\nT;0;27:50:2:مَكۡرࣰا وَمَكَرۡنَا مَكۡرࣰا وَهُمۡ لَا يَشۡعُرُونَ¦27:51:1:فَٱنظُرۡ\nT;0;27:51:0:كَيۡفَ كَانَ عَٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَٰهُمۡ وَقَوۡمَهُمۡ\nT;0;27:51:2:أَجۡمَعِينَ¦27:52:1:فَتِلۡكَ بُيُوتُهُمۡ خَاوِيَةَۢ بِمَا ظَلَمُوٓاْۚ إِنَّ\nT;0;27:52:2:فِي ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ يَعۡلَمُونَ¦27:53:1:وَأَنجَيۡنَا ٱلَّذِينَ ءَامَنُواْ\nT;0;27:53:2:وَكَانُواْ يَتَّقُونَ¦27:54:1:وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ\nT;0;27:54:2:ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ¦27:55:1:أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ\nT;0;27:55:2:شَهۡوَةࣰ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمࣱ تَجۡهَلُونَ',
  '20;39;0;153\nT;0;27:56:1:۞ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ\nT;0;27:56:2:لُوطࣲ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسࣱ يَتَطَهَّرُونَ¦27:57:1:فَأَنجَيۡنَٰهُ\nT;0;27:57:2:وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَٰهَا مِنَ ٱلۡغَٰبِرِينَ¦27:58:1:وَأَمۡطَرۡنَا\nT;0;27:58:2:عَلَيۡهِم مَّطَرࣰاۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ¦27:59:1:قُلِ ٱلۡحَمۡدُ لِلَّهِ\nT;0;27:59:2:وَسَلَٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصۡطَفَىٰٓۗ ءَآللَّهُ خَيۡرٌ أَمَّا يُشۡرِكُونَ\nT;0;27:60:1:أَمَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ\nT;0;27:60:0:مَآءࣰ فَأَنۢبَتۡنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهۡجَةࣲ مَّا كَانَ لَكُمۡ أَن\nT;0;27:60:2:تُنۢبِتُواْ شَجَرَهَآۗ أَءِلَٰهࣱ مَّعَ ٱللَّهِۚ بَلۡ هُمۡ قَوۡمࣱ يَعۡدِلُونَ\nT;0;27:61:1:أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارࣰا وَجَعَلَ خِلَٰلَهَآ أَنۡهَٰرࣰا وَجَعَلَ\nT;0;27:61:0:لَهَا رَوَٰسِيَ وَجَعَلَ بَيۡنَ ٱلۡبَحۡرَيۡنِ حَاجِزًاۗ أَءِلَٰهࣱ مَّعَ ٱللَّهِۚ\nT;0;27:61:2:بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ¦27:62:1:أَمَّن يُجِيبُ ٱلۡمُضۡطَرَّ إِذَا\nT;0;27:62:0:دَعَاهُ وَيَكۡشِفُ ٱلسُّوٓءَ وَيَجۡعَلُكُمۡ خُلَفَآءَ ٱلۡأَرۡضِۗ\nT;0;27:62:2:أَءِلَٰهࣱ مَّعَ ٱللَّهِۚ قَلِيلࣰا مَّا تَذَكَّرُونَ¦27:63:1:أَمَّن يَهۡدِيكُمۡ فِي\nT;0;27:63:0:ظُلُمَٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ وَمَن يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ\nT;0;27:63:2:رَحۡمَتِهِۦٓۗ أَءِلَٰهࣱ مَّعَ ٱللَّهِۚ تَعَٰلَى ٱللَّهُ عَمَّا يُشۡرِكُونَ',
  '20;39;0;\nT;0;27:64:1:أَمَّن يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرۡزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۗ\nT;0;27:64:2:أَءِلَٰهࣱ مَّعَ ٱللَّهِۚ قُلۡ هَاتُواْ بُرۡهَٰنَكُمۡ إِن كُنتُمۡ صَٰدِقِينَ¦27:65:1:قُل\nT;0;27:65:0:لَّا يَعۡلَمُ مَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ ٱلۡغَيۡبَ إِلَّا ٱللَّهُۚ وَمَا يَشۡعُرُونَ\nT;0;27:65:2:أَيَّانَ يُبۡعَثُونَ¦27:66:1:بَلِ ٱدَّٰرَكَ عِلۡمُهُمۡ فِي ٱلۡأٓخِرَةِۚ بَلۡ هُمۡ فِي\nT;0;27:66:2:شَكࣲّ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ¦27:67:1:وَقَالَ ٱلَّذِينَ كَفَرُوٓاْ أَءِذَا\nT;0;27:67:2:كُنَّا تُرَٰبࣰا وَءَابَآؤُنَآ أَئِنَّا لَمُخۡرَجُونَ¦27:68:1:لَقَدۡ وُعِدۡنَا هَٰذَا\nT;0;27:68:2:نَحۡنُ وَءَابَآؤُنَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ\nT;0;27:69:3:قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ\nT;0;27:70:3:وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُن فِي ضَيۡقࣲ مِّمَّا يَمۡكُرُونَ\nT;0;27:71:3:وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَٰدِقِينَ¦27:72:1:قُلۡ عَسَىٰٓ\nT;0;27:72:2:أَن يَكُونَ رَدِفَ لَكُم بَعۡضُ ٱلَّذِي تَسۡتَعۡجِلُونَ¦27:73:1:وَإِنَّ رَبَّكَ\nT;0;27:73:2:لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَشۡكُرُونَ¦27:74:1:وَإِنَّ\nT;0;27:74:2:رَبَّكَ لَيَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا يُعۡلِنُونَ¦27:75:1:وَمَا مِنۡ غَآئِبَةࣲ\nT;0;27:75:2:فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِلَّا فِي كِتَٰبࣲ مُّبِينٍ¦27:76:1:إِنَّ هَٰذَا ٱلۡقُرۡءَانَ\nT;0;27:76:2:يَقُصُّ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ أَكۡثَرَ ٱلَّذِي هُمۡ فِيهِ يَخۡتَلِفُونَ',
  '20;39;0;154\nT;0;27:77:3:وَإِنَّهُۥ لَهُدࣰى وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِينَ¦27:78:1:إِنَّ رَبَّكَ يَقۡضِي بَيۡنَهُم\nT;0;27:78:2:بِحُكۡمِهِۦۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡعَلِيمُ¦27:79:1:فَتَوَكَّلۡ عَلَى ٱللَّهِۖ إِنَّكَ عَلَى\nT;0;27:79:2:ٱلۡحَقِّ ٱلۡمُبِينِ¦27:80:1:إِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَآءَ\nT;0;27:80:2:إِذَا وَلَّوۡاْ مُدۡبِرِينَ¦27:81:1:وَمَآ أَنتَ بِهَٰدِي ٱلۡعُمۡيِ عَن ضَلَٰلَتِهِمۡۖ إِن\nT;0;27:81:2:تُسۡمِعُ إِلَّا مَن يُؤۡمِنُ بِـَٔايَٰتِنَا فَهُم مُّسۡلِمُونَ¦27:82:1:۞ وَإِذَا وَقَعَ\nT;0;27:82:0:ٱلۡقَوۡلُ عَلَيۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَآبَّةࣰ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ\nT;0;27:82:2:ٱلنَّاسَ كَانُواْ بِـَٔايَٰتِنَا لَا يُوقِنُونَ¦27:83:1:وَيَوۡمَ نَحۡشُرُ مِن كُلِّ أُمَّةࣲ\nT;0;27:83:2:فَوۡجࣰا مِّمَّن يُكَذِّبُ بِـَٔايَٰتِنَا فَهُمۡ يُوزَعُونَ¦27:84:1:حَتَّىٰٓ إِذَا جَآءُو قَالَ\nT;0;27:84:2:أَكَذَّبۡتُم بِـَٔايَٰتِي وَلَمۡ تُحِيطُواْ بِهَا عِلۡمًا أَمَّاذَا كُنتُمۡ تَعۡمَلُونَ\nT;0;27:85:3:وَوَقَعَ ٱلۡقَوۡلُ عَلَيۡهِم بِمَا ظَلَمُواْ فَهُمۡ لَا يَنطِقُونَ¦27:86:1:أَلَمۡ\nT;0;27:86:0:يَرَوۡاْ أَنَّا جَعَلۡنَا ٱلَّيۡلَ لِيَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِي\nT;0;27:86:2:ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يُؤۡمِنُونَ¦27:87:1:وَيَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَفَزِعَ مَن\nT;0;27:87:0:فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ\nT;0;27:87:2:دَٰخِرِينَ¦27:88:1:وَتَرَى ٱلۡجِبَالَ تَحۡسَبُهَا جَامِدَةࣰ وَهِيَ تَمُرُّ مَرَّ ٱلسَّحَابِۚ\nT;0;27:88:2:صُنۡعَ ٱللَّهِ ٱلَّذِيٓ أَتۡقَنَ كُلَّ شَيۡءٍۚ إِنَّهُۥ خَبِيرُۢ بِمَا تَفۡعَلُونَ',
  '20;39;1;\nT;0;27:89:3:مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرࣱ مِّنۡهَا وَهُم مِّن فَزَعࣲ يَوۡمَئِذٍ ءَامِنُونَ\nT;0;27:90:1:وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِي ٱلنَّارِ هَلۡ تُجۡزَوۡنَ إِلَّا\nT;0;27:90:2:مَا كُنتُمۡ تَعۡمَلُونَ¦27:91:1:إِنَّمَآ أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَٰذِهِ ٱلۡبَلۡدَةِ ٱلَّذِي\nT;0;27:91:2:حَرَّمَهَا وَلَهُۥ كُلُّ شَيۡءࣲۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِينَ\nT;0;27:92:1:وَأَنۡ أَتۡلُوَاْ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ\nT;0;27:92:2:وَمَن ضَلَّ فَقُلۡ إِنَّمَآ أَنَا۠ مِنَ ٱلۡمُنذِرِينَ¦27:93:1:وَقُلِ ٱلۡحَمۡدُ لِلَّهِ\nT;2;27:93:2:سَيُرِيكُمۡ ءَايَٰتِهِۦ فَتَعۡرِفُونَهَاۚ وَمَا رَبُّكَ بِغَٰفِلٍ عَمَّا تَعۡمَلُونَ\nH;28\nB;28\nT;0;28:1:3:طسٓمٓ¦28:2:3:تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ ٱلۡمُبِينِ¦28:3:1:نَتۡلُواْ عَلَيۡكَ\nT;0;28:3:2:مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمࣲ يُؤۡمِنُونَ¦28:4:1:إِنَّ\nT;0;28:4:0:فِرۡعَوۡنَ عَلَا فِي ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِيَعࣰا يَسۡتَضۡعِفُ\nT;0;28:4:0:طَآئِفَةࣰ مِّنۡهُمۡ يُذَبِّحُ أَبۡنَآءَهُمۡ وَيَسۡتَحۡيِۦ نِسَآءَهُمۡۚ إِنَّهُۥ كَانَ\nT;0;28:4:2:مِنَ ٱلۡمُفۡسِدِينَ¦28:5:1:وَنُرِيدُ أَن نَّمُنَّ عَلَى ٱلَّذِينَ ٱسۡتُضۡعِفُواْ\nT;0;28:5:2:فِي ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَئِمَّةࣰ وَنَجۡعَلَهُمُ ٱلۡوَٰرِثِينَ',
  '20;39;1;155\nT;0;28:6:1:وَنُمَكِّنَ لَهُمۡ فِي ٱلۡأَرۡضِ وَنُرِيَ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا\nT;0;28:6:2:مِنۡهُم مَّا كَانُواْ يَحۡذَرُونَ¦28:7:1:وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ\nT;0;28:7:0:أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي\nT;0;28:7:2:وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ\nT;0;28:8:1:فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوࣰّا وَحَزَنًاۗ إِنَّ\nT;0;28:8:2:فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ\nT;0;28:9:1:وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنࣲ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ\nT;0;28:9:2:عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدࣰا وَهُمۡ لَا يَشۡعُرُونَ\nT;0;28:10:1:وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِي بِهِۦ لَوۡلَآ\nT;0;28:10:2:أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِينَ¦28:11:1:وَقَالَتۡ\nT;0;28:11:2:لِأُخۡتِهِۦ قُصِّيهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبࣲ وَهُمۡ لَا يَشۡعُرُونَ\nT;0;28:12:1:۞ وَحَرَّمۡنَا عَلَيۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ\nT;0;28:12:2:عَلَىٰٓ أَهۡلِ بَيۡتࣲ يَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَٰصِحُونَ\nT;0;28:13:1:فَرَدَدۡنَٰهُ إِلَىٰٓ أُمِّهِۦ كَيۡ تَقَرَّ عَيۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ\nT;0;28:13:2:أَنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ',
  '20;39;2;\nT;0;28:14:1:وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰٓ ءَاتَيۡنَٰهُ حُكۡمࣰا وَعِلۡمࣰاۚ وَكَذَٰلِكَ نَجۡزِي\nT;0;28:14:2:ٱلۡمُحۡسِنِينَ¦28:15:1:وَدَخَلَ ٱلۡمَدِينَةَ عَلَىٰ حِينِ غَفۡلَةࣲ مِّنۡ أَهۡلِهَا\nT;0;28:15:0:فَوَجَدَ فِيهَا رَجُلَيۡنِ يَقۡتَتِلَانِ هَٰذَا مِن شِيعَتِهِۦ وَهَٰذَا مِنۡ عَدُوِّهِۦۖ\nT;0;28:15:0:فَٱسۡتَغَٰثَهُ ٱلَّذِي مِن شِيعَتِهِۦ عَلَى ٱلَّذِي مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ\nT;0;28:15:0:مُوسَىٰ فَقَضَىٰ عَلَيۡهِۖ قَالَ هَٰذَا مِنۡ عَمَلِ ٱلشَّيۡطَٰنِۖ إِنَّهُۥ عَدُوࣱّ مُّضِلࣱّ\nT;0;28:15:2:مُّبِينࣱ¦28:16:1:قَالَ رَبِّ إِنِّي ظَلَمۡتُ نَفۡسِي فَٱغۡفِرۡ لِي فَغَفَرَ لَهُۥٓۚ إِنَّهُۥ\nT;0;28:16:2:هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ¦28:17:1:قَالَ رَبِّ بِمَآ أَنۡعَمۡتَ عَلَيَّ فَلَنۡ أَكُونَ\nT;0;28:17:2:ظَهِيرࣰا لِّلۡمُجۡرِمِينَ¦28:18:1:فَأَصۡبَحَ فِي ٱلۡمَدِينَةِ خَآئِفࣰا يَتَرَقَّبُ فَإِذَا\nT;0;28:18:0:ٱلَّذِي ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ يَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰٓ إِنَّكَ لَغَوِيࣱّ\nT;0;28:18:2:مُّبِينࣱ¦28:19:1:فَلَمَّآ أَنۡ أَرَادَ أَن يَبۡطِشَ بِٱلَّذِي هُوَ عَدُوࣱّ لَّهُمَا قَالَ\nT;0;28:19:0:يَٰمُوسَىٰٓ أَتُرِيدُ أَن تَقۡتُلَنِي كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِيدُ\nT;0;28:19:0:إِلَّآ أَن تَكُونَ جَبَّارࣰا فِي ٱلۡأَرۡضِ وَمَا تُرِيدُ أَن تَكُونَ مِنَ\nT;0;28:19:2:ٱلۡمُصۡلِحِينَ¦28:20:1:وَجَآءَ رَجُلࣱ مِّنۡ أَقۡصَا ٱلۡمَدِينَةِ يَسۡعَىٰ قَالَ يَٰمُوسَىٰٓ\nT;0;28:20:2:إِنَّ ٱلۡمَلَأَ يَأۡتَمِرُونَ بِكَ لِيَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّي لَكَ مِنَ ٱلنَّٰصِحِينَ\nT;0;28:21:3:فَخَرَجَ مِنۡهَا خَآئِفࣰا يَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِي مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ',
  '20;39;2;\nT;0;28:22:1:وَلَمَّا تَوَجَّهَ تِلۡقَآءَ مَدۡيَنَ قَالَ عَسَىٰ رَبِّيٓ أَن يَهۡدِيَنِي سَوَآءَ\nT;0;28:22:2:ٱلسَّبِيلِ¦28:23:1:وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةࣰ مِّنَ\nT;0;28:23:0:ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ\nT;0;28:23:0:مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا\nT;0;28:23:2:شَيۡخࣱ كَبِيرࣱ¦28:24:1:فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ\nT;0;28:24:2:رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرࣲ فَقِيرࣱ¦28:25:1:فَجَآءَتۡهُ إِحۡدَىٰهُمَا\nT;0;28:25:0:تَمۡشِي عَلَى ٱسۡتِحۡيَآءࣲ قَالَتۡ إِنَّ أَبِي يَدۡعُوكَ لِيَجۡزِيَكَ\nT;0;28:25:0:أَجۡرَ مَا سَقَيۡتَ لَنَاۚ فَلَمَّا جَآءَهُۥ وَقَصَّ عَلَيۡهِ ٱلۡقَصَصَ قَالَ\nT;0;28:25:2:لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ¦28:26:1:قَالَتۡ إِحۡدَىٰهُمَا\nT;0;28:26:2:يَٰٓأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَيۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِيُّ ٱلۡأَمِينُ\nT;0;28:27:1:قَالَ إِنِّيٓ أُرِيدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَيَّ هَٰتَيۡنِ عَلَىٰٓ أَن\nT;0;28:27:0:تَأۡجُرَنِي ثَمَٰنِيَ حِجَجࣲۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرࣰا فَمِنۡ عِندِكَۖ\nT;0;28:27:0:وَمَآ أُرِيدُ أَنۡ أَشُقَّ عَلَيۡكَۚ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ\nT;0;28:27:2:ٱلصَّٰلِحِينَ¦28:28:1:قَالَ ذَٰلِكَ بَيۡنِي وَبَيۡنَكَۖ أَيَّمَا ٱلۡأَجَلَيۡنِ\nT;0;28:28:2:قَضَيۡتُ فَلَا عُدۡوَٰنَ عَلَيَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِيلࣱ',
  '20;39;3;156\nT;0;28:29:1:۞ فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ\nT;0;28:29:0:ٱلطُّورِ نَارࣰاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارࣰا لَّعَلِّيٓ ءَاتِيكُم\nT;0;28:29:2:مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةࣲ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ\nT;0;28:30:1:فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ\nT;0;28:30:0:ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ\nT;0;28:30:2:ٱلۡعَٰلَمِينَ¦28:31:1:وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا\nT;0;28:31:0:جَآنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ يُعَقِّبۡۚ يَٰمُوسَىٰٓ أَقۡبِلۡ وَلَا تَخَفۡۖ\nT;0;28:31:2:إِنَّكَ مِنَ ٱلۡأٓمِنِينَ¦28:32:1:ٱسۡلُكۡ يَدَكَ فِي جَيۡبِكَ تَخۡرُجۡ\nT;0;28:32:0:بَيۡضَآءَ مِنۡ غَيۡرِ سُوٓءࣲ وَٱضۡمُمۡ إِلَيۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ\nT;0;28:32:0:فَذَٰنِكَ بُرۡهَٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦٓۚ إِنَّهُمۡ\nT;0;28:32:2:كَانُواْ قَوۡمࣰا فَٰسِقِينَ¦28:33:1:قَالَ رَبِّ إِنِّي قَتَلۡتُ مِنۡهُمۡ نَفۡسࣰا\nT;0;28:33:2:فَأَخَافُ أَن يَقۡتُلُونِ¦28:34:1:وَأَخِي هَٰرُونُ هُوَ أَفۡصَحُ مِنِّي لِسَانࣰا\nT;0;28:34:2:فَأَرۡسِلۡهُ مَعِيَ رِدۡءࣰا يُصَدِّقُنِيٓۖ إِنِّيٓ أَخَافُ أَن يُكَذِّبُونِ\nT;0;28:35:1:قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنࣰا فَلَا\nT;0;28:35:2:يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ',
  '20;39;3;\nT;0;28:36:1:فَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتࣲ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرࣱ\nT;0;28:36:2:مُّفۡتَرࣰى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ\nT;0;28:37:1:وَقَالَ مُوسَىٰ رَبِّيٓ أَعۡلَمُ بِمَن جَآءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن\nT;0;28:37:2:تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ\nT;0;28:38:1:وَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ\nT;0;28:38:0:غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحࣰا لَّعَلِّيٓ\nT;0;28:38:2:أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ\nT;0;28:39:1:وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَظَنُّوٓاْ\nT;0;28:39:2:أَنَّهُمۡ إِلَيۡنَا لَا يُرۡجَعُونَ¦28:40:1:فَأَخَذۡنَٰهُ وَجُنُودَهُۥ فَنَبَذۡنَٰهُمۡ\nT;0;28:40:2:فِي ٱلۡيَمِّۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ\nT;0;28:41:1:وَجَعَلۡنَٰهُمۡ أَئِمَّةࣰ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ\nT;0;28:41:2:لَا يُنصَرُونَ¦28:42:1:وَأَتۡبَعۡنَٰهُمۡ فِي هَٰذِهِ ٱلدُّنۡيَا لَعۡنَةࣰۖ\nT;0;28:42:2:وَيَوۡمَ ٱلۡقِيَٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِينَ¦28:43:1:وَلَقَدۡ ءَاتَيۡنَا\nT;0;28:43:0:مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ\nT;0;28:43:2:بَصَآئِرَ لِلنَّاسِ وَهُدࣰى وَرَحۡمَةࣰ لَّعَلَّهُمۡ يَتَذَكَّرُونَ',
  '20;39;3;\nT;0;28:44:1:وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ إِذۡ قَضَيۡنَآ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ\nT;0;28:44:2:مِنَ ٱلشَّٰهِدِينَ¦28:45:1:وَلَٰكِنَّآ أَنشَأۡنَا قُرُونࣰا فَتَطَاوَلَ عَلَيۡهِمُ\nT;0;28:45:0:ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيࣰا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ\nT;0;28:45:2:ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ¦28:46:1:وَمَا كُنتَ بِجَانِبِ\nT;0;28:46:0:ٱلطُّورِ إِذۡ نَادَيۡنَا وَلَٰكِن رَّحۡمَةࣰ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا\nT;0;28:46:2:مَّآ أَتَىٰهُم مِّن نَّذِيرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ يَتَذَكَّرُونَ\nT;0;28:47:1:وَلَوۡلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ فَيَقُولُواْ\nT;0;28:47:0:رَبَّنَا لَوۡلَآ أَرۡسَلۡتَ إِلَيۡنَا رَسُولࣰا فَنَتَّبِعَ ءَايَٰتِكَ وَنَكُونَ\nT;0;28:47:2:مِنَ ٱلۡمُؤۡمِنِينَ¦28:48:1:فَلَمَّا جَآءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُواْ\nT;0;28:48:0:لَوۡلَآ أُوتِيَ مِثۡلَ مَآ أُوتِيَ مُوسَىٰٓۚ أَوَلَمۡ يَكۡفُرُواْ بِمَآ أُوتِيَ\nT;0;28:48:2:مُوسَىٰ مِن قَبۡلُۖ قَالُواْ سِحۡرَانِ تَظَٰهَرَا وَقَالُوٓاْ إِنَّا بِكُلࣲّ كَٰفِرُونَ\nT;0;28:49:1:قُلۡ فَأۡتُواْ بِكِتَٰبࣲ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَآ أَتَّبِعۡهُ\nT;0;28:49:2:إِن كُنتُمۡ صَٰدِقِينَ¦28:50:1:فَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ\nT;0;28:50:0:أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ\nT;0;28:50:2:هُدࣰى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ',
  '20;40;0;157\nT;0;28:51:3:۞ وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ¦28:52:1:ٱلَّذِينَ\nT;0;28:52:2:ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ يُؤۡمِنُونَ¦28:53:1:وَإِذَا يُتۡلَىٰ\nT;0;28:53:0:عَلَيۡهِمۡ قَالُوٓاْ ءَامَنَّا بِهِۦٓ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَآ إِنَّا كُنَّا مِن قَبۡلِهِۦ\nT;0;28:53:2:مُسۡلِمِينَ¦28:54:1:أُوْلَٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ\nT;0;28:54:2:بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ¦28:55:1:وَإِذَا سَمِعُواْ\nT;0;28:55:0:ٱللَّغۡوَ أَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ\nT;0;28:55:2:عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ¦28:56:1:إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ\nT;0;28:56:2:وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ\nT;0;28:57:1:وَقَالُوٓاْ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَلَمۡ\nT;0;28:57:0:نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنࣰا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءࣲ رِّزۡقࣰا\nT;0;28:57:2:مِّن لَّدُنَّا وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ¦28:58:1:وَكَمۡ أَهۡلَكۡنَا مِن\nT;0;28:58:0:قَرۡيَةِۭ بَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ\nT;0;28:58:2:بَعۡدِهِمۡ إِلَّا قَلِيلࣰاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ¦28:59:1:وَمَا كَانَ رَبُّكَ\nT;0;28:59:0:مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ يَبۡعَثَ فِيٓ أُمِّهَا رَسُولࣰا يَتۡلُواْ عَلَيۡهِمۡ\nT;0;28:59:2:ءَايَٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِي ٱلۡقُرَىٰٓ إِلَّا وَأَهۡلُهَا ظَٰلِمُونَ',
  '20;40;0;\nT;0;28:60:1:وَمَآ أُوتِيتُم مِّن شَيۡءࣲ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ\nT;0;28:60:2:ٱللَّهِ خَيۡرࣱ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ¦28:61:1:أَفَمَن وَعَدۡنَٰهُ وَعۡدًا حَسَنࣰا\nT;0;28:61:0:فَهُوَ لَٰقِيهِ كَمَن مَّتَّعۡنَٰهُ مَتَٰعَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا ثُمَّ هُوَ يَوۡمَ ٱلۡقِيَٰمَةِ\nT;0;28:61:2:مِنَ ٱلۡمُحۡضَرِينَ¦28:62:1:وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ\nT;0;28:62:2:ٱلَّذِينَ كُنتُمۡ تَزۡعُمُونَ¦28:63:1:قَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا\nT;0;28:63:0:هَٰٓؤُلَآءِ ٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ\nT;0;28:63:2:مَا كَانُوٓاْ إِيَّانَا يَعۡبُدُونَ¦28:64:1:وَقِيلَ ٱدۡعُواْ شُرَكَآءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ\nT;0;28:64:2:يَسۡتَجِيبُواْ لَهُمۡ وَرَأَوُاْ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُواْ يَهۡتَدُونَ\nT;0;28:65:3:وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ¦28:66:1:فَعَمِيَتۡ\nT;0;28:66:2:عَلَيۡهِمُ ٱلۡأَنۢبَآءُ يَوۡمَئِذࣲ فَهُمۡ لَا يَتَسَآءَلُونَ¦28:67:1:فَأَمَّا مَن تَابَ\nT;0;28:67:2:وَءَامَنَ وَعَمِلَ صَٰلِحࣰا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ\nT;0;28:68:1:وَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ سُبۡحَٰنَ\nT;0;28:68:2:ٱللَّهِ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ¦28:69:1:وَرَبُّكَ يَعۡلَمُ مَا تُكِنُّ\nT;0;28:69:2:صُدُورُهُمۡ وَمَا يُعۡلِنُونَ¦28:70:1:وَهُوَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ\nT;0;28:70:2:ٱلۡحَمۡدُ فِي ٱلۡأُولَىٰ وَٱلۡأٓخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ',
  '20;40;0;158\nT;0;28:71:1:قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ\nT;0;28:71:2:ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ\nT;0;28:72:1:قُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ\nT;0;28:72:0:يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِلَيۡلࣲ تَسۡكُنُونَ\nT;0;28:72:2:فِيهِۚ أَفَلَا تُبۡصِرُونَ¦28:73:1:وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ\nT;0;28:73:0:وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ\nT;0;28:73:2:تَشۡكُرُونَ¦28:74:1:وَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ\nT;0;28:74:2:كُنتُمۡ تَزۡعُمُونَ¦28:75:1:وَنَزَعۡنَا مِن كُلِّ أُمَّةࣲ شَهِيدࣰا فَقُلۡنَا\nT;0;28:75:0:هَاتُواْ بُرۡهَٰنَكُمۡ فَعَلِمُوٓاْ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم\nT;0;28:75:2:مَّا كَانُواْ يَفۡتَرُونَ¦28:76:1:۞ إِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ\nT;0;28:76:0:فَبَغَىٰ عَلَيۡهِمۡۖ وَءَاتَيۡنَٰهُ مِنَ ٱلۡكُنُوزِ مَآ إِنَّ مَفَاتِحَهُۥ لَتَنُوٓأُ\nT;0;28:76:0:بِٱلۡعُصۡبَةِ أُوْلِي ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ\nT;0;28:76:2:لَا يُحِبُّ ٱلۡفَرِحِينَ¦28:77:1:وَٱبۡتَغِ فِيمَآ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡأٓخِرَةَۖ\nT;0;28:77:0:وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ\nT;0;28:77:2:وَلَا تَبۡغِ ٱلۡفَسَادَ فِي ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُفۡسِدِينَ',
  '20;40;1;\nT;0;28:78:1:قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَلَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ\nT;0;28:78:0:مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةࣰ وَأَكۡثَرُ جَمۡعࣰاۚ\nT;0;28:78:2:وَلَا يُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ¦28:79:1:فَخَرَجَ عَلَىٰ قَوۡمِهِۦ\nT;0;28:79:0:فِي زِينَتِهِۦۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا يَٰلَيۡتَ لَنَا\nT;0;28:79:2:مِثۡلَ مَآ أُوتِيَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمࣲ¦28:80:1:وَقَالَ ٱلَّذِينَ\nT;0;28:80:0:أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرࣱ لِّمَنۡ ءَامَنَ وَعَمِلَ\nT;0;28:80:2:صَٰلِحࣰاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ¦28:81:1:فَخَسَفۡنَا بِهِۦ\nT;0;28:81:0:وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةࣲ يَنصُرُونَهُۥ مِن دُونِ\nT;0;28:81:2:ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِينَ¦28:82:1:وَأَصۡبَحَ ٱلَّذِينَ تَمَنَّوۡاْ\nT;0;28:82:0:مَكَانَهُۥ بِٱلۡأَمۡسِ يَقُولُونَ وَيۡكَأَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن\nT;0;28:82:0:يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُۖ لَوۡلَآ أَن مَّنَّ ٱللَّهُ عَلَيۡنَا لَخَسَفَ بِنَاۖ\nT;0;28:82:2:وَيۡكَأَنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ¦28:83:1:تِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ\nT;0;28:83:2:لَا يُرِيدُونَ عُلُوࣰّا فِي ٱلۡأَرۡضِ وَلَا فَسَادࣰاۚ وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ\nT;0;28:84:1:مَن جَآءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَيۡرࣱ مِّنۡهَاۖ وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا\nT;0;28:84:2:يُجۡزَى ٱلَّذِينَ عَمِلُواْ ٱلسَّيِّـَٔاتِ إِلَّا مَا كَانُواْ يَعۡمَلُونَ',
  '20;40;1;159\nT;0;28:85:1:إِنَّ ٱلَّذِي فَرَضَ عَلَيۡكَ ٱلۡقُرۡءَانَ لَرَآدُّكَ إِلَىٰ مَعَادࣲۚ قُل رَّبِّيٓ\nT;0;28:85:2:أَعۡلَمُ مَن جَآءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِي ضَلَٰلࣲ مُّبِينࣲ¦28:86:1:وَمَا كُنتَ\nT;0;28:86:0:تَرۡجُوٓاْ أَن يُلۡقَىٰٓ إِلَيۡكَ ٱلۡكِتَٰبُ إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَۖ فَلَا\nT;0;28:86:2:تَكُونَنَّ ظَهِيرࣰا لِّلۡكَٰفِرِينَ¦28:87:1:وَلَا يَصُدُّنَّكَ عَنۡ ءَايَٰتِ\nT;0;28:87:0:ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَيۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ\nT;0;28:87:2:ٱلۡمُشۡرِكِينَ¦28:88:1:وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۘ لَآ إِلَٰهَ إِلَّا هُوَۚ\nT;2;28:88:2:كُلُّ شَيۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَيۡهِ تُرۡجَعُونَ\nH;29\nB;29\nT;0;29:1:3:الٓمٓ¦29:2:1:أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ\nT;0;29:2:2:لَا يُفۡتَنُونَ¦29:3:1:وَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ\nT;0;29:3:2:صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ¦29:4:1:أَمۡ حَسِبَ ٱلَّذِينَ يَعۡمَلُونَ\nT;0;29:4:2:ٱلسَّيِّـَٔاتِ أَن يَسۡبِقُونَاۚ سَآءَ مَا يَحۡكُمُونَ¦29:5:1:مَن كَانَ يَرۡجُواْ\nT;0;29:5:2:لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَأٓتࣲۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ¦29:6:1:وَمَن\nT;0;29:6:2:جَٰهَدَ فَإِنَّمَا يُجَٰهِدُ لِنَفۡسِهِۦٓۚ إِنَّ ٱللَّهَ لَغَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ',
  '20;40;2;\nT;0;29:7:1:وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ\nT;0;29:7:2:وَلَنَجۡزِيَنَّهُمۡ أَحۡسَنَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ¦29:8:1:وَوَصَّيۡنَا ٱلۡإِنسَٰنَ\nT;0;29:8:0:بِوَٰلِدَيۡهِ حُسۡنࣰاۖ وَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمࣱ\nT;0;29:8:2:فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\nT;0;29:9:3:وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُدۡخِلَنَّهُمۡ فِي ٱلصَّٰلِحِينَ\nT;0;29:10:1:وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِيَ فِي ٱللَّهِ جَعَلَ\nT;0;29:10:0:فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَئِن جَآءَ نَصۡرࣱ مِّن رَّبِّكَ لَيَقُولُنَّ\nT;0;29:10:2:إِنَّا كُنَّا مَعَكُمۡۚ أَوَلَيۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِي صُدُورِ ٱلۡعَٰلَمِينَ\nT;0;29:11:3:وَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَلَيَعۡلَمَنَّ ٱلۡمُنَٰفِقِينَ\nT;0;29:12:1:وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ ٱتَّبِعُواْ سَبِيلَنَا\nT;0;29:12:0:وَلۡنَحۡمِلۡ خَطَٰيَٰكُمۡ وَمَا هُم بِحَٰمِلِينَ مِنۡ خَطَٰيَٰهُم مِّن\nT;0;29:12:2:شَيۡءٍۖ إِنَّهُمۡ لَكَٰذِبُونَ¦29:13:1:وَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالࣰا مَّعَ\nT;0;29:13:2:أَثۡقَالِهِمۡۖ وَلَيُسۡـَٔلُنَّ يَوۡمَ ٱلۡقِيَٰمَةِ عَمَّا كَانُواْ يَفۡتَرُونَ\nT;0;29:14:1:وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ\nT;0;29:14:2:إِلَّا خَمۡسِينَ عَامࣰا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ',
  '20;40;2;\nT;0;29:15:3:فَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةࣰ لِّلۡعَٰلَمِينَ\nT;0;29:16:1:وَإِبۡرَٰهِيمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُۖ ذَٰلِكُمۡ\nT;0;29:16:2:خَيۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ¦29:17:1:إِنَّمَا تَعۡبُدُونَ مِن\nT;0;29:17:0:دُونِ ٱللَّهِ أَوۡثَٰنࣰا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِينَ تَعۡبُدُونَ مِن\nT;0;29:17:0:دُونِ ٱللَّهِ لَا يَمۡلِكُونَ لَكُمۡ رِزۡقࣰا فَٱبۡتَغُواْ عِندَ ٱللَّهِ ٱلرِّزۡقَ\nT;0;29:17:2:وَٱعۡبُدُوهُ وَٱشۡكُرُواْ لَهُۥٓۖ إِلَيۡهِ تُرۡجَعُونَ¦29:18:1:وَإِن تُكَذِّبُواْ\nT;0;29:18:0:فَقَدۡ كَذَّبَ أُمَمࣱ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَٰغُ\nT;0;29:18:2:ٱلۡمُبِينُ¦29:19:1:أَوَلَمۡ يَرَوۡاْ كَيۡفَ يُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ\nT;0;29:19:2:يُعِيدُهُۥٓۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣱ¦29:20:1:قُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ\nT;0;29:20:0:فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشۡأَةَ ٱلۡأٓخِرَةَۚ\nT;0;29:20:2:إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ¦29:21:1:يُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ\nT;0;29:21:2:مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ¦29:22:1:وَمَآ أَنتُم بِمُعۡجِزِينَ فِي\nT;0;29:22:0:ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن\nT;0;29:22:2:وَلِيࣲّ وَلَا نَصِيرࣲ¦29:23:1:وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ\nT;0;29:23:2:أُوْلَٰٓئِكَ يَئِسُواْ مِن رَّحۡمَتِي وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمࣱ',
  '20;40;2;160\nT;0;29:24:1:فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ\nT;0;29:24:2:فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يُؤۡمِنُونَ\nT;0;29:25:1:وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنࣰا مَّوَدَّةَ بَيۡنِكُمۡ\nT;0;29:25:0:فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم\nT;0;29:25:0:بِبَعۡضࣲ وَيَلۡعَنُ بَعۡضُكُم بَعۡضࣰا وَمَأۡوَىٰكُمُ ٱلنَّارُ\nT;0;29:25:2:وَمَا لَكُم مِّن نَّٰصِرِينَ¦29:26:1:۞ فَـَٔامَنَ لَهُۥ لُوطࣱۘ وَقَالَ\nT;0;29:26:2:إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ\nT;0;29:27:1:وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ وَجَعَلۡنَا فِي ذُرِّيَّتِهِ\nT;0;29:27:0:ٱلنُّبُوَّةَ وَٱلۡكِتَٰبَ وَءَاتَيۡنَٰهُ أَجۡرَهُۥ فِي ٱلدُّنۡيَاۖ وَإِنَّهُۥ\nT;0;29:27:2:فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ¦29:28:1:وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ\nT;0;29:28:0:إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدࣲ\nT;0;29:28:2:مِّنَ ٱلۡعَٰلَمِينَ¦29:29:1:أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ\nT;0;29:29:0:ٱلسَّبِيلَ وَتَأۡتُونَ فِي نَادِيكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ\nT;0;29:29:0:قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ\nT;0;29:29:2:ٱلصَّٰدِقِينَ¦29:30:3:قَالَ رَبِّ ٱنصُرۡنِي عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِينَ',
  '20;40;3;\nT;0;29:31:1:وَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ\nT;0;29:31:2:أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ\nT;0;29:32:1:قَالَ إِنَّ فِيهَا لُوطࣰاۚ قَالُواْ نَحۡنُ أَعۡلَمُ بِمَن فِيهَاۖ لَنُنَجِّيَنَّهُۥ\nT;0;29:32:2:وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ¦29:33:1:وَلَمَّآ\nT;0;29:33:0:أَن جَآءَتۡ رُسُلُنَا لُوطࣰا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعࣰاۖ\nT;0;29:33:0:وَقَالُواْ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا\nT;0;29:33:2:ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ¦29:34:1:إِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ\nT;0;29:34:2:هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزࣰا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ\nT;0;29:35:3:وَلَقَد تَّرَكۡنَا مِنۡهَآ ءَايَةَۢ بَيِّنَةࣰ لِّقَوۡمࣲ يَعۡقِلُونَ\nT;0;29:36:1:وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبࣰا فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ\nT;0;29:36:2:وَٱرۡجُواْ ٱلۡيَوۡمَ ٱلۡأٓخِرَ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ\nT;0;29:37:1:فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ\nT;0;29:37:2:جَٰثِمِينَ¦29:38:1:وَعَادࣰا وَثَمُودَاْ وَقَد تَّبَيَّنَ لَكُم\nT;0;29:38:0:مِّن مَّسَٰكِنِهِمۡۖ وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ\nT;0;29:38:2:فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ',
  '20;40;3;\nT;0;29:39:1:وَقَٰرُونَ وَفِرۡعَوۡنَ وَهَٰمَٰنَۖ وَلَقَدۡ جَآءَهُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ\nT;0;29:39:2:فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ وَمَا كَانُواْ سَٰبِقِينَ\nT;0;29:40:1:فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَيۡهِ حَاصِبࣰا\nT;0;29:40:0:وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّيۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ\nT;0;29:40:0:ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ\nT;0;29:40:2:وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ¦29:41:1:مَثَلُ ٱلَّذِينَ\nT;0;29:41:0:ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ\nT;0;29:41:0:ٱتَّخَذَتۡ بَيۡتࣰاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ\nT;0;29:41:2:لَوۡ كَانُواْ يَعۡلَمُونَ¦29:42:1:إِنَّ ٱللَّهَ يَعۡلَمُ مَا يَدۡعُونَ مِن\nT;0;29:42:2:دُونِهِۦ مِن شَيۡءࣲۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ¦29:43:1:وَتِلۡكَ\nT;0;29:43:2:ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ\nT;0;29:44:1:خَلَقَ ٱللَّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِي ذَٰلِكَ\nT;0;29:44:2:لَأٓيَةࣰ لِّلۡمُؤۡمِنِينَ¦29:45:1:ٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ\nT;0;29:45:0:وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ\nT;0;29:45:2:وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ يَعۡلَمُ مَا تَصۡنَعُونَ',
  '21;41;0;161\nT;0;29:46:1:۞ وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا\nT;0;29:46:0:ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ\nT;0;29:46:2:إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدࣱ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ\nT;0;29:47:1:وَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ\nT;0;29:47:0:ٱلۡكِتَٰبَ يُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا\nT;0;29:47:2:يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ¦29:48:1:وَمَا كُنتَ تَتۡلُواْ مِن\nT;0;29:48:0:قَبۡلِهِۦ مِن كِتَٰبࣲ وَلَا تَخُطُّهُۥ بِيَمِينِكَۖ إِذࣰا لَّٱرۡتَابَ\nT;0;29:48:2:ٱلۡمُبۡطِلُونَ¦29:49:1:بَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتࣱ فِي صُدُورِ ٱلَّذِينَ\nT;0;29:49:2:أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ¦29:50:1:وَقَالُواْ\nT;0;29:50:0:لَوۡلَآ أُنزِلَ عَلَيۡهِ ءَايَٰتࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡأٓيَٰتُ عِندَ ٱللَّهِ\nT;0;29:50:2:وَإِنَّمَآ أَنَا۠ نَذِيرࣱ مُّبِينٌ¦29:51:1:أَوَلَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ\nT;0;29:51:0:ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةࣰ وَذِكۡرَىٰ\nT;0;29:51:2:لِقَوۡمࣲ يُؤۡمِنُونَ¦29:52:1:قُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ\nT;0;29:52:0:شَهِيدࣰاۖ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ ءَامَنُواْ\nT;0;29:52:2:بِٱلۡبَٰطِلِ وَكَفَرُواْ بِٱللَّهِ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ',
  '21;41;0;\nT;0;29:53:1:وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَآ أَجَلࣱ مُّسَمࣰّى لَّجَآءَهُمُ ٱلۡعَذَابُۚ\nT;0;29:53:2:وَلَيَأۡتِيَنَّهُم بَغۡتَةࣰ وَهُمۡ لَا يَشۡعُرُونَ¦29:54:1:يَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ\nT;0;29:54:2:وَإِنَّ جَهَنَّمَ لَمُحِيطَةُۢ بِٱلۡكَٰفِرِينَ¦29:55:1:يَوۡمَ يَغۡشَىٰهُمُ ٱلۡعَذَابُ\nT;0;29:55:2:مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَيَقُولُ ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ\nT;0;29:56:3:يَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةࣱ فَإِيَّٰيَ فَٱعۡبُدُونِ\nT;0;29:57:3:كُلُّ نَفۡسࣲ ذَآئِقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَيۡنَا تُرۡجَعُونَ¦29:58:1:وَٱلَّذِينَ\nT;0;29:58:0:ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفࣰا تَجۡرِي\nT;0;29:58:2:مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ¦29:59:1:ٱلَّذِينَ\nT;0;29:59:2:صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ¦29:60:1:وَكَأَيِّن مِّن دَآبَّةࣲ لَّا تَحۡمِلُ\nT;0;29:60:2:رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ¦29:61:1:وَلَئِن\nT;0;29:61:0:سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ\nT;0;29:61:2:لَيَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ يُؤۡفَكُونَ¦29:62:1:ٱللَّهُ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ\nT;0;29:62:2:عِبَادِهِۦ وَيَقۡدِرُ لَهُۥٓۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمࣱ¦29:63:1:وَلَئِن سَأَلۡتَهُم\nT;0;29:63:0:مَّن نَّزَّلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا\nT;0;29:63:2:لَيَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ',
  '21;41;0;162\nT;0;29:64:1:وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوࣱ وَلَعِبࣱۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ\nT;0;29:64:2:ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ¦29:65:1:فَإِذَا رَكِبُواْ فِي ٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ\nT;0;29:65:2:مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ\nT;0;29:66:3:لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡ وَلِيَتَمَتَّعُواْۚ فَسَوۡفَ يَعۡلَمُونَ\nT;0;29:67:1:أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنࣰا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ\nT;0;29:67:2:حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ\nT;0;29:68:1:وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَآءَهُۥٓۚ\nT;0;29:68:2:أَلَيۡسَ فِي جَهَنَّمَ مَثۡوࣰى لِّلۡكَٰفِرِينَ¦29:69:1:وَٱلَّذِينَ جَٰهَدُواْ\nT;2;29:69:2:فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ\nH;30\nB;30\nT;0;30:1:3:الٓمٓ¦30:2:3:غُلِبَتِ ٱلرُّومُ¦30:3:1:فِيٓ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ\nT;0;30:3:2:بَعۡدِ غَلَبِهِمۡ سَيَغۡلِبُونَ¦30:4:1:فِي بِضۡعِ سِنِينَۗ لِلَّهِ ٱلۡأَمۡرُ\nT;0;30:4:2:مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَيَوۡمَئِذࣲ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ\nT;0;30:5:3:بِنَصۡرِ ٱللَّهِۚ يَنصُرُ مَن يَشَآءُۖ وَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ',
];
